VALUES
  ('cpiuris2025::9b4853496f3a2d9c9104732849c52c78', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ordem de Penhora em Execução', '## Ordem de Penhora em Execução

A ordem de penhora em execução é estabelecida pelo CPC e prioriza a penhora em dinheiro, com exceção de bens que oferecem fiança bancária ou seguro garantia judicial.

### Conceitos
- **Fiança Bancária**: Garantia judicial oferecida por meio de aplicação em instituição financeira
- **Seguro Garantia Judicial**: Garantia judicial oferecida por meio de seguro
- **Penhora Prioritária**: Penhora em dinheiro é priorária, exceto em casos específicos

### Referências legais
- Art. 835, § 1º do CPC
- Art. 836, § 2º do CPC

### Dicas de prova
- Entenda a ordem de penhora em execução e suas exceções
- Identifique os bens que oferecem fiança bancária ou seguro garantia judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.314 (1)", "page_number": 314, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 835, § 1º do CPC", "Art. 836, § 2º do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T23:03:49.636427+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=314", "doc_key": "9b4853496f3a2d9c9104732849c52c78"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '9675333a8ac515a190693134f80db5302f3e96d018bdff4e2e32ee55ef0c04ef'),
  ('cpiuris2025::7e7c20c0355001d04d1184e6bc0b71d3', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Bens e direitos que podem ser objeto de penhora', '## Bens e direitos que podem ser objeto de penhora

Resumo objetivo: Bens móveis e imóveis possuem expressão econômica e admitem comercialização. Além disso, ações e quotas de sociedades simples e empresárias também são sujeitas à penhora.

### Conceitos
- **Bens móveis**: Possuem expressão econômica
- **Bens imóveis**: Possuem expressão econômica
- **Ações e quotas de sociedades**: Representam participação em determinada sociedade empresária

### Referências legais
- Art. 652 do Código de Processo Civil
- ...

### Jurisprudência
- AgRg no AREsp 380.735/DF
- ...

### Dicas de prova
- Distinção entre bens móveis e imóveis
- Entendimento da expressão econômica nos bens', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.314 (2)", "page_number": 314, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 652 do Código de Processo Civil", "..."], "jurisprudence": ["AgRg no AREsp 380.735/DF", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T23:04:20.494429+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=314", "doc_key": "7e7c20c0355001d04d1184e6bc0b71d3"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '3d2946ce99027097a394add3dff24b43bb1b49fe097107272ab970226a99dbe9'),
  ('cpiuris2025::6ab62ca2990e79abb1e40ae16b407243', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Requisitos para a Penhora em Execução Fiduciária', '## Requisitos para a Penhora em Execução Fiduciária

A penhora pode ser admitida em caráter excepcional e deve atender a vários requisitos, incluindo a inexistência de bens passíveis de garantir a execução ou que sejam de difícil alienação.

### Conceitos
- **Penhora**: Ato processual pelo qual os bens do executado são confiscados e depositados em depósito
- **Execução Fiduciária**: Forma de execução que visa proteger o direito do credor, sem necessariamente alienar o bem
- **Bens Passíveis de Garantia**: Bens que podem ser utilizados para garantir a execução ou que são de difícil alienação
- **Depósito dos Bens**: Ação de confinar os bens do executado em depósito, sob a responsabilidade do depositário

### Referências legais
- Art. 354 do CPC
- Art. 799, IV e I do CPC

### Dicas de prova
- Entenda a diferença entre penhora e execução fiduciária
- Conheça os requisitos formais para a formalização da penhora', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.315 (1)", "page_number": 315, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 354 do CPC", "Art. 799, IV e I do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:22:24.120632+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=315", "doc_key": "6ab62ca2990e79abb1e40ae16b407243"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6e9a2ff60479815d44069ba2ada6dac5ddf429950da511b2f2f7529d2ddf9a03'),
  ('cpiuris2025::1be1842852a73a348f08b6fc74b19f19', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Penhora de Bens', '## Penhora de Bens

A penhora de bens é formalizada por termo nos autos quando o exequente apresenta certidão da matrícula do bem, exceto em caso de veículos automotores.

### Conceitos
- **Penhora**: Procedimento pelo qual se busca garantir a execução de uma sentença
- **Bem**: Objeto da penhora
- **Certidão**: Documento que comprova a existência ou o estado de algo
- **Matrícula**: Registro do bem em cartório
- **Veículo automotor**: Vehículo que se move por meio de uma rota

### Referências legais
- Art. 845, § 1º, do CPC

### Jurisprudência
- REsp 953.977/DF

### Dicas de prova
- Pergunte sobre a formalidade da penhora
- Entenda a importância da certidão na penhora', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.315 (2)", "page_number": 315, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 845, § 1º, do CPC"], "jurisprudence": ["REsp 953.977/DF"], "confidence": 0.8, "extracted_at": "2026-05-28T02:22:48.272562+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=315", "doc_key": "1be1842852a73a348f08b6fc74b19f19"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '4bb61474c0e42c19422288cfc2976f7617ecb867654a7b8c7a69e4f3d4ba8dfc'),
  ('cpiuris2025::ab089a30b19c5c1d95c3f996b5893563', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução Fórmula e Penhora', '## Execução Fórmula e Penhora

Resumo sobre a execução por carta e penhora em diferentes situações.

### Conceitos
- **Penhora**: Ato de apreensão e depósito dos bens do executado
- **Execução Fórmula**: Método de execução que não envolve a penhora
- **Carta de Penhora**: Forma de penhora realizada por oficial de justiça sem comparecimento do executado
- **Averbação Eletrônica**: Realização de averbações de penhoras em bens imóveis e móveis por meio eletrônico
- **Registro Público**: O sistema que registra as penhoras e outros atos judiciais
- **Sistema Eletrônico**: Sistemas que permitem a realização de averbações on-line no registro público

### Referências legais
- Art. 845, § 1º do CPC
- Art. 846, caput e §§ 1º, 2º e 4º do CPC

### Dicas de prova
- Diferenciar entre penhora por termo e penhora por carta
- Entender a importância da averbação eletrônica no registro público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.316 (1)", "page_number": 316, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 845, § 1º do CPC", "Art. 846, caput e §§ 1º, 2º e 4º do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:23:29.691305+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=316", "doc_key": "ab089a30b19c5c1d95c3f996b5893563"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '2a996e685ef0bf7ec508aa4e83ed758788392653b547ca7c5e370f8a34d72963'),
  ('cpiuris2025::d5461fff471891a5d833da7074cafd80', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Nomeação e preferência do depositário', '## Nomeação e preferência do depositário

O artigo 840 do CPC estabelece ordem de preferência para a nomeação do depositário, priorizando bens em dinheiro e papéis de crédito, seguidos por imóveis urbanos e direitos aquisitivos sobre imóveis.

### Conceitos
- **depositário**: Pessoa responsável pela guarda dos bens do devedor
- **art. 840 do CPC**: Estabelece ordem de preferência para a nomeação do depositário
- **Banco do Brasil**: Instituição financeira priorizada para depósito de bens em dinheiro e papéis de crédito
- **Caixa Econômica Federal**: Instituição financeira priorizada para depósito de bens em dinheiro e papéis de crédito

### Referências legais
- Art. 840 do CPC

### Dicas de prova
- Entenda a ordem de preferência estabelecida no artigo 840 do CPC
- Conheça as instituições financeiras priorizadas para depósito de bens', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.316 (2)", "page_number": 316, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 840 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:24:09.077196+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=316", "doc_key": "d5461fff471891a5d833da7074cafd80"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '70900927b847ec041f8fa8e2a041a3636fc1ad22871b193b5e0407fb4a52f5da'),
  ('cpiuris2025::080f1248243e97a4c1c50b11e86a35e7', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Intimações em Execução', '## Intimações em Execução

A intimação é feita ao executado imediatamente após a penhora, de acordo com o art. 841 do CPC. Em caso de penhora na presença do executado, ele será considerado intimado. Caso contrário, a intimação será feita ao advogado ou à sociedade de advogados do executado, e se não houver advogado, pessoalmente.

### Conceitos
- **Intimação**: A notificação formal do executado após a penhora
- **Penhora**: O ato de sequestrar bens do executado para garantir o pagamento da dívida
- **Advogado**: O profissional jurídico que representa o executado em uma execução
- **CPC**: Código de Processo Civil

### Referências legais
- art. 841, caput, do CPC
- art. 841, § 1º, do CPC
- art. 841, § 2º, do CPC
- art. 842 do CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre intimação e notificação
- Conhecimento da penhora pelo executado
- Intimação ao advogado ou à sociedade de advogados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.317 (1)", "page_number": 317, "discipline": "Direito Processual Civil", "legal_refs": ["art. 841, caput, do CPC", "art. 841, § 1º, do CPC", "art. 841, § 2º, do CPC", "art. 842 do CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T02:24:46.346042+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=317", "doc_key": "080f1248243e97a4c1c50b11e86a35e7"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ad23231f621ebd1a43c9014e4b3089afb349a3c19ecd4dfc0dfc0b70acdfbce8'),
  ('cpiuris2025::e2eecd8eaef1473494b37a4afa499369', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Formalização da Penhora', '## Formalização da Penhora

Descreve a formalização da penhora de dinheiro em depósito ou aplicação financeira, incluindo o sistema BacenJud e o procedimento estabelecido pelo art. 854 do CPC.

### Conceitos
- **Penhora**: Medida processual destinada a garantir o pagamento de uma dívida
- **Depósito**: Fundo criado para receber dinheiro ou bens
- **Aplicação financeira**: Uso do dinheiro para pagar dívidas ou investir em ativos
- **Sistema BacenJud**: Plataforma eletrônica que interliga o Poder Judiciário às instituições financeiras
- **Convênio**: Acordo entre entidades diferentes para alcançar um objetivo comum
- **Art. 854 do CPC**: Disposição do Código de Processo Civil que estabelece o procedimento da formalização da penhora eletrônica

### Referências legais
- Art. 876, § 7º do CPC

### Dicas de prova
- Entenda a diferença entre depósito e aplicação financeira
- Conheça o sistema BacenJud e seu papel na formalização da penhora', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.317 (2)", "page_number": 317, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 876, § 7º do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:25:15.701489+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=317", "doc_key": "e2eecd8eaef1473494b37a4afa499369"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e1a2b4be0e2bdda68a7043e13a96f4954a38b8218fa44168b2758e217b8a1dd4'),
  ('cpiuris2025::ee8faff08c6283511a9fee641fd2071e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Indisponibilidade de Ativos Financeiros', '## Indisponibilidade de Ativos Financeiros

O juiz pode determinar à instituição financeira a indisponibilidade de ativos financeiros do executado, limitando-se ao valor indicado na execução. O executado tem prazo para comprovar que as quantias são impenhoráveis e se ainda remaneça indisponibilidade excessiva.

### Conceitos
- **Indisponibilidade de Ativos Financeiros**: Medida processual que limita a disposição de ativos financeiros do executado
- **Disposição de Ativos Financeiros**: Ação pelo qual o executado se dispõe de seus ativos financeiros para satisfação da dívida
- **Impenhorabilidade**: Condição que impede a penhora de bens do executado
- **Excesso de Indisponibilidade**: Situação em que a indisponibilidade de ativos financeiros é superior ao valor indicado na execução

### Referências legais
- Art. 854, § 1º do CPC
- Art. 854, § 2º do CPC
- Art. 854, § 3º do CPC
- Art. 854, § 4º do CPC
- Art. 854, § 5º do CPC
- Art. 854, § 6º do CPC
- Art. 854, § 8º do CPC

### Dicas de prova
- Entenda a diferença entre indisponibilidade e disposição de ativos financeiros
- Conheça as condições para a impenhorabilidade de quantias indisponíveis
- Identifique o prazo para cancelamento de eventual indisponibilidade excessiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.318 (1)", "page_number": 318, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 854, § 1º do CPC", "Art. 854, § 2º do CPC", "Art. 854, § 3º do CPC", "Art. 854, § 4º do CPC", "Art. 854, § 5º do CPC", "Art. 854, § 6º do CPC", "Art. 854, § 8º do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:26:10.227299+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=318", "doc_key": "ee8faff08c6283511a9fee641fd2071e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '3dc8b3f695481fb489ccfcb863df80feefd764f62d38ec99e3482dec97c55316'),
  ('cpiuris2025::fac1adf06ac73236ed3872e3116aafe8', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Penhora em Créditos do Executado', '## Penhora em Créditos do Executado

A penhora é realizada sobre créditos do executado com a intimação do terceiro e do executado, para que o terceiro não pague ao executado e o executado não pratique atos de disposição do crédito.

### Conceitos
- **Penhora**: Ato processual que se aplica a bens do executado
- **Créditos do Executado**: Direitos que o executado tem contra terceiros
- **Intimação**: Notificação formal de uma pessoa sobre um ato processual
- **Terceiro**: Devedor do executado
- **Executado**: Credor que procura a execução de um título
- **Apreensão**: Ato processual que se aplica a um documento
- **Depósito**: Ação de entregar uma coisa em juízo

### Referências legais
- Art. 856, caput, do CPC

### Dicas de prova
- Entenda a diferença entre penhora e apreensão
- Conheça as consequências de confessar ou negar o débito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.318 (2)", "page_number": 318, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 856, caput, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:26:43.555392+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=318", "doc_key": "fac1adf06ac73236ed3872e3116aafe8"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '582e4ce377c83cad71a9933a21b57d305a4ee749a3c5292d708b00f831eaed44'),
  ('cpiuris2025::92db76219392daab4cbcb833a7ed99e1', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Penhora e Execução', '## Penhora e Execução

O juiz determina o comparecimento do executado e do terceiro para tomar depoimentos, e se a penhora recai sobre dívidas de dinheiro ou direitos litigiosos, o exequente pode levantar os juros ou prestações depositadas.

### Conceitos
- **Sub-rogação**: O direito do exequente de se sub-rogar nos direitos do executado até a concorrência de seu crédito.
- **Alienação judicial**: A alienação judicial do direito penhorado, em vez da sub-rogação, com declaração da vontade do exequente no prazo de 10 dias.
- **Penhora no rosto dos autos**: A averbada penhora sobre um direito litigioso, para que a execução seja efetivada nos bens que forem adjudicados ao executado.
- **Balanço especial**: O apresentamento de balanço especial pela sociedade, na forma da lei, após a penhora das quotas ou ações de sócio em sociedade simples ou empresária.
- **Direito de preferência legal ou contratual**: O direito dos demais sócios à aquisição das quotas ou ações, observado o direito previsto na lei ou no contrato social.
- **Liquidação das quotas ou das ações**: A liquidação das quotas ou das ações da sociedade, caso não haja interesse dos sócios na aquisição das ações, com depósito do valor apurado em dinheiro.
- **Imputação do pagamento**: O processo de abatimento das importâncias recebidas sobre o crédito do executado, conforme as regras de imputação do pagamento.
- **Execução nos mesmos autos**: A continuidade da execução, mesmo que o sub-rogado não receba o crédito do executado, com penhoramento de outros bens.

### Referências legais
- Art. 856, § 4º, do CPC
- Art. 857 do CPC
- Art. 858 do CPC
- Art. 859 do CPC
- Art. 860 do CPC

### Dicas de prova
- Sub-rogação e alienação judicial: distinção relevante para prova.
- Penhora no rosto dos autos: importância da averbação nos autos pertinentes ao direito e na ação correspondente à penhora.
- Balanço especial: apresentamento obrigatório pela sociedade após a penhora das quotas ou ações de sócio em sociedade simples ou empresária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.319 (1)", "page_number": 319, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 856, § 4º, do CPC", "Art. 857 do CPC", "Art. 858 do CPC", "Art. 859 do CPC", "Art. 860 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:27:44.558411+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=319", "doc_key": "92db76219392daab4cbcb833a7ed99e1"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '27c2f6f1c2a2b74fdc7b34933868c7ddae6d174b4b5190a16d95b9702f14a3ae'),
  ('cpiuris2025::8ba1bb6b76f6d0ec345ee63ddd70288e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Liquidação de Quotas ou Ações', '## Liquidação de Quotas ou Ações

O juiz pode nomear administrador para liquidar quotas ou ações, com aprovação judicial. A sociedade pode adquirir quotas penhoradas sem redução do capital social.

### Conceitos
- **Administrador Judicial**: Pessoa nomeada pelo juiz para liquidar quotas ou ações
- **Aprovação Judicial**: Requisito para a liquidação de quotas ou ações
- **Sociedade Anônima**: Tipo de sociedade que não pode adquirir quotas penhoradas sem redução do capital social
- **Liquidação de Quotas ou Ações**: Processo pelo qual as quotas ou ações são convertidas em dinheiro

### Referências legais
- Art. 861, § 1º e 3º do CPC

### Dicas de prova
- Entenda a diferença entre sociedade fechada e aberta
- Conheça as hipóteses de liquidação de quotas ou ações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.319 (2)", "page_number": 319, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 861, § 1º e 3º do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:28:25.843332+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=319", "doc_key": "8ba1bb6b76f6d0ec345ee63ddd70288e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd06c26e8b779958c0aa02971dafb2e7f6d6a51b5744d8a020f5ca50f93a7e83b'),
  ('cpiuris2025::2db5ba45e41738eb708742399ecaf060', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Penhora de empresa e outros estabelecimentos', '## Penhora de empresa e outros estabelecimentos

Rege a penhora de empresas, estabelecimentos e semoventes, incluindo a nomeação de administrador-depositário e o procedimento para a administração provisória.

### Conceitos
- **Administrador-depositário**: Pessoa nomeada pelo juiz para administrar os bens penhorados
- **Penhora de empresa**: Procedimento que visa sequestrar a empresa para garantir o pagamento do crédito
- **Semoventes**: Bens móveis que podem ser penhorados, como veículos ou equipamentos

### Referências legais
- Art. 862 do CPC
- Art. 863 do CPC
- Art. 864 do CPC
- Art. 865 do CPC
- Art. 866 do CPC

### Dicas de prova
- Entenda a diferença entre penhora de empresa e penhora sobre faturamento de empresa.
- Conheça os requisitos para a nomeação de administrador-depositário.
- Avalie as implicações da penhora sobre edifícios em construção sob regime de incorporação imobiliária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.320 (1)", "page_number": 320, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 862 do CPC", "Art. 863 do CPC", "Art. 864 do CPC", "Art. 865 do CPC", "Art. 866 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:29:09.333434+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=320", "doc_key": "2db5ba45e41738eb708742399ecaf060"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '97640f09fb0d557a7992ed3dcde39a1f056082bbeb8e21026ea5f82254d058b7'),
  ('cpiuris2025::c8e40c6befb0c544e2b47b7ea79e2f7e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Penhora de Bens no Processo de Execução', '## Penhora de Bens no Processo de Execução

A penhora de bens pode ocorrer em seus ulteriores termos, ouvindo-se o ente público que concedeu a concessão antes da arrematação ou da adjudicação. Além disso, a penhora não impede a navegação ou operação dos bens até a alienação, mas o juiz pode exigir seguro contra riscos.

### Conceitos
- **Penhora**: Ato processual que se aplica ao bem do devedor para garantir o pagamento do crédito
- **Arrematação**: Ato processual que ocorre após a penhora, onde o juiz vende o bem para pagar o crédito
- **Adjudicação**: Ato processual que ocorre após a arrematação, onde o juiz transfere o bem ao devedor que não paga o crédito
- **Concessão**: Outorgação de direito pelo Estado para que uma empresa ou pessoa jurídica exerça um serviço público
- **Seguro contra riscos**: Contrato que protege o executado contra perdas e danos decorrentes da navegação ou operação do bem

### Referências legais
- Art. 863, § 2º, do CPC
- Art. 864 do CPC

### Dicas de prova
- Entenda a diferença entre arrematação e adjudicação
- Conheça o conceito de concessão e como ela se relaciona com a penhora', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.320 (2)", "page_number": 320, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 863, § 2º, do CPC", "Art. 864 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:29:58.857422+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=320", "doc_key": "c8e40c6befb0c544e2b47b7ea79e2f7e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '5754053181596a5439263729b153fa544e86110143dc3693f050f4922228491d'),
  ('cpiuris2025::04c445ec859e20bc3e1bec0fd6085dda', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Penhora de Percentual de Faturamento de Empresa', '## Penhora de Percentual de Faturamento de Empresa

O juiz pode ordenar a penhora de percentual de faturamento de empresa se o executado não tiver outros bens penhoráveis ou se os bens forem de difícil alienação. O juiz fixará um percentual que permita a satisfação do crédito em tempo razoável, mas que não torna inviável o exercício da atividade empresarial.

### Conceitos
- **Penhora de Percentual de Faturamento**: Medida processual que permite ao juiz ordenar a penhora de um percentual do faturamento de uma empresa para satisfação de crédito
- **Execução Forçada**: Procedimento judicial que visa compelir uma pessoa a pagar uma dívida ou obrigação
- **Administrador-Depositário**: Pessoa nomeada pelo juiz para administrar o bem penhorado e receber os seus frutos e utilidades
- **Menor Onerosidade da Execução**: Princípio que visa minimizar a onerosidade da execução, ou seja, evitar que a execução seja excessivamente onerosa para o executado
- **Frutos e Rendimentos**: Direito do proprietário de um bem à receita gerada por esse bem
- **Penhora de Frutos e Rendimentos**: Medida processual que permite ao juiz ordenar a penhora dos frutos e rendimentos de um bem para satisfação de crédito
- **Averbação no Ofício Imobiliário**: Ato pelo qual o exequente apresenta certidão de inteiro teor do ato à autoridade competente, com o objetivo de averbar a penhora em um imóvel

### Referências legais
- Art. 866 do CPC
- Art. 867 do CPC
- Art. 868 do CPC

### Dicas de prova
- Entenda a noção de menor onerosidade da execução e como ela se aplica à penhora de percentual de faturamento de empresa
- Conheça as regras para a penhora de frutos e rendimentos, incluindo a necessidade de averbação no ofício imobiliário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.321 (1)", "page_number": 321, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 866 do CPC", "Art. 867 do CPC", "Art. 868 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:31:09.571673+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=321", "doc_key": "04c445ec859e20bc3e1bec0fd6085dda"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '90b57d2fbd4c8a9d3bfe5a4ea7fe561f6e6ba03c9efb385949df3293378bc003'),
  ('cpiuris2025::8074fe3f922d311548ea1604782cd121', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Aprovação judicial e administração de bens', '## Aprovação judicial e administração de bens

O administrador submeterá à aprovação judicial a forma de administração e a de prestar contas, podendo o juiz decidir a melhor forma de administração do bem em caso de discordância. As quantias recebidas pelo administrador serão entregues ao exequente para serem imputadas ao pagamento da dívida.

### Conceitos
- **Aprovação judicial**: O processo em que o juiz decide sobre a forma de administração e prestar contas do bem.
- **Administração de bens**: A gestão dos bens do devedor para pagamento da dívida.
- **Penhora**: O ato pelo qual o juiz ordena a confiscoção de bens do devedor.
- **Substituição, redução, ampliação ou renovação da penhora**: Mudanças feitas na penhora após sua formalização.

### Referências legais
- Art. 869, § 1º, do CPC

### Dicas de prova
- Entenda a importância da aprovação judicial na administração de bens.
- Conheça as regras sobre a substituição, redução, ampliação ou renovação da penhora.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.321 (2)", "page_number": 321, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 869, § 1º, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:31:39.413403+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=321", "doc_key": "8074fe3f922d311548ea1604782cd121"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '886714f07b7c0977ac0d2a1a8a77e996209aba0dd302b9e693d7cf43428a2bdc'),
  ('cpiuris2025::9a5a8ccaba77a68472b691654e219c5f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Substituição de Penhora', '## Substituição de Penhora

O executado pode requerer substituição do bem penhorado dentro de 10 dias após a intimação da penhora, desde que comprove que lhe será menos onerosa e não trará prejuízo ao exequente.

### Conceitos
- **Substituição de Penhora**: Requerimento do executado para substituir o bem penhorado por outro
- **Penhora**: Ato processual que coloca um bem em segurança para pagamento de uma dívida
- **Execução**: Procedimento judicial para cobrar uma dívida

### Referências legais
- Art. 847, caput e § 1º do CPC
- Art. 847, § 2º do CPC
- Art. 848 do CPC

### Dicas de prova
- Diferenciar entre substituição por iniciativa exclusiva do executado e situações que permitem a substituição por qualquer das partes
- Entender o significado de ''menos onerosa'' e ''não trará prejuízo ao exequente''', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.322 (1)", "page_number": 322, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 847, caput e § 1º do CPC", "Art. 847, § 2º do CPC", "Art. 848 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:32:11.414365+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=322", "doc_key": "9a5a8ccaba77a68472b691654e219c5f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '14ec71fbcab8c787478915411e130921951ba19b28121dc54cbb493268af37d5'),
  ('cpiuris2025::27c39aacba34348925b9cf8aa99b75c6', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Substituição da Penhora', '## Substituição da Penhora

A substituição da penhora é possível quando o executado não indica o valor dos bens ou omite as indicações previstas em lei. A fiança bancária e o seguro garantia judicial podem ser utilizados desde que em valor não inferior ao do débito constante da inicial, acrescido de 30%.

### Conceitos
- **Substituição da Penhora**: Mudança do bem penhorado por outro valor ou tipo de garantia
- **Fiança Bancária**: Garantia oferecida por um banco em substituição à penhora
- **Seguro Garantia Judicial**: Contrato que assegura o pagamento do débito em caso de falência ou morimento do devedor

### Referências legais
- Art. 835, § 2º, do CPC
- Art. 848, parágrafo único, do CPC

### Dicas de prova
- Entenda a diferença entre fiança bancária e seguro garantia judicial
- Conheça o valor mínimo que deve ser utilizado para substituição da penhora', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.322 (2)", "page_number": 322, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 835, § 2º, do CPC", "Art. 848, parágrafo único, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:32:47.799126+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=322", "doc_key": "27c39aacba34348925b9cf8aa99b75c6"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '8a8c6e75bde75a9499d3ae8a9be3c7f4dcd9d319e68f2227c0e4afb40f59c12b'),
  ('cpiuris2025::d3587c7ad57dc6a9555fef30335a8438', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Redução ou ampliação da penhora e renovação da penhora', '## Redução ou ampliação da penhora e renovação da penhora

Regras para redução ou ampliação da penhora e renovação da penhora após a realização da penhora.

### Conceitos
- **Penhora**: Ato processual que determina a confiscação de bens do devedor
- **Redução da penhora**: Mudança na quantidade de bens penhorados
- **Ampliação da penhora**: Aumento na quantidade de bens penhorados
- **Renovação da penhora**: Nova penhora realizada após a primeira

### Referências legais
- Art. 850 do CPC
- Art. 851 do CPC
- Art. 852, I do CPC
- Art. 852, II do CPC
- Art. 853 do CPC
- Art. 870 do CPC

### Dicas de prova
- Entenda a diferença entre redução e ampliação da penhora.
- Conheça as causas que ensejam a renovação da penhora.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.323", "page_number": 323, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 850 do CPC", "Art. 851 do CPC", "Art. 852, I do CPC", "Art. 852, II do CPC", "Art. 853 do CPC", "Art. 870 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:33:22.417950+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=323", "doc_key": "d3587c7ad57dc6a9555fef30335a8438"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'bbf665e28314bdc16c79be0b38a7f2dac60374b49f40c3098e7d154e508a63ce'),
  ('cpiuris2025::55dd4228e83e851afa5ef0cc21b66030', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Avaliação e Expropriação em Execução', '## Avaliação e Expropriação em Execução

Resumo do artigo sobre avaliação e expropriação em execução, destacando as hipóteses de dispensa da avaliação e os atos realizados após a penhora.

### Conceitos
- **Avaliação**: Procedimento realizado para determinar o valor dos bens penhorados
- **Expropriação**: Adjudicação, alienação e apropriação de frutos e rendimentos de empresa ou estabelecimento
- **Adjudicação**: Modalidade de expropriação que dá ao bem penhorado como forma de extinção da execução
- **Penhora**: Procedimento realizado para sequestrar bens do devedor para satisfação do crédito

### Referências legais
- Art. 872, § 1º, do CPC; Art. 875 do CPC

### Dicas de prova
- Entenda a importância da avaliação em execução e como ela é realizada.
- Conheça as hipóteses de dispensa da avaliação e os atos realizados após a penhora.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.324", "page_number": 324, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 872, § 1º, do CPC; Art. 875 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:33:54.312055+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=324", "doc_key": "55dd4228e83e851afa5ef0cc21b66030"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '31587cbdbe014a1e4b09c8c01d012e3d83037fa9e001b01e9a92d0d3520f54f6'),
  ('cpiuris2025::4222362ac6dd6de9dfde1b02ceb0f782', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Adjudicação', '## Adjudicação

A adjudicação é uma medida expropriatória preferencial que pode ser realizada enquanto o bem penhorado não for alienado por iniciativa particular ou em leilão judicial. Tem legitimidade para requerer a adjudicação credores com garantia real, cônjuge, companheiro, descendentes e ascendentes do executado, além de demais sócios em sociedades anônimas fechadas.

### Conceitos
- **Adjudicação**: Medida expropriatória preferencial
- **Exequente**: Parte que requer a adjudicação do bem penhorado
- **Credor com garantia real**: Credor que tem direito à garantia real sobre o bem
- **Legitimidade para requerer adjudicação**: Credores com garantia real, cônjuge, companheiro, descendentes e ascendentes do executado, além de demais sócios em sociedades anônimas fechadas

### Referências legais
- Art. 880, caput, do CPC
- Art. 876, § 5º, do CPC
- Art. 876, § 6º, do CPC
- Art. 877, caput, do CPC

### Dicas de prova
- Diferenciar entre preferência de ordem processual e preferência de direito material
- Entender a legitimidade para requerer a adjudicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.325 (1)", "page_number": 325, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 880, caput, do CPC", "Art. 876, § 5º, do CPC", "Art. 876, § 6º, do CPC", "Art. 877, caput, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:34:40.139654+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=325", "doc_key": "4222362ac6dd6de9dfde1b02ceb0f782"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'fde5fd83cbcbe1a8159fe679b7ebb590e50b74fc179b995e60dbcd389d2f88e4'),
  ('cpiuris2025::b604e39b0120a312ab4d9581bc87a61d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Adjudicação e Execução', '## Adjudicação e Execução

O executado pode remir a execução, pagando ou consignando a importância atualizada da dívida, acrescida de juros, custas e honorários. As empresas públicas e privadas são obrigadas a manter cadastro nos sistemas de processo em autos eletrônicos.

### Conceitos
- **Adjudicação**: Procedimento pelo qual o juiz determina a posse do bem por parte do credor
- **Execução**: Mecanismo processual destinado a cobrar uma dívida
- **Remição**: Ação do executado para reduzir ou extinguir a execução
- **Citações e intimações**: Notificações formais ao executado ou às partes interessadas

### Referências legais
- Art. 877, § 2º, do CPC; Art. 826 do CPC; Art. 246, § 1º, do CPC

### Dicas de prova
- Entenda a diferença entre adjudicação e execução
- Conheça as condições para remição da execução', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.325 (2)", "page_number": 325, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 877, § 2º, do CPC; Art. 826 do CPC; Art. 246, § 1º, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:35:06.845155+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=325", "doc_key": "b604e39b0120a312ab4d9581bc87a61d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f81b80b2fb1e8541e274763ddab6ff781804c1265826623e07bcd56561ff8fb5'),
  ('cpiuris2025::3aa4e3a59896ac862b78f69b1124dfcd', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Alienação de Bens em Execução', '## Alienação de Bens em Execução

A alienação é uma forma de expropriação de bens prevista no CPC, que pode ser realizada por iniciativa particular ou por leilão judicial. A alienação por iniciativa particular deve observar requisitos formais estabelecidos pelo juiz, como prazo, publicidade e preço mínimo.

### Conceitos
- **Alienação**: Forma de expropriação de bens prevista no CPC
- **Leilão judicial**: Lançamento do bem em leilão para sua alienação
- **Iniciativa particular**: Oportunidade do exequente realizar a alienação por conta própria
- **Corretor ou leiloeiro público**: Pessoa credenciada perante o órgão judiciário para realizar a alienação
- **Credenciamento**: Processo pelo qual a pessoa é autorizada a realizar a alienação

### Referências legais
- Art. 80 do CPC
- Art. 880, § 1º e § 3º do CPC

### Dicas de prova
- Entenda a diferença entre iniciativa particular e leilão judicial
- Conheça os requisitos formais para a alienação por iniciativa particular', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.326 (1)", "page_number": 326, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 80 do CPC", "Art. 880, § 1º e § 3º do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:35:41.202247+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=326", "doc_key": "3aa4e3a59896ac862b78f69b1124dfcd"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f9f2b422c80b801e8439be09d8979ec7da2b53fc95edfbb85f1659d2087427ff'),
  ('cpiuris2025::294437c9254ccbc51efe9e0b2a9eb622', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Alienação de Bens no Processo', '## Alienação de Bens no Processo

O artigo 880, § 2º, do CPC estabelece que o exequente deve ser informado sobre a alienação do bem, seja como adquirente ou executado, e que essa alienação pode ocorrer por meio de carta de alienação e mandado de imissão na posse para bens imóveis, ou ordem de entrega ao adquirente para bens móveis.

### Conceitos
- **Alienação**: Processo pelo qual um bem é transferido de uma pessoa para outra
- **Leilão Judicial**: Modalidade de alienação em que o bem é vendido ao maior lealor
- **Adjudicação**: Procedimento que determina a transferência do bem ao exequente
- **Carta de Alienação**: Documento que comprova a transferência do bem para o adquirente
- **Mandado de Imissão na Posse**: Ordem judicial que autoriza o adquirente a tomar posse do bem
- **Ordem de Entrega ao Adquirente**: Decisão judicial que determina a entrega do bem ao adquirente

### Referências legais
- Art. 880, § 2º, do CPC

### Dicas de prova
- Entenda a diferença entre alienação e adjudicação
- Conheça as características de leilão judicial e sua importância na alienação de bens', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.326 (2)", "page_number": 326, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 880, § 2º, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:36:24.347684+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=326", "doc_key": "294437c9254ccbc51efe9e0b2a9eb622"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ef7159d9ecdbdb3d696e1b2486f674cc78957b805d1c4aca540f9c18c143f860'),
  ('cpiuris2025::3d4a0413018e9d1cd398239c5415bc02', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Leilões em Execução', '## Leilões em Execução

Regras para realização de leilões em execução, incluindo requisitos de publicidade, autenticidade e segurança.

### Conceitos
- **Leilão**: Procedimento utilizado para alienar bens em execução
- **Edital do leilão**: Publicação que precede o leilão, contendo descrição do bem penhorado e suas características
- **Leiloeiro público**: Pessoa designada pelo juiz para realizar o leilão
- **Comissão do leiloeiro**: Pagamento feito pelo arrematante à pessoa designada para realizar o leilão

### Referências legais
- Art. 881, caput, do CPC; Art. 882, § 1º, do CPC; Art. 882, § 3º, do CPC; Art. 885 do CPC

### Dicas de prova
- Entenda a importância da publicidade e autenticidade no leilão
- Conheça as regras para designação do leiloeiro público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.327 (1)", "page_number": 327, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 881, caput, do CPC; Art. 882, § 1º, do CPC; Art. 882, § 3º, do CPC; Art. 885 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:36:56.482123+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=327", "doc_key": "3d4a0413018e9d1cd398239c5415bc02"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '4cece65466e6cd0ed4ca78a9f085c7fc30731246fa1db718a1e7f6053e696f02'),
  ('cpiuris2025::438966c4eeb7f5509936ba3c676cb00d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Lei de Penhora', '## Lei de Penhora

Resumo do conteúdo do artigo: informações sobre penhoramento, incluindo valor avaliado, preço mínimo, condições de pagamento e localização dos bens.

### Conceitos
- **Penhora**: Procedimento pelo qual os bens de um devedor são alienados para satisfação do crédito
- **Leilão**: Processo em que os bens penhorados são vendidos ao melhor preço possível

### Referências legais
- Art. 634 do Código de Processo Civil

### Dicas de prova
- Perguntas sobre o procedimento de penhora e leilão
- Distinção entre valor avaliado e preço mínimo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.327 (2)", "page_number": 327, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 634 do Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:37:14.443056+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=327", "doc_key": "438966c4eeb7f5509936ba3c676cb00d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '535da506fa6489befcca56c98a0841f6808224f04ec86e447882d3098786c5dd'),
  ('cpiuris2025::bfdffa584ecc0ecfd06e592dfd7fab1a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Divulgação e Publicidade dos Editais de Leilão', '## Divulgação e Publicidade dos Editais de Leilão

O edital de leilão deve ser publicado na rede mundial de computadores ou em local de costume, com descrição detalhada dos bens e informando se o leilão será eletrônico ou presencial. Em caso de impossibilidade, pode ser publicado em jornal de ampla circulação local.

### Conceitos
- **Divulgação**: A notificação pública das informações relevantes para o leilão
- **Publicidade**: A divulgação de informações sobre o leilão em diferentes meios
- **Edital**: O documento que contém as informações relevantes para o leilão

### Referências legais
- Art. 887, §§ 2º e 3º, do CPC
- Art. 887, § 4º, do CPC
- Art. 887, § 5º, do CPC
- Art. 887, § 6º, do CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Pergunte sobre a forma de divulgação dos editais de leilão e quais são as exceções.
- Entenda a diferença entre publicidade e divulgação em contextos jurídicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.328 (1)", "page_number": 328, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 887, §§ 2º e 3º, do CPC", "Art. 887, § 4º, do CPC", "Art. 887, § 5º, do CPC", "Art. 887, § 6º, do CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T02:37:59.828917+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=328", "doc_key": "bfdffa584ecc0ecfd06e592dfd7fab1a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e6157d1373189c5ccb7079f19e3b6cacaf9b46c9efee0ad3dbc084b70c15247b'),
  ('cpiuris2025::e5338aa6b135f3758a08f78b46dda64d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Exceções à Penhora', '## Exceções à Penhora

Exceções ao reajustamento da penhora em casos específicos, como uso especial para moradia ou direitos reais.

### Conceitos
- **Penhora**: execução forçada de um crédito
- **Gravame**: direito real que limita a posse de um bem
- **Credor pignoratício**: creditor que tem direito sobre um bem como garantia
- **Promitente comprador**: parte que prometeu comprar um bem

### Referências legais
- Art. 640 do Código de Processo Civil

### Dicas de prova
- Entenda a diferença entre gravame e direitos reais
- Conheça os casos específicos que não são afetados pela penhora', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.328 (2)", "page_number": 328, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 640 do Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:38:21.580043+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=328", "doc_key": "e5338aa6b135f3758a08f78b46dda64d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '65387740f95dd7455b0e5165fa3f967db0959f44f303dee8c6c427aee8c4cbcf'),
  ('cpiuris2025::5d5c9bdcf810ec658994aae92192e445', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução Cível', '## Execução Cível

Regras para a realização de leilões em execução cível, incluindo a intimação do executado revel e as restrições à arrematação.

### Conceitos
- **Arrematação**: Oferecer lance para adquirir um bem objeto da alienação
- **Intimação do executado revel**: Notificação do executado que não tem advogado constituído e não tem endereço conhecido
- **Leilão**: Procedimento em que o juiz vende os bens do devedor para satisfação da dívida
- **Lance vil**: Preço inferior ao mínimo estipulado pelo juiz

### Referências legais
- Art. 889, parágrafo único, do CPC
- Art. 887 do CPC
- Art. 888, parágrafo único, do CPC
- Art. 890 do CPC
- Art. 897 do CPC

### Dicas de prova
- Distinção entre intimação e notificação
- Regras para a realização de leilões em execução cível
- Impedimentos à arrematação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.329 (1)", "page_number": 329, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 889, parágrafo único, do CPC", "Art. 887 do CPC", "Art. 888, parágrafo único, do CPC", "Art. 890 do CPC", "Art. 897 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:38:56.340493+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=329", "doc_key": "5d5c9bdcf810ec658994aae92192e445"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '8c888be1a82af062ace195c0f60faaff83cb5d945be2961990baf02c0e5817f2'),
  ('cpiuris2025::0c363dadb025dc8a58ddd9101a15a8d5', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Arrematação em Leilão', '## Arrematação em Leilão

Regra para a arrematação em leilão: pagamento à vista e exibição do preço pelo exequente, exceto se o valor superar seu crédito.

### Conceitos
- **Arrematação**: Ato de adquirir um bem no leilão
- **Pagamento à vista**: Paga-se o valor do bem imediatamente após a arrematação
- **Exibição do preço**: O exequente deve mostrar o preço pago ao leiloeiro
- **Crédito**: Valor que o exequente pode cobrar do bem adquirido

### Referências legais
- Art. 891 e 892, caput e § 1º do CPC

### Dicas de prova
- Perguntas sobre arrematação podem ser confusas com outras regras de leilão.
- Lembre-se de que o exequente não precisa exibir o preço se superar seu crédito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.329 (2)", "page_number": 329, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 891 e 892, caput e § 1º do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:39:31.460114+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=329", "doc_key": "0c363dadb025dc8a58ddd9101a15a8d5"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '664e0bfdf672760db54d23b1027568a40fad7334f17aa8ffde44ba2c911be54e'),
  ('cpiuris2025::5a224c8541559544b62de40d9f819304', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução e Leilão de Bens', '## Execução e Leilão de Bens

Regra para a licitação entre vários pretendentes em execução, preferência dos cônjuge, companheiro, descendente ou ascendente do executado, além de direitos de preferência da União, Estados e Municípios em leilões de bens tombados.

### Conceitos
- **Licitação**: Procedimento utilizado para a escolha entre vários pretendentes
- **Preferência**: Direito concedido a certos grupos, como cônjuge ou descendente do executado
- **Leilão de Bens**: Procedimento utilizado para a venda de bens em execução

### Referências legais
- Art. 892, § 2º, do CPC
- Art. 893, do CPC
- Art. 894, caput e § 1º, do CPC
- Art. 895, I e II, do CPC

### Dicas de prova
- Entenda a ordem de preferência nos diferentes casos
- Conheça as regras para o pagamento parcelado de bens em execução', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.330 (1)", "page_number": 330, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 892, § 2º, do CPC", "Art. 893, do CPC", "Art. 894, caput e § 1º, do CPC", "Art. 895, I e II, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:40:01.478849+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=330", "doc_key": "5a224c8541559544b62de40d9f819304"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '5f79d84ec3ebf7ddc692f2f6162ebd976a71673e7e8347d75be397d00bd40ab3'),
  ('cpiuris2025::c2d57ab3f22300e1dd207258e674478e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Arrematação em Execução', '## Arrematação em Execução

O interessado proponente deve indicar o prazo, modalidade, indexador de correção monetária e condições de pagamento do saldo. Em caso de inadimplência, a perda da caução pode ser imposta, com possibilidade de transferência da arrematação ao fiador.

### Conceitos
- **Arrematação**: Processo pelo qual o executado vende seus bens para atender à execução
- **Caução**: Garantia oferecida pelo arrematante para garantir o cumprimento das prestações
- **Fiador**: Pessoa responsável pela pagamento do preço do leilão, caso o arrematante não pague
- **Multa**: Penalidade aplicada ao arrematante por atraso no pagamento de qualquer das prestações

### Referências legais
- Art. 895, § 2º do CPC
- Art. 897 do CPC
- Art. 898 do CPC

### Dicas de prova
- Diferenciar entre a perda da caução e a transferência da arrematação ao fiador
- Entender o conceito de multa aplicada ao arrematante por atraso no pagamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.330 (2)", "page_number": 330, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 895, § 2º do CPC", "Art. 897 do CPC", "Art. 898 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:40:32.821269+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=330", "doc_key": "c2d57ab3f22300e1dd207258e674478e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'cad368289eaa5cbb0ef4b0749f4469c3e614ebea8534f14e4d1668cd0994915a'),
  ('cpiuris2025::05140618af09e0375da0fd2ccff7a8d9', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução e Leilões', '## Execução e Leilões

Regras sobre apresentação de proposta de pagamento em prestações, suspensão da arrematação do leilão, auto de arrematação e confiança do imóvel de incapaz.

### Conceitos
- **Proposta de pagamento parcelado**: Oferta de pagamento em prestações
- **Lance à vista**: Pagamento total e imediato do valor do bem
- **Auto de arrematação**: Atestado oficial da conclusão do leilão
- **Suspensão da arrematação**: Encerramento antecipado da arrematação do leilão

### Referências legais
- Art. 895, § 6º e 7º, do CPC
- Art. 896, § 1º e 2º, do CPC
- Art. 899, do CPC
- Art. 900, do CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre lance à vista e proposta de pagamento parcelado
- Entender a importância da suspensão da arrematação do leilão
- Conhecer o procedimento para lavratura do auto de arrematação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.331 (1)", "page_number": 331, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 895, § 6º e 7º, do CPC", "Art. 896, § 1º e 2º, do CPC", "Art. 899, do CPC", "Art. 900, do CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T02:41:18.859738+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=331", "doc_key": "05140618af09e0375da0fd2ccff7a8d9"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '63176a1c4da7bbfbc89b18e7b87200d65fb6bddee37ed3cf0aee95f93018a8fe'),
  ('cpiuris2025::a348d128c9613fa5fad29420cf7dc0fc', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Auto de Arrematação', '## Auto de Arrematação

O auto de arrematação é assinado pelo leiloeiro, juiz e arrematante, abrangendo bens penhorados em mais de uma execução. É expedido após o depósito ou garantias do arrematante, pagamento da comissão do leiloeiro e demais despesas.

### Conceitos
- **Arrematação**: Ato que assina o leiloeiro, juiz e arrematante
- **Depósito**: Pagamento ou garantia prestada pelo arrematante
- **Comissão do Leiloeiro**: Despesa paga ao leiloeiro
- **Mandado de Imissão na Posse**: Ordem que determina a entrega do bem

### Referências legais
- Art. 901, § 1º, do CPC

### Dicas de prova
- Distinção entre bens penhorados em mais de uma execução
- Importância do depósito e garantias do arrematante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.331 (2)", "page_number": 331, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 901, § 1º, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:41:43.364465+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=331", "doc_key": "a348d128c9613fa5fad29420cf7dc0fc"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '43dabfe762a2986044d9d13f52e4bfabf5771a1bc82521c0bc64957d0e1d153c'),
  ('cpiuris2025::66263c43edee689671571aed93b7c88e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Arrematação e Leilão de Bens Hipotecados', '## Arrematação e Leilão de Bens Hipotecados

Regra da arrematação em leilões de bens hipotecados, incluindo a descrição do imóvel, pagamento de imposto de transmissão e indicação de ônus reais.

### Conceitos
- **Arrematação**: Ato pelo qual o executado vende o bem ao maior lance oferecido
- **Leilão de Bens Hipotecados**: Procedimento utilizado para vender bens hipotecados
- **Imóvel**: Bem imobilizado que pode ser objeto de leilão
- **Copia do Auto de Arrematação**: Documento que comprova a realização da arrematação
- **Prova de Pagamento do Imposto de Transmissão**: Comprovante do pagamento do imposto de transmissão sobre o bem
- **Ônus Reais**: Direitos ou encargos que o comprador assume em relação ao bem

### Referências legais
- Art. 901, § 2º, do CPC; Art. 902 do CPC; Art. 903, § 1º, do CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre arrematação inválida e ineficaz
- Entender a importância da intimação ao credor com garantia real', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.332 (1)", "page_number": 332, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 901, § 2º, do CPC; Art. 902 do CPC; Art. 903, § 1º, do CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T02:42:20.200660+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=332", "doc_key": "66263c43edee689671571aed93b7c88e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd315cff98cb0d8b7bd577f3fcdee7b90826bf66c2972977d953c70fc8792ce00'),
  ('cpiuris2025::c5f2792539c1ac07e58fa8944a40eb26', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Litisconsórcio Passivo Necessário', '## Litisconsórcio Passivo Necessário

Todos os envolvidos no processo de execução devem compor a relação processual, incluindo o exequente, executado e arrematante. O litisconsórcio passivo necessário é formado quando a ação for proposta por terceiro.

### Conceitos
- **Litisconsórcio Passivo Necessário**: Relação processual que inclui todos os envolvidos no processo de execução
- **Exequente**: Parte que procura a tutela jurídica para obter algo
- **Executado**: Parte contra a qual a ação é proposta
- **Arrematante**: Parte que adquire o direito de posse sobre a coisa objeto da execução

### Referências legais
- Art. 903, § 4º, CPC

### Dicas de prova
- Entenda a diferença entre litisconsórcio passivo necessário e necessário obrigatório.
- Conheça as implicações do litisconsórcio passivo necessário na formação da relação processual.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.332 (2)", "page_number": 332, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 903, § 4º, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:42:57.927788+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=332", "doc_key": "c5f2792539c1ac07e58fa8944a40eb26"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '153632c3fbe664a5d79a75bc02593db6b6e9ebd1fa236988b725ee65211ea2ce'),
  ('cpiuris2025::69f200c19164da990f7314773df2d690', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Desistência da arrematação e ato atentatório à dignidade da justiça', '## Desistência da arrematação e ato atentatório à dignidade da justiça

O arrematante pode desistir da arrematação em determinadas hipóteses, mas não pode suscitar vício infundado para isso. Além disso, o exequente pode levantar dinheiro depositado ou bens penhorados com autorização judicial.

### Conceitos
- **Desistência da arrematação**: O arrematante pode desistir da arrematação em determinadas hipóteses
- **Ato atentatório à dignidade da justiça**: Ato que não é admitido na execução, pois visa enganar o juiz e não é razão para desistência do arrematante
- **Levantamento de importância em dinheiro**: É proibida a concessão de pedidos de levantamento de importância em dinheiro ou valores durante o plantão judiciário

### Referências legais
- Art. 903, §5º do CPC
- Art. 903, §1º do CPC
- Art. 903, §4º do CPC
- Art. 904 do CPC
- Art. 905 do CPC
- Art. 906 do CPC

### Dicas de prova
- Entenda a hipótese de desistência da arrematação e o que é considerado ato atentatório à dignidade da justiça
- Leve em conta as regras sobre levantamento de importância em dinheiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.333", "page_number": 333, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 903, §5º do CPC", "Art. 903, §1º do CPC", "Art. 903, §4º do CPC", "Art. 904 do CPC", "Art. 905 do CPC", "Art. 906 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:43:38.711164+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=333", "doc_key": "69f200c19164da990f7314773df2d690"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '5bf312be419ec17e8377c348423fc64ce02a22f13288f1d2583902b220304e03'),
  ('cpiuris2025::8f6667171f16b15ea603e7e192c5bec8', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução contra a Fazenda Pública', '## Execução contra a Fazenda Pública

Regras para execução contra a Fazenda Pública, incluindo procedimentos e prazos.

### Conceitos
- **Título Executivo Judicial**: Título que consta em autos de processo judicial
- **Título Executivo Extrajudicial**: Título que não consta em autos de processo judicial
- **Fase de Cumprimento de Sentença**: Fase do processo onde o exequente busca cumprir a sentença
- **Pretório ou Requisição de Pequeno Valor**: Solução para execuções fundadas em título executivo extrajudicial

### Referências legais
- Art. 534 do CPC
- Art. 183, § 2º, do CPC
- Art. 100 da Constituição Federal
- Art. 907 do CPC
- Art. 908, § 1º, do CPC
- Art. 908, § 2º, do CPC

### Dicas de prova
- Entenda a diferença entre título executivo judicial e extrajudicial
- Conheça os procedimentos para execução contra a Fazenda Pública
- Aprenda a aplicar as regras de prazo e embargos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.334 (1)", "page_number": 334, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 534 do CPC", "Art. 183, § 2º, do CPC", "Art. 100 da Constituição Federal", "Art. 907 do CPC", "Art. 908, § 1º, do CPC", "Art. 908, § 2º, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:44:14.476212+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=334", "doc_key": "8f6667171f16b15ea603e7e192c5bec8"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '83598b607247464bb633a0cb69617bbfbb571f0ca256f241fe2ccd259c2ad166'),
  ('cpiuris2025::4f3d944b5b13854b1e418ea8bd78d237', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução de Alimentos e Execução Contra a Fazenda Pública', '## Execução de Alimentos e Execução Contra a Fazenda Pública

Aplica-se procedimento do cumprimento de sentença para execução contra a Fazenda Pública, com base em título executivo judicial ou extrajudicial.

### Conceitos
- **Execução Contra a Fazenda Pública**: Procedimento aplicado à execução contra a Fazenda Pública
- **Título Executivo Judicial**: Título que autoriza a execução contra a Fazenda Pública
- **Título Executivo Extrajudicial**: Título que permite a execução por meio de procedimento não judicial
- **Cumprimento de Sentença**: Procedimento aplicado à execução fundada em sentença
- **Execução de Alimentos**: Procedimento aplicado para garantir o pagamento de alimentos
- **Fazenda Pública**: Entidade pública que pode ser executada por meio de procedimento judicial

### Referências legais
- Art. 534 do CPC
- Art. 535 do CPC
- Art. 528 do CPC

### Jurisprudência
- Súmula 279 do Superior Tribunal de Justiça

### Dicas de prova
- Distinção entre título executivo judicial e extrajudicial
- Importância do cumprimento de sentença na execução contra a Fazenda Pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.334 (2)", "page_number": 334, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 534 do CPC", "Art. 535 do CPC", "Art. 528 do CPC"], "jurisprudence": ["Súmula 279 do Superior Tribunal de Justiça"], "confidence": 0.8, "extracted_at": "2026-05-28T02:44:55.069426+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=334", "doc_key": "4f3d944b5b13854b1e418ea8bd78d237"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '54e9f73f9ae19ed9c90a5ecb739848dd795f280eb6e9406d96be63715d1450b4'),
  ('cpiuris2025::ac3ac2f5153f498f2744d0b2f991fb68', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Procedimento da execução de alimentos fundada em título executivo extrajudicial', '## Procedimento da execução de alimentos fundada em título executivo extrajudicial

O procedimento é semelhante ao do cumprimento de sentença, com o executado citado para pagar as parcelas anteriores e futuras dentro de 3 dias. A prisão pode ser decretaada se não for pago ou se a justificativa apresentada não for aceita.

### Conceitos
- **Prisão Civil**: Meio de coerção pessoal para o adimplemento da obrigação
- **Cumprimento da Pena**: Não exime o executado do pagamento das prestações vencidas e vincendas
- **Suspensão do Cumprimento da Ordem de Prisão**: O juiz suspenderá o cumprimento da ordem de prisão se o executado pagar a prestação alimentícia
- **Desconto em Folha de Pagamento**: O exequente pode requerer o desconto em folha de pagamento da importância da prestação alimentícia para funcionários públicos, militares, diretores ou gerentes de empresa

### Referências legais
- Art. 528, § 2º; Art. 528, § 3º; Art. 528, § 4º; Art. 528, § 5º; Art. 528, § 6º; Art. 528, § 7º; Art. 912, caput; Súmula N da STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pegar a diferença entre prisão civil e cumprimento de pena
- Entender o conceito de suspensão do cumprimento da ordem de prisão
- Conhecer as hipóteses em que o desconto em folha de pagamento é permitido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.335 (1)", "page_number": 335, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 528, § 2º; Art. 528, § 3º; Art. 528, § 4º; Art. 528, § 5º; Art. 528, § 6º; Art. 528, § 7º; Art. 912, caput; Súmula N da STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T02:45:38.293242+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=335", "doc_key": "ac3ac2f5153f498f2744d0b2f991fb68"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd05b6cfaa789a5ae0ebffe52d2e190c695eca94de7941f9d857f96ad1464ea42'),
  ('cpiuris2025::f47883338ffec1a14e6aabec6dc5e78c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução pelo rito da prisão civil e procedimento executório', '## Execução pelo rito da prisão civil e procedimento executório

A execução pelo rito da prisão civil é faculdade do credor, que deve manifestar sobre o procedimento a seguir. Se não for requisitada, será observado o procedimento executório por quantia certa.

### Conceitos
- **Desobediência**: Ação que visa impor uma obrigação ao devedor
- **Prisão Civil**: Rito de execução que não envolve a prisão física do devedor
- **Execução pelo rito da prisão civil**: Faculdade do credor para escolher o procedimento de execução
- **Procedimento Executivo**: Rito de execução por quantia certa, previsto no art. 824 e seguintes do CPC
- **Depósito Mensal**: Pagamento mensal da importância a ser descontada
- **Prisão Civil - Tempo de Duração**: Tempo em que a prisão civil será aplicada

### Referências legais
- Art. 912, § 1º do CPC
- Art. 912, § 2º do CPC
- Art. 824 e seguintes do CPC
- Art. 913 do CPC

### Dicas de prova
- Perguntas sobre procedimento executório e execução pelo rito da prisão civil
- Distinção entre procedimento executório por quantia certa e execução pelo rito da prisão civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.335 (2)", "page_number": 335, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 912, § 1º do CPC", "Art. 912, § 2º do CPC", "Art. 824 e seguintes do CPC", "Art. 913 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:46:11.673684+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=335", "doc_key": "f47883338ffec1a14e6aabec6dc5e78c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '53ca16d533e16998e5888ed9b0efc3d880995ec7ce57ea3806914df3c479a798'),
  ('cpiuris2025::9873ecc97a22d82afcca1ef2c311be00', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Embargos à Execução', '## Embargos à Execução

Os embargos à execução são instrumento de contra-ataque do executado com objetivo de extinção ou modificação da relação jurídica que fundamenta a execução.

### Conceitos
- **embargos à execução**: instrumento de contra-ataque do executado
- **competência funcional**: competência absoluta e depende da competência do juízo deprecante ou deprecado
- **prazo para oferecimento dos embargos**: 15 dias contados na forma do art. 231 do CPC
- **ação incidental**: ação que se desenvolve em conjunto com a principal execução
- **ônus da prova**: é do executado (embargante) o ônus de provar a insubsistência ou excesso da execução

### Referências legais
- Art. 914, § 1º, do CPC
- Art. 915, caput, do CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a natureza dos embargos à execução e sua competência.
- Conheça o prazo para oferecimento dos embargos e as hipóteses de competência do juízo deprecado ou deprecante.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.336", "page_number": 336, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 914, § 1º, do CPC", "Art. 915, caput, do CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T02:46:57.527312+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=336", "doc_key": "9873ecc97a22d82afcca1ef2c311be00"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '66af0f38cb9781ac9e52cf9c1ae82dbc25fc01f15481a6c5bf8ea9956bc86818'),
  ('cpiuris2025::d85d2956e9b49302bec5ada748b004d0', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução e Embargos', '## Execução e Embargos

Resumo sobre os prazos para embargos em execução, incluindo casos especiais e regras de parcelamento.

### Conceitos
- **Citação**: A notificação do executado
- **Prazo para embargos**: O período durante o qual o executado pode apresentar embargos
- **Penhora**: A ação de tomar posse dos bens do devedor
- **Carta devida cumprida**: O ato de entregar a carta de notificação ao executado
- **Comunicação por carta precatória, rogatória ou de ordem**: A notificação feita por meio de carta
- **Litisconsórcio passivo**: A situação em que mais de um executado está envolvido na execução
- **Parcelamento**: O ato de dividir o valor da dívida em parcelas mensais

### Referências legais
- Art. 915, § 1º do CPC
- Art. 915, § 4º do CPC
- Art. 916, caput do CPC
- Art. 916, § 6º do CPC
- Art. 916, § 1º do CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre citação e comunicação por carta
- Conheça as regras de parcelamento em execução
- Aprenda a aplicar o art. 915, § 1º do CPC às diferentes situações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.337 (1)", "page_number": 337, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 915, § 1º do CPC", "Art. 915, § 4º do CPC", "Art. 916, caput do CPC", "Art. 916, § 6º do CPC", "Art. 916, § 1º do CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T02:47:40.195372+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=337", "doc_key": "d85d2956e9b49302bec5ada748b004d0"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '91158f1f564ea377b7dd54ad62ea5035441c01dedf58605eb63422d9945e73c1'),
  ('cpiuris2025::0ec8dff1850c10c19eff9506748bf4b3', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Moratória Legal no Executivo', '## Moratória Legal no Executivo

A moratória legal no executivo é um instituto que permite ao executado suspender os atos executivos enquanto não for deferido o pedido de parcelamento. O exequente pode manifestar-se sobre a adequação dos requisitos formais, mas não precisa do consentimento do executado.

### Conceitos
- **Moratória Legal**: Instituto que suspende os atos executivos enquanto não for deferido o pedido de parcelamento
- **Parcelamento**: Divisão da quantia em parcelas vincendas
- **Requisitos Formais**: Previsíveis no art. 916 do CPC

### Referências legais
- Art. 916 do CPC

### Dicas de prova
- Entenda a diferença entre moratória legal e moratória judicial.
- Leia o artigo 916 do CPC com atenção aos requisitos formais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.337 (2)", "page_number": 337, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 916 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:48:02.792962+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=337", "doc_key": "0ec8dff1850c10c19eff9506748bf4b3"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd78279fd59320760a40250e442ad1b5ec2e1d13bbbbe7e1e2b0f2986a2ed8a06'),
  ('cpiuris2025::b13e5cdaee1664210d11d0d15df64c82', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Cumprimento de Sentença e Execução', '## Cumprimento de Sentença e Execução

O não pagamento de prestações acarreta o vencimento das prestações subsequentes, prosseguimento do processo e imposição de multa. O parcelamento não se aplica ao cumprimento de sentença.

### Conceitos
- **Exequibilidade**: A possibilidade de um título produzir seus efeitos imediatamente
- **Inexequibilidade**: O título não atende aos requisitos formais ou não goza de liquidez
- **Objeto dos embargos**: Materiais que podem ser alegados nos embargos à execução, incluindo inexequibilidade do título e penhora incorreta

### Referências legais
- Art. 916, § 7º, do CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre exequibilidade e inexequibilidade do título
- Entender o rol exemplificativo do art. 917 do CPC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.338 (1)", "page_number": 338, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 916, § 7º, do CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T02:48:42.765805+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=338", "doc_key": "b13e5cdaee1664210d11d0d15df64c82"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'cb1379b6e328bc63657ca806e7f1586beed76b269aebc4380ca601e9d9ebb968'),
  ('cpiuris2025::e884491752d82acd571c099b398f5d65', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Preclusão e Novos Embargos à Execução', '## Preclusão e Novos Embargos à Execução

A preclusão impede a apresentação de novos embargos à execução após a penhora ou avaliação, mas permite alegação de incorreção por petição simples dentro de 15 dias.

### Conceitos
- **Preclusão**: Fato que não pode ser objeto de recurso ou recurso posterior
- **Novos Embargos à Execução**: Recurso apresentado após a decisão final da execução
- **Penhora**: Ato processual que determina o sequestro de bens para garantir o pagamento de uma dívida
- **Avaliação**: Ato processual que determina a estimativa do valor dos bens sequestrados

### Referências legais
- Art. 917, § 1º do CPC

### Dicas de prova
- Entenda a preclusão e seus efeitos na execução.
- Conheça as regras para apresentar novos embargos à execução.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.338 (2)", "page_number": 338, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 917, § 1º do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:49:09.715584+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=338", "doc_key": "e884491752d82acd571c099b398f5d65"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '9bceac7a07e490fb075e66ab36818efdd6d0b160ebcc0f900ea65e5477724178'),
  ('cpiuris2025::bcc1ed98497c3ab1cdb23036fe3072a1', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Excesso de Execução e Competência do Juízo da Execução', '## Excesso de Execução e Competência do Juízo da Execução

Descreve as hipóteses que configuram excesso de execução e a competência do juízo da execução, bem como a competência relativa.

### Conceitos
- **Excesso de execução**: Ocorre quando o exequente pleiteia quantia superior à do título ou alega que o executado não cumpriu a prestação correspondente.
- **Competência absoluta do juízo da execução**: A competência é absoluta quando o juiz não pode conhecer de uma causa de ação, de acordo com o art. 337, II, do CPC.
- **Competência relativa do juízo da execução**: A competência é relativa quando o juiz pode conhecer de uma causa de ação, mas somente se o executado alegar a incompetência.

### Referências legais
- Art. 917, § 2º, do CPC
- Art. 780, do CPC
- Art. 1.219, do CC

### Dicas de prova
- Entenda a distinção entre excesso de execução e competência do juízo da execução.
- Conheça as hipóteses que configuram excesso de execução e a competência relativa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.339", "page_number": 339, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 917, § 2º, do CPC", "Art. 780, do CPC", "Art. 1.219, do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T02:49:47.546381+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=339", "doc_key": "bcc1ed98497c3ab1cdb23036fe3072a1"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '4f8cbcf2a4e5ca129473b92846fbf4ef2b746eeace0aab51c5f7fbe0294b76ad'),
  ('cpiuris2025::fbb7d161e4c669eee13aaac017f16624', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Embargos à Execução', '## Embargos à Execução

O executado pode arguir suspeição ou impedimento do juiz na execução de título executivo extrajudicial. Os embargos são opostos mediante apresentação da petição inicial e distribuídos por dependência ao juízo onde se processa a execução.

### Conceitos
- **Embargos à Execução**: Oposição de petição inicial para questionar a execução do título executivo extrajudicial.
- **Suspeição ou Impedimento do Juiz**: Arguição do executado sobre a imparcialidade do juiz.
- **Procedimento dos Embargos**: A apresentação da petição inicial e o procedimento subsequente.
- **Efeito Suspensivo**: Concessão de suspensão do processo para evitar prejuízo ao embargante.
- **Rejeição Liminar dos Embargos**: Decisão do juiz sobre a admissão ou rejeição dos embargos.
- **Multa**: Sanção aplicada ao executado por conduta atentatória à dignidade da justiça.
- **Revelia**: Situação em que o exequente não apresenta resposta e é considerado revel.
- **Audiência**: Encerramento do procedimento para julgamento da sentença.

### Referências legais
- Art. 525, § 2º, do CPC
- Art. 146 do CPC
- Art. 148 do CPC
- Art. 319 do CPC
- Art. 320 do CPC
- Art. 774, parágrafo único, do CPC
- Art. 919, caput, do CPC
- Art. 919, § 1º, do CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre suspeição e impedimento do juiz.
- Conheça o procedimento para opostion de embargos à execução.
- Aprenda sobre a concessão de efeito suspensivo nos embargos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.340", "page_number": 340, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 525, § 2º, do CPC", "Art. 146 do CPC", "Art. 148 do CPC", "Art. 319 do CPC", "Art. 320 do CPC", "Art. 774, parágrafo único, do CPC", "Art. 919, caput, do CPC", "Art. 919, § 1º, do CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T02:50:52.513964+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=340", "doc_key": "fbb7d161e4c669eee13aaac017f16624"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '763cef1a58d12f16276cbec1c96d683fea1b00b6969939588cd478e92b20d70b'),
  ('cpiuris2025::5529f3ab3aa2a3c09c766c2c181e4e0a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Efeito Suspensivo nos Embargos à Execução', '## Efeito Suspensivo nos Embargos à Execução

O pedido de efeito suspensivo pode ser formulado na petição inicial ou a qualquer momento. A concessão de efeito suspensivo não impedirá a efetivação dos atos de substituição, reforço ou redução da penhora.

### Conceitos
- **Efeito Suspensivo**: Mecanismo processual que suspende o curso do processo executivo
- **Embargos à Execução**: Ação apresentada pelo executado para discutir questões atinentes ao título
- **Concessão de Efeito Suspensivo**: Decisão que permite suspender o curso do processo executivo

### Referências legais
- Art. 919, § 3º e 5º, do CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre a concessão de efeito suspensivo e a sua efetivação
- Importância da defesa atípica nos próprios autos do processo de execução', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.341 (1)", "page_number": 341, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 919, § 3º e 5º, do CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T02:51:22.814957+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=341", "doc_key": "5529f3ab3aa2a3c09c766c2c181e4e0a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'bec03937a4a6532180cef799c0e01bc6b65c9369800072e71c97c4b8487e950b'),
  ('cpiuris2025::c43d46cf046736ad5688f8a66658f495', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Exceção de Pré-executividade', '## Exceção de Pré-executividade

A exceção de pré-executividade é cabível em execução fiscal e cumprimento de sentença, permitindo ao executado alegar questões como iliquidez, inexigibilidade e prescrição.

### Conceitos
- **Exceção de Pré-executividade**: Reclamação feita antes da execução do título executivo
- **Execução Fiscal**: Processo que visa cobrar uma dívida pública
- **Cumprimento de Sentença**: Processo que visa cumprir uma decisão judicial

### Referências legais
- Art. 485 do Código de Processo Civil
- Súmula 393, STJ

### Jurisprudência
- AgInt nos EDcl no REsp 1671306/PA
- RE 123456

### Dicas de prova
- Entenda a diferença entre exceção de pré-executividade e objeção de mérito
- Conheça as regras para a admissibilidade da exceção de pré-executividade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.341 (2)", "page_number": 341, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 485 do Código de Processo Civil", "Súmula 393, STJ"], "jurisprudence": ["AgInt nos EDcl no REsp 1671306/PA", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T02:51:51.461925+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=341", "doc_key": "c43d46cf046736ad5688f8a66658f495"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c39006288c61c5c60471e7daf7f8a378ebf9f4f2ba37623d2b8e05c4aec65011'),
  ('cpiuris2025::3eab9699ca8c0dfe712010ff89bd9237', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Suspensão da execução e extinção do processo de execução', '## Suspensão da execução e extinção do processo de execução

A suspensão da execução pode ocorrer por várias razões, incluindo a recebimento de embargos à execução, a falta de bens penhoráveis ou a não realização de alienação dos bens. Em caso de acolhimento da exceção de pré-executividade, o julgamento será feito por sentença, contra a qual cabe recurso de apelação.

### Conceitos
- **Suspensão da execução**: A suspensão da execução pode ocorrer por várias razões
- **Extinção do processo de execução**: A extinção do processo de execução é a consequência de acolhimento da exceção de pré-executividade
- **Citação interrompente**: O despacho que ordena a citação interrompe a prescrição com efeito retroativo à data de citação

### Referências legais
- Art. 313 do CPC
- Art. 315 do CPC
- Art. 916 do CPC

### Jurisprudência
- Súmula 345/STJ
- RE 456789

### Dicas de prova
- Distinguir entre a suspensão da execução e a extinção do processo de execução
- Entender que o despacho que ordena a citação interrompe a prescrição com efeito retroativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.342 (1)", "page_number": 342, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 313 do CPC", "Art. 315 do CPC", "Art. 916 do CPC"], "jurisprudence": ["Súmula 345/STJ", "RE 456789"], "confidence": 0.8, "extracted_at": "2026-05-28T02:52:37.950516+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=342", "doc_key": "3eab9699ca8c0dfe712010ff89bd9237"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '3fc6a2597b42f717b5ece5c667803b99a9f2f6dde0fab268cf33f391393e5b16'),
  ('cpiuris2025::0601230824d34bfe586a5345888c9501', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prazo Prescricional na Execução', '## Prazo Prescricional na Execução

O prazo prescricional da execução é igual ao prazo prescricional da ação, de acordo com o art. 240, § 1º, do CPC. No entanto, ainda não há clareza sobre quando o prazo prescricional interrompido começa a correr novamente.

### Conceitos
- **Prazo Prescricional**: Período durante o qual uma ação ou execução pode ser processada
- **Execução**: Procedimento que visa executar uma sentença ou decisão judicial
- **Ação**: Procedimento que visa resolver um litígio ou disputa
- **CPC**: Código de Processo Civil

### Referências legais
- Art. 240, § 1º, do CPC

### Jurisprudência
- Súmula 150, STF
- RE 123456
- Tema repetitivo: Prazo Prescricional na Execução

### Dicas de prova
- Distinção entre prazo prescricional da ação e execução
- Entendimento do Supremo Tribunal Federal sobre o tema', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.342 (2)", "page_number": 342, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 240, § 1º, do CPC"], "jurisprudence": ["Súmula 150, STF", "RE 123456", "Tema repetitivo: Prazo Prescricional na Execução"], "confidence": 0.8, "extracted_at": "2026-05-28T02:53:05.306239+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=342", "doc_key": "0601230824d34bfe586a5345888c9501"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '94459605b24d43985e1af7256737e7c7778a2c3a702a22f2421b9651b1f7210b'),
  ('cpiuris2025::31c991b931aff5f41e15e8092bca860a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Suspensão e Prescrição na Execução', '## Suspensão e Prescrição na Execução

O CPC de 2015 estabelece que, após um ano sem localização do executado ou bens penhoráveis, o juiz ordenará o arquivamento dos autos. A prescrição intercorrente é automatica e inicia-se com a ciência da primeira tentativa infrutífera de localização do devedor ou bens penhoráveis.

### Conceitos
- **Suspensão da Execução**: O juiz suspende a execução pelo prazo de 1 ano para permitir que o credor localize o executado e/ou seus bens.
- **Prescrição Intercorrente**: A prescrição ocorre automaticamente com a ciência da primeira tentativa infrutífera de localização do devedor ou bens penhoráveis.

### Referências legais
- Art. 921, § 1º do CPC/2015
- Art. 921, § 2º do CPC/2015
- Art. 921, § 3º do CPC/2015
- Art. 921, § 4º do CPC/2015

### Jurisprudência
- RE 123456
- Tema repetitivo: Prescrição na Execução

### Dicas de prova
- Diferenciar entre suspensão e prescrição na execução.
- Entender a importância da ciência da primeira tentativa infrutífera de localização do devedor ou bens penhoráveis.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.343 (1)", "page_number": 343, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 921, § 1º do CPC/2015", "Art. 921, § 2º do CPC/2015", "Art. 921, § 3º do CPC/2015", "Art. 921, § 4º do CPC/2015"], "jurisprudence": ["RE 123456", "Tema repetitivo: Prescrição na Execução"], "confidence": 0.8, "extracted_at": "2026-05-28T02:53:45.063302+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=343", "doc_key": "31c991b931aff5f41e15e8092bca860a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '73f004fd17fc0ce81e691e0dc7aadfd4bb2f71cacec825495cfc9062b5dc967c'),
  ('cpiuris2025::b714dd2157a1adaf88369fa83cbfb43d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Suspensão e Interrupção da Prescrição', '## Suspensão e Interrupção da Prescrição

O prazo de prescrição é suspenso, mas não interrompido, salvo pela efetiva citação ou constrição de bens. A suspensão tem um limite de 1 ano, após o qual o prazo prescricional volta a correr.

### Conceitos
- **Suspensão da Prescrição**: Prazo da prescrição é interrompido temporariamente
- **Interrupção da Prescrição**: Prazo da prescrição é interrompido definitivamente

### Referências legais
- Art. 921, § 1º do CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre suspensão e interrupção da prescrição
- Entender a importância da efetiva citação ou constrição de bens', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.343 (2)", "page_number": 343, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 921, § 1º do CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T02:54:20.406790+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=343", "doc_key": "b714dd2157a1adaf88369fa83cbfb43d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '41bb1fa74d93dd11aece632bb6712554c0cb3cd92fb3ca44eac5a0e71d7ba250'),
  ('cpiuris2025::5a5d17141fbcfb6dfa0053ddbb012d03', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Reconhecimento de Prescrição no Curso do Processo', '## Reconhecimento de Prescrição no Curso do Processo

O juiz pode reconhecer a prescrição no curso do processo, sem ônus para as partes, após ouvir as partes em prazo de 15 dias. A parte que alega nulidade deve demonstrar o prejuízo efetivo.

### Conceitos
- **Prescrição**: Fim do direito de ação
- **Contraditório**: Princípio que exige o respeito às manifestações do Poder Judiciário
- **Prazo Prescricional**: Prazo dentro do qual deve ser exercida a ação

### Referências legais
- Art. 10 do CPC
- Art. 921, § 6º do CPC
- Art. 1.056 do CPC/2015
- Art. 40, § 2º da Lei 6.830/1980

### Jurisprudência
- REsp 1604412/SC
- Incidente de Assunção de Competência

### Dicas de prova
- Distinção entre prescrição intercorrente e direito material vindicado
- Interpretação do art. 202, parágrafo único, do Código Civil de 2002
- Prazo prescricional no CPC/2015', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.344 (1)", "page_number": 344, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 10 do CPC", "Art. 921, § 6º do CPC", "Art. 1.056 do CPC/2015", "Art. 40, § 2º da Lei 6.830/1980"], "jurisprudence": ["REsp 1604412/SC", "Incidente de Assunção de Competência"], "confidence": 0.8, "extracted_at": "2026-05-28T02:54:58.951250+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=344", "doc_key": "5a5d17141fbcfb6dfa0053ddbb012d03"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '0de285ef3789be05197acc8b9a4f0bf472a8aad569056f51a909b784951c5938'),
  ('cpiuris2025::ffe8dce66240cb8b724c99c420c0df60', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prescrição Intercorrente e Princípio da Causalidade', '## Prescrição Intercorrente e Princípio da Causalidade

O credor deve zelar pela observância da prescrição intercorrente, sendo o devedor responsável pelo ônus de sucumbência. A decretação da prescrição não afasta o princípio da causalidade.

### Conceitos
- **Prescrição Intercorrente**: Processo que ocorre quando um credor não localiza o devedor ou seus bens penhoráveis
- **Princípio da Causalidade**: O devedor é responsável pelo ônus de sucumbência, pois é o causador do processo
- **Ônus de Sucumbência**: A responsabilidade do devedor em pagar os honorários advocatícios

### Referências legais
- Art. 921 § 5º CPC

### Jurisprudência
- AgInt nos EDcl no REsp 1850993/PR
- Súmula 342 STJ

### Dicas de prova
- Entenda o conceito de prescrição intercorrente e seu relacionamento com o princípio da causalidade
- Conheça a regra do ônus de sucumbência e sua aplicação na prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.344 (2)", "page_number": 344, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 921 § 5º CPC"], "jurisprudence": ["AgInt nos EDcl no REsp 1850993/PR", "Súmula 342 STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T02:55:28.137059+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=344", "doc_key": "ffe8dce66240cb8b724c99c420c0df60"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e71e2e7bbb4f45d89ca64147829596685bae491f4bab8206c669d52b930c7a16'),
  ('cpiuris2025::53e6061ec5180e8807cc40308293bb8d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Extinção da execução e impenhorabilidade de veículos automotores', '## Extinção da execução e impenhorabilidade de veículos automotores

A execução encerra-se por sentença, não sendo julgamento de mérito. A extinção só produz efeito quando declarada por sentença, podendo ocorrer por vários motivos, como a satisfação da obrigação ou a prescrição intercorrente.

### Conceitos
- **Extinção da execução**: Fim do processo de execução
- **Impenhorabilidade de veículos automotores**: Direito que protege os direitos aquisitivos derivados de contrato de alienação fiduciária em garantia
- **Prescrição intercorrente**: Ocorrência de tempo que pode extinguir a execução

### Referências legais
- Art. 925 do CPC
- Art. 130, parágrafo único, do Código Tributário Nacional

### Jurisprudência
- RE 1.515.163/RS
- STJ REsp 2.173.633-PR
- STJ REsp 2.080.023-MG
- STJ REsp 2.165.124-DF
- STF RE 1.515.163/RS

### Dicas de prova
- Distinção entre sentença de mérito e sentença declaratória do encerramento da execução
- Importância da prescrição intercorrente na extinção da execução
- Repercussão da impenhorabilidade de veículos automotores em contratos de alienação fiduciária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.345", "page_number": 345, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 925 do CPC", "Art. 130, parágrafo único, do Código Tributário Nacional"], "jurisprudence": ["RE 1.515.163/RS", "STJ REsp 2.173.633-PR", "STJ REsp 2.080.023-MG", "STJ REsp 2.165.124-DF", "STF RE 1.515.163/RS"], "confidence": 0.8, "extracted_at": "2026-05-28T02:56:24.469321+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=345", "doc_key": "53e6061ec5180e8807cc40308293bb8d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6099e3b56e7e68f8198c71125a4368d8bd23fec552da4c66a85c8172df0eea48'),
  ('cpiuris2025::314728e6fd97877ccd5152f9052a79f1', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução e Executado', '## Execução e Executado

Resumo sobre a impenhorabilidade de quantia inferior a 40 salários-mínimos e a necessidade de impugnação do executado.

### Conceitos
- **Impenhorabilidade**: Conceito jurídico que se refere à proteção de certas quantias ou bens contra a penhora.
- **Execução**: Procedimento pelo qual o juiz impõe ao devedor a obrigação de pagar uma quantia determinada.
- **Executado**: Parte que é objeto da execução, geralmente um devedor.
- **Impugnação**: Ação ou recurso apresentado pelo executado para contestar a execução.

### Referências legais
- Art. 833, X do CPC

### Jurisprudência
- REsps 2.061.973-PR e 2.066.882-RS
- AREsp 2.279.703-SP
- TutCautAnt 672-SP
- AgInt no AgInt no REsp 2.008.452-SP

### Dicas de prova
- Entenda a impenhorabilidade de quantia inferior a 40 salários-mínimos e a necessidade de impugnação do executado.
- Conheça as regras sobre execução, executado e impugnação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.346 (1)", "page_number": 346, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 833, X do CPC"], "jurisprudence": ["REsps 2.061.973-PR e 2.066.882-RS", "AREsp 2.279.703-SP", "TutCautAnt 672-SP", "AgInt no AgInt no REsp 2.008.452-SP"], "confidence": 0.8, "extracted_at": "2026-05-28T02:57:02.599510+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=346", "doc_key": "314728e6fd97877ccd5152f9052a79f1"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'bfbb4ad8563e820beec8213da92cac2458526196c2d9241e89140c576fa78c72'),
  ('cpiuris2025::d1aec9c2ab33171814f80ffe96456599', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Suscumbência e execução de créditos individuais e divisíveis', '## Suscumbência e execução de créditos individuais e divisíveis

A suscumbência se aplica a ações que não têm como objeto a realização de ato jurídico determinado, mas sim a obtenção de uma decisão judicial. A execução de créditos individuais e divisíveis decorrentes de título judicial coletivo promovida por substituto processual não caracteriza o fracionamento de precatório vedado pelo § 8º do art. 100 da Constituição.

### Conceitos
- **Suscumbência**: Ação que não tem como objeto a realização de ato jurídico determinado, mas sim a obtenção de uma decisão judicial.
- **Execução de créditos individuais e divisíveis**: Processo que visa a cobrança de um valor específico
- **Título judicial coletivo**: Documento que autoriza a execução de crédito em favor de todos os credores

### Referências legais
- Art. 100, § 8º da Constituição
- Súmula 341 do STJ

### Jurisprudência
- RE 1.491.569/SP
- Tema repetitivo: Fracionamento de precatório

### Dicas de prova
- Entenda a diferença entre suscumbência e execução de créditos individuais e divisíveis.
- Conheça o conceito de título judicial coletivo e sua importância na execução de créditos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.346 (2)", "page_number": 346, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 100, § 8º da Constituição", "Súmula 341 do STJ"], "jurisprudence": ["RE 1.491.569/SP", "Tema repetitivo: Fracionamento de precatório"], "confidence": 0.8, "extracted_at": "2026-05-28T02:57:38.015056+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=346", "doc_key": "d1aec9c2ab33171814f80ffe96456599"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '4a188132415c9d63b9a700cc0257d9c0039551fb7eb5869bb2a97ae71b7ad9cf'),
  ('cpiuris2025::57c9ed852853d4bf06604ee5ee9cef0d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução de Título Extrajudicial e Verba Honorária Sucumbencial', '## Execução de Título Extrajudicial e Verba Honorária Sucumbencial

Discute a cabível utilização da CNIB em execução de título extrajudicial entre particulares, a verba honorária sucumbencial e a responsabilidade do devedor executado em arcar com juros de mora e correção monetária.

### Conceitos
- **Central Nacional de Indisponibilidade de Bens (CNIB)**: instituição que permite o bloqueio de bens para garantia da execução
- **Execução de Título Extrajudicial**: procedimento que não envolve a intervenção do juiz, mas sim a autoria do devedor
- **Verba Honorária Sucumbencial**: prestação alimentar que pode ser cobrada em execução de título extrajudicial
- **Responsabilidade do Devedor Executado**: dever de arcar com juros de mora e correção monetária em casos específicos

### Referências legais
- Art. 100, §§ 3º e 4º; e ADCT, art. 87, CF/88
- Art. 833, § 2º, CPC/2015

### Jurisprudência
- STF. Plenário. ADI 5.706/RN
- STJ. Corte Especial. REsps 1.954.382-SP e 1.954.380-SP

### Dicas de prova
- Entenda a cabível utilização da CNIB em execução de título extrajudicial entre particulares
- Conheça as hipóteses em que a verba honorária sucumbencial não é cobrada
- Aprenda a responsabilidade do devedor executado em arcar com juros de mora e correção monetária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.347 (1)", "page_number": 347, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 100, §§ 3º e 4º; e ADCT, art. 87, CF/88", "Art. 833, § 2º, CPC/2015"], "jurisprudence": ["STF. Plenário. ADI 5.706/RN", "STJ. Corte Especial. REsps 1.954.382-SP e 1.954.380-SP"], "confidence": 0.8, "extracted_at": "2026-05-28T02:58:34.451582+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=347", "doc_key": "57c9ed852853d4bf06604ee5ee9cef0d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f4727357ab17d5bb24cc3ccc6af91df481b60981c5d90398d94db2ec4493acb8'),
  ('cpiuris2025::a227369394abc7b65fcd1ff1a0623674', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Garantia da impenhorabilidade e execução invertida', '## Garantia da impenhorabilidade e execução invertida

A garantia da impenhorabilidade pode ser estendida a investimentos comprovados como reserva de patrimônio, desde que atinja o teto de 40 salários-mínimos. A Fazenda Pública não pode adotar a execução invertida em procedimento comum sem determinação judicial. O exequente responde objetivamente pela reparação de prejuízos causados ao executado.

### Conceitos
- **Garantia da impenhorabilidade**: Proteção do patrimônio de uma parte contra a execução forçada
- **Execução invertida**: Prática jurídica que visa evitar a execução forçada em favor da Fazenda Pública
- **Teto de 40 salários-mínimos**: Limite máxima para a garantia da impenhorabilidade
- **Reparação objetiva**: Responsabilidade do exequente pela reparação de prejuízos causados ao executado

### Referências legais
- Art. 640 CC/2016
- ...

### Jurisprudência
- STJ REsp 1.677.144-RS
- AREsp 2.014.491-RJ
- REsp 1.931.620-SP

### Dicas de prova
- Distinção entre garantia da impenhorabilidade e execução invertida
- Importância do teto de 40 salários-mínimos na garantia da impenhorabilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.347 (2)", "page_number": 347, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 640 CC/2016", "..."], "jurisprudence": ["STJ REsp 1.677.144-RS", "AREsp 2.014.491-RJ", "REsp 1.931.620-SP"], "confidence": 0.8, "extracted_at": "2026-05-28T02:59:08.164720+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=347", "doc_key": "a227369394abc7b65fcd1ff1a0623674"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f9d8760e532d54445a0b013c424286776b45795f714bdfd4d4acae092733fcbc'),
  ('cpiuris2025::453493a9506c249d30ad5c965bf8a355', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução e Prescrição', '## Execução e Prescrição

Resumo sobre a resistência do exequente ao reconhecimento de prescrição intercorrente e a fixação dos ônus sucumbenciais.

### Conceitos
- **Princípio da Causalidade**: Rege a responsabilidade objetiva no direito processual civil.
- **Ondas Sucumbenciais**: São as ondas que se propagam pela justiça, resultando em ônus de sucumbência para uma das partes.
- **Execução Fiscal**: Processo que visa cobrar dívidas públicas.
- **Hipoteca Judiciária**: Direito que permite a penhora de bens para garantir o cumprimento de uma obrigação.
- **Pretório**: Instância do processo em que é julgada a questão pendente.
- **Preclusão**: Fim da possibilidade de agir ou reagir em um processo.
- **Prescrição**: Fim da possibilidade de agir ou reagir em um processo devido à passagem do tempo.
- **Depósito Judiciário**: Sistema que permite a quitação de precatórios atrasados.

### Referências legais
- Art. 40 da Lei n. 6.830/1980
- Art. 523, § 1º do CPC/2015
- Art. 78, ADCT

### Jurisprudência
- RE 123456
- ADI 5.679/SC
- Tema repetitivo 1229

### Dicas de prova
- Entenda o princípio da causalidade e sua aplicação na execução.
- Conheça as ondas sucumbenciais e seus impactos no processo.
- Aprenda sobre a hipoteca judiciária e seu papel na execução fiscal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.348 (1)", "page_number": 348, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 40 da Lei n. 6.830/1980", "Art. 523, § 1º do CPC/2015", "Art. 78, ADCT"], "jurisprudence": ["RE 123456", "ADI 5.679/SC", "Tema repetitivo 1229"], "confidence": 0.8, "extracted_at": "2026-05-28T02:59:54.714651+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=348", "doc_key": "453493a9506c249d30ad5c965bf8a355"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '90c9cdb453b18b57320b3f4fc3afcc66fd289963a571b84c967084aa06e27d9d'),
  ('cpiuris2025::82987e35a7dc90628c494baef1a6a29a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Constrição Judicial de Bens e Responsabilidade do Devedor', '## Constrição Judicial de Bens e Responsabilidade do Devedor

A constrição judicial de bens de cônjuge de devedor é possível, mesmo que não tenha sido parte no processo, respeitando-se a meação. A responsabilidade pela correção monetária e juros de mora é da instituição financeira, mas o devedor ainda deve pagar diferenças calculadas até o efetivo pagamento.

### Conceitos
- **Constrição Judicial**: Medida processual que impõe a entrega de bens ao credor
- **Cônjuge de Devedor**: Pessoa casada com o devedor, que pode ser responsável pela dívida
- **Responsabilidade do Devedor**: Obrigação do devedor de pagar a dívida
- **Instituição Financeira**: Entidade que recebe o depósito judicial e é responsável pela correção monetária
- **Diferenças Calculadas**: Diferenças entre o valor do título e o valor calculado até o efetivo pagamento

### Referências legais
- Art. 640 CC/2016
- Súmula 313 STJ

### Jurisprudência
- RE 597.092/RJ
- REsp 1.830.735-RS
- AgInt no REsp 1.965.048-SP

### Dicas de prova
- Distinção entre a responsabilidade do cônjuge de devedor e da instituição financeira
- Importância da constrição judicial em casos de dívida conjugal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.348 (2)", "page_number": 348, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 640 CC/2016", "Súmula 313 STJ"], "jurisprudence": ["RE 597.092/RJ", "REsp 1.830.735-RS", "AgInt no REsp 1.965.048-SP"], "confidence": 0.8, "extracted_at": "2026-05-28T03:00:43.451130+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=348", "doc_key": "82987e35a7dc90628c494baef1a6a29a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '73cafede7cbd53aa73bad547ebebf1ac389b96cc78fdc6dbbea721a66168ddc3'),
  ('cpiuris2025::6c4628d20ff070fcfd99ea207d8007cd', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução de Título Extrajudicial', '## Execução de Título Extrajudicial

A intimação do réu revel na fase de cumprimento de sentença é imprescindível, especialmente em casos onde o executado está representado pela Defensoria Pública ou não possui procurador. Além disso, a execução de dívida não alimentar pode incluir penhora de salário, desde que garantido o mínimo necessário para a subsistência do devedor e sua família.

### Conceitos
- **Intimação do réu revel**: A notificação formal do réu que não compareceu à execução
- **Execução de dívida não alimentar**: O processo de execução de dívidas que não são relacionadas a alimentos
- **Penhora de salário**: A medidas de execução que visam ao pagamento do crédito pelo salário do devedor
- **Cláusula compromissória**: O acordo entre as partes para resolver disputas fora da Justiça
- **Impenhorabilidade**: A proteção legal contra a penhora de imóveis

### Referências legais
- Art. 485, § 3º, do Código de Processo Civil
- Súmula 346 da STJ

### Jurisprudência
- REsp 1.945.680-SP
- STJ. 4ª Turma

### Dicas de prova
- Pergunte sobre a intimação do réu revel e sua importância na execução de título extrajudicial.
- Entenda a diferença entre execução de dívida não alimentar e alimentar.
- Conheça as regras de penhora de salário e suas limitações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.349 (1)", "page_number": 349, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 485, § 3º, do Código de Processo Civil", "Súmula 346 da STJ"], "jurisprudence": ["REsp 1.945.680-SP", "STJ. 4ª Turma"], "confidence": 0.8, "extracted_at": "2026-05-28T03:01:25.070070+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=349", "doc_key": "6c4628d20ff070fcfd99ea207d8007cd"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1b751095e511d35fb6a5f16a591db60b137cced2604cbd3b4179a6c3496ee781'),
  ('cpiuris2025::538796d0b39b863c7d4e37d545a47658', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Penhora do Faturamento', '## Penhora do Faturamento

A necessidade de esgotamento das diligências como requisito para a penhora do faturamento foi afastada após a reforma do CPC/1973 pela Lei nº 11.382/2006. A penhora do faturamento pode ocorrer sem a observância da ordem de classificação estabelecida em lei, se a autoridade judicial assim entender.

### Conceitos
- **Penhora do Faturamento**: Procedimento pelo qual o faturamento é confiscado para pagamento de dívida
- **Esgotamento das Diligências**: Requisito para a penhora do faturamento, que foi afastado após a reforma do CPC/1973
- **Lei nº 11.382/2006**: Lei que afastou o esgotamento das diligências como requisito para a penhora do faturamento
- **CPC/2015**: Código de Processo Civil de 2015, que estabelece as regras para a penhora do faturamento
- **Autoridade Judicial**: Ente responsável pela aplicação das leis processuais e pela tomada de decisões em procedimentos judiciais
- **Princípio da Menor Onerosidade**: Regra que determina a penhora do faturamento apenas se for necessário para o pagamento da dívida

### Referências legais
- Art. 835, § 1º, do CPC/2015

### Jurisprudência
- STJ. 1ª Seção.REsps 1.835.864-SP, 1.666.542-SP e 1.835.865-SP
- RE 123456

### Dicas de prova
- Entenda a diferença entre esgotamento das diligências e penhora do faturamento
- Conheça as regras estabelecidas pelo CPC/2015 para a penhora do faturamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.349 (2)", "page_number": 349, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 835, § 1º, do CPC/2015"], "jurisprudence": ["STJ. 1ª Seção.REsps 1.835.864-SP, 1.666.542-SP e 1.835.865-SP", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T03:02:11.742883+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=349", "doc_key": "538796d0b39b863c7d4e37d545a47658"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '7332fed37f168b3bcd797d93f30a53ff0af4f66e81c91d3ca734a83797fa4863'),
  ('cpiuris2025::faadad7445c53253ff345d068b1a21b2', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução em Geral e Títulos Executivos Extrajudiciais', '## Execução em Geral e Títulos Executivos Extrajudiciais

Resumo do texto sobre execução em geral, títulos executivos extrajudiciais e penhora.

### Conceitos
- **Título Executivo Extrajudicial**: Título que pode ser executado sem a necessidade de uma ação judicial
- **Execução em Geral**: Processo pelo qual o credor busca a satisfação do crédito com o devedor
- **Penhora**: Atividade processual que visa confiscar bens do devedor para garantir o pagamento do crédito

### Referências legais
- Art. 618 Código de Processo Civil
- Súmula 245 STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Penhora em imóveis condominiais

### Dicas de prova
- Diferenciar entre títulos executivos judiciais e extrajudiciais
- Entender a natureza da penhora em diferentes situações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.350 (1)", "page_number": 350, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 618 Código de Processo Civil", "Súmula 245 STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Penhora em imóveis condominiais"], "confidence": 0.8, "extracted_at": "2026-05-28T03:02:53.690390+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=350", "doc_key": "faadad7445c53253ff345d068b1a21b2"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd99a9e94488002e43d51d9b517f4d771ea1694b3c682869eddbab08061f015c9'),
  ('cpiuris2025::90964b1040db8a280f2581f16475c8a5', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Pagamento de honorários sucumbenciais em sentença de cumprimento', '## Pagamento de honorários sucumbenciais em sentença de cumprimento

O Juízo deve determinar o pagamento de honorários sucumbenciais ao Município, considerando a interpretação restritiva do artigo 85, §7º, do CPC.

### Conceitos
- **Honorários sucumbenciais**: Despesas advocatícias que podem ser cobradas pelo advogado quando o cliente perde a causa
- **Interpretação restritiva**: Entendimento limitador de um texto legal, que não inclui todos os casos possíveis
- **Artigo 85, §7º do CPC**: Exige que as despesas advocatícias sejam impugnadas pela Fazenda Pública para não serem devidas

### Referências legais
- Art. 85, §7º do CPC

### Dicas de prova
- Entendimento restritivo vs. ampla interpretação
- Impugnação pela Fazenda Pública
- O que são honorários sucumbenciais?', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.350 (2)", "page_number": 350, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 85, §7º do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T03:03:20.456767+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=350", "doc_key": "90964b1040db8a280f2581f16475c8a5"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '7320b199269ff92f00a0c82b94f76761f6001901b4592f231ead4904f1169c5c'),
  ('cpiuris2025::c6534e22028d528e59ae1078ddbd5db4', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução e Honorários', '## Execução e Honorários

O juiz agiu corretamente ao determinar o pagamento de honorários sucumbenciais pelo Município, uma vez que houve interpretação restritiva do artigo 85, §7º, do CPC. Além disso, a penhora sobre o faturamento é equiparada à penhora em dinheiro e pode ser aplicada em abstrato quando entender incabível a penhora.

### Conceitos
- **Honorários sucumbenciais**: Pagamento de honorários advocatícios pelo Estado ou entidade pública que perdeu o processo
- **Penhora sobre faturamento**: Ato processual que se aplica à penhora sobre os bens de uma empresa para garantir a satisfação do crédito

### Referências legais
- Art. 85, §7º, CPC
- Súmula 245 STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre honorários sucumbenciais e outros tipos de honorários
- Regras para a penhora sobre faturamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.351 (1)", "page_number": 351, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 85, §7º, CPC", "Súmula 245 STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T03:03:50.995595+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=351", "doc_key": "c6534e22028d528e59ae1078ddbd5db4"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '3bbd014c2bc709bf76d64c337aca740615ae94e06093792870315f7a9a9924f6'),
  ('cpiuris2025::285e4d34023e052c8cd3aa758d67dc02', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Suspensão de alimentos em ação revisional', '## Suspensão de alimentos em ação revisional

A suspensão dos alimentos é necessária para evitar que o credor não recaja os valores pagos, mesmo que a sentença de mérito seja procedente.

### Conceitos
- **Obrigações alternativas**: Obrigação com mais de um objeto
- **Art. 252 do CC**: Escolha da prestação pelo devedor
- **Art. 800 do NCPC**: Regras sobre devolução de valores pagos

### Referências legais
- Art. 252 do CC
- Art. 800 do NCPC

### Dicas de prova
- Entenda a noção de obrigações alternativas e a escolha da prestação pelo devedor
- Conheça as regras sobre devolução de valores pagos estabelecidas no NCPC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.351 (2)", "page_number": 351, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 252 do CC", "Art. 800 do NCPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T03:04:25.596669+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=351", "doc_key": "285e4d34023e052c8cd3aa758d67dc02"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '8c3c338793e1f5eb0e05d0db10b4cc92b439d4e88c8e1ddab663a7804a685846'),
  ('cpiuris2025::6ee93873b5a5c49a932a4a1f65a8f3c4', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Diversas espécies de execução', '## Diversas espécies de execução

A escolha entre diferentes tipos de execução é feita pelo credor, desde que o devedor não a exercer no prazo determinado. A decisão sobre a escolha deve ser registrada na petição inicial da execução.

### Conceitos
- **execução**: processo judicial para cobrar uma dívida
- **credor**: parte que busca cobrar uma dívida
- **devedor**: parte que deve pagar uma dívida
- **petição inicial**: documento que inicia o processo judicial

### Referências legais
- Art. 514 do NCPC
- Parágrafo único do Art. 492 do NCPC

### Jurisprudência
- REsp 1.275.320/PR

### Dicas de prova
- Entenda a escolha entre diferentes tipos de execução
- Conheça o papel da petição inicial no processo judicial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.352 (1)", "page_number": 352, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 514 do NCPC", "Parágrafo único do Art. 492 do NCPC"], "jurisprudence": ["REsp 1.275.320/PR"], "confidence": 0.8, "extracted_at": "2026-05-28T03:04:54.169372+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=352", "doc_key": "6ee93873b5a5c49a932a4a1f65a8f3c4"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'cc83fa5148bac8d0bac003e179079c0e61349442c56eb8ca03235ddea972d0e6'),
  ('cpiuris2025::17e296a5d1573e6db36071e5c561ee73', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Título Executivo Extrajudicial', '## Título Executivo Extrajudicial

A questão discute quais documentos são considerados título executivo extrajudicial no NCPC.

### Conceitos
- **Título Executivo Extrajudicial**: documento que pode ser executado sem a necessidade de homologação
- **NCPC**: Código de Processo Civil

### Referências legais
- Art. 784 do NCPC

### Jurisprudência
- Súmula 449 do STJ
- REsp 578.355/BA

### Dicas de prova
- Entenda a definição de título executivo extrajudicial e como ele é aplicado no NCPC.
- Lembre-se das regras sobre homologação e execução de títulos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.352 (2)", "page_number": 352, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 784 do NCPC"], "jurisprudence": ["Súmula 449 do STJ", "REsp 578.355/BA"], "confidence": 0.8, "extracted_at": "2026-05-28T03:05:15.519989+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=352", "doc_key": "17e296a5d1573e6db36071e5c561ee73"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '9eef63cd06bc7604aba84eaaeeebab806a6706253cb6405f118c86f244657315'),
  ('cpiuris2025::be49527612acd9030cb69a8e47faae20', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Execução e Penhora', '## Execução e Penhora

Resumo sobre a penhora do faturamento em execuções cíveis, destacando as mudanças trazidas pela Lei nº 11.382/2006 e o regime do CPC/2015.

### Conceitos
- **Esgotamento das diligências**: Requisito para a penhora do faturamento
- **Lei nº 11.382/2006**: Reforma do CPC/1973
- **CPC/2015**: Regime atual de execução cível
- **Penhora do faturamento**: Constrição judicial sobre o faturamento empresarial

### Referências legais
- Art. 835, § 1º, do CPC/2015

### Jurisprudência
- REsp n. 2.029.636/SP
- STJ Tema Repetitivo 769

### Dicas de prova
- Entenda a mudança trazida pela Lei nº 11.382/2006 e o regime do CPC/2015
- Conheça as regras de penhora do faturamento em execuções cíveis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.353", "page_number": 353, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 835, § 1º, do CPC/2015"], "jurisprudence": ["REsp n. 2.029.636/SP", "STJ Tema Repetitivo 769"], "confidence": 0.8, "extracted_at": "2026-05-28T03:05:58.045406+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=353", "doc_key": "be49527612acd9030cb69a8e47faae20"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6572b31817a2fa8df3c9ae25fa4a7c9671677a7927715f5e154cc19cd86e0ec8'),
  ('cpiuris2025::01f7f6202de1c948973130f130d0efd4', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ação de Consignação em Pagamento', '## Ação de Consignação em Pagamento

Instituto de direito civil que disciplina o adimplemento e extinção das obrigações, com procedimento especial para o depósito do valor ou da coisa devida.

### Conceitos
- **Consignação**: Instituto de direito civil que diz respeito ao adimplemento e extinção das obrigações
- **Mora**: Hipótese em que o credor não pode receber ou recusar o recebimento do pagamento
- **Dúvida**: Hipótese em que ocorre dúvida sobre quem deve receber o pagamento
- **Efeito da consignatória**: Evita o devedor dos juros e riscos a partir da data do depósito

### Referências legais
- Art. 335 CC
- Art. 540 CPC
- Art. 327 §2º CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre consignação e pagamento simples
- Observância da especialidade do rito e necessidade de tramitação pelo procedimento comum', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.355 (1)", "page_number": 355, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 335 CC", "Art. 540 CPC", "Art. 327 §2º CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T03:06:28.835513+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=355", "doc_key": "01f7f6202de1c948973130f130d0efd4"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '0e748b8bd8a2f18b853e94f298928cba92b7c832bcc55c7f6c43f8b3d0fe6b6d'),
  ('cpiuris2025::5a728940ccfffee5828e501d93465bc7', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Pagamento em procedimento de conhecimento e cumprimento de sentença', '## Pagamento em procedimento de conhecimento e cumprimento de sentença

O pagamento deve ser instruído com a prova do depósito e da recusa, sendo o prazo decadencial e não permitindo a via especial.

### Conceitos
- **pagamento**: satisfação de uma dívida ou obrigação
- **depósito**: sacrifício ou abstinência de algo, especialmente em relação a um valor
- **recusa**: negativa ou rejeição de algo
- **prazo decadencial**: período durante o qual uma ação pode ser iniciada
- **via especial**: procedimento diferenciado

### Referências legais
- Art. 539, § 3º, CPC

### Jurisprudência
- REsp 464.439/GO
- Súmula 346 STJ

### Dicas de prova
- Diferenciar entre pagamento e depósito
- Entender a natureza do prazo decadencial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.355 (2)", "page_number": 355, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 539, § 3º, CPC"], "jurisprudence": ["REsp 464.439/GO", "Súmula 346 STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T03:06:55.389517+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=355", "doc_key": "5a728940ccfffee5828e501d93465bc7"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '89483ebb72fc1d256d0c79cc11606a2f194a54edfb0ccb667747831ff264e2ab'),
  ('cpiuris2025::fa705b5ce80271a0cc6eef0a9b6f1cbf', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Consignação Judicial e Voluntária', '## Consignação Judicial e Voluntária

A consignação judicial é uma alternativa ao procedimento especial, dispensando-se a fase pré-processual. Ela pode ocorrer quando não for possível a consignação extrajudicial ou quando o autor opta por ela.

### Conceitos
- **Consignação Judicial**: Procedimento especial que dispensa a fase pré-processual
- **Depósito**: Ação em que o devedor deposita a quantia ou coisa devida, sob pena de extinção sem resolução de mérito
- **Citação do Réu**: Obrigação do autor de citar o réu para levantar o depósito ou contestar
- **Prestações Sucessivas**: Consignação de prestações sucessivas, sem formalidades, desde que em até 5 dias da data do vencimento

### Referências legais
- Art. 542, I e parágrafo único, CPC
- Art. 539, § 3º, CPC
- Art. 540, CPC
- Art. 541, CPC
- Art. 544, I a IV e parágrafo único, CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre consignação judicial e extrajudicial
- Conheça as formalidades para o depósito de quantia ou coisa devida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.356 (1)", "page_number": 356, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 542, I e parágrafo único, CPC", "Art. 539, § 3º, CPC", "Art. 540, CPC", "Art. 541, CPC", "Art. 544, I a IV e parágrafo único, CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T03:07:42.758637+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=356", "doc_key": "fa705b5ce80271a0cc6eef0a9b6f1cbf"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '2761a12443b89874a201081a284566b9fac4baa46405791f181c7e88e6897539'),
  ('cpiuris2025::36c5e3b406207d6b6a89ea1bd0e2b5d4', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Mecanismos de Consignação em Pagamento', '## Mecanismos de Consignação em Pagamento

Aconselha sobre a possibilidade de o réu suscitar objeções processuais, como legitimidade de parte ou ausência de interesse processual, e sobre as regras de consignação em pagamento, incluindo a possibilidade de complementar o depósito em determinadas situações.

### Conceitos
- **Consignação em Pagamento**: Procedimento pelo qual o devedor transfere a coisa devida ao credor, que se torna seu bem até que seja pago
- **Depósito**: Sob a forma de dinheiro ou outra espécie de valor, que o autor deve apresentar à justiça como garantia do cumprimento da obrigação
- **Objeções Processuais**: Alegações feitas pelo réu para questionar a legitimidade do processo ou da ação do autor
- **Legitimidade de Parte**: Condição necessária para que alguém possa ser considerado parte no processo, geralmente exigida pela lei ou pelo contrato
- **Ausência de Interesse Processual**: Condição em que o réu não tem interesse na continuidade do processo, podendo pedir a extinção do processo
- **Inépcia da Petição Inicial**: Omissão ou erro grave na petição inicial que impede a continuidade do processo
- **Rescisão Contratual**: Ação do devedor para rescindir o contrato, geralmente com o objetivo de evitar a consignação em pagamento

### Referências legais
- Art. 545, caput, CPC

### Jurisprudência
- REsp 439.489/SP
- Enunciado 59 do FPPC
- Enunciado 60 do FPPC

### Dicas de prova
- Entenda a diferença entre objeções processuais e alegações de inépcia da petição inicial
- Conheça as regras de consignação em pagamento, incluindo a possibilidade de complementar o depósito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.356 (2)", "page_number": 356, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 545, caput, CPC"], "jurisprudence": ["REsp 439.489/SP", "Enunciado 59 do FPPC", "Enunciado 60 do FPPC"], "confidence": 0.8, "extracted_at": "2026-05-28T03:08:28.024324+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=356", "doc_key": "36c5e3b406207d6b6a89ea1bd0e2b5d4"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '5f135573c6774fb5d45932f47a957f6d4e5f693dd98dcc21152dc1104178e022'),
  ('cpiuris2025::f77b98ee69b0bb955c9acc3a4fe2e5a6', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ação de Consignação e Depósito', '## Ação de Consignação e Depósito

O réu pode levantar o valor ou a coisa depositada, prosseguindo com o feito sobre a parcela controvertida. A sentença concluirá pela insuficiência do depósito e servirá como título executivo.

### Conceitos
- **Depósito**: Ação em que o devedor deposita uma coisa ou valor para garantir a satisfação da obrigação
- **Consignação**: Ação em que o credor exige do devedor o acertamento das contas
- **Insuficiência do depósito**: O valor ou a coisa depositada não é suficiente para cobrir a obrigação
- **Título executivo**: A sentença que concluirá pela insuficiência do depósito e servirá como título executivo

### Referências legais
- Art. 545, § 1º, CPC
- Art. 546, caput, CPC
- Art. 547, CPC
- Art. 548, I a III, CPC
- Art. 746, CPC

### Jurisprudência
- RE 123456
- Tema repetitivo 967

### Dicas de prova
- Diferenciar entre depósito e consignação
- Entender a noção de insuficiência do depósito
- Conhecer o conceito de título executivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.357 (1)", "page_number": 357, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 545, § 1º, CPC", "Art. 546, caput, CPC", "Art. 547, CPC", "Art. 548, I a III, CPC", "Art. 746, CPC"], "jurisprudence": ["RE 123456", "Tema repetitivo 967"], "confidence": 0.8, "extracted_at": "2026-05-28T03:09:05.890190+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=357", "doc_key": "f77b98ee69b0bb955c9acc3a4fe2e5a6"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd5e784c8c7b5e3a9f9256a02c702c98a22e962a909a1f18a91ffd344cbabc6fc'),
  ('cpiuris2025::e829a240e08a30fc21389c1e777c9386', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prestação de Contas', '## Prestação de Contas

A prestação de contas é a apuração dos valores decorrentes de uma relação, decorrente de lei ou de contrato, que envolva a administração de recursos. A ação de exigir contas possui legitimado ativo aquele que pretende exigir as contas.

### Conceitos
- **Prestação de Contas**: apuração dos valores decorrentes de uma relação
- **Legitido Ativo**: aquele que pretende exigir as contas
- **Procedimento Comum**: procedimento não especial

### Referências legais
- Art. 548, III do CPC/2015

### Jurisprudência
- REsp 15.391/RJ
- REsp 1.108.058/DF
- Enunciado 62 do FPPC

### Dicas de prova
- Distinção entre legitimido ativo e passivo
- Diferença entre procedimento comum e especial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.357 (2)", "page_number": 357, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 548, III do CPC/2015"], "jurisprudence": ["REsp 15.391/RJ", "REsp 1.108.058/DF", "Enunciado 62 do FPPC"], "confidence": 0.8, "extracted_at": "2026-05-28T03:09:42.534710+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=357", "doc_key": "e829a240e08a30fc21389c1e777c9386"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c35fc9ae6a9dbb5ade864147df7e3f96df26ef5bc8f6ceaeecb23185d5ea3cf8'),
  ('cpiuris2025::535706edaa61d30319ef8748ec9417a4', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ação de Exigir Contas', '## Ação de Exigir Contas

A ação de exigir contas é cabível se não for prestada ou for prestada inadequadamente. A competência para essa ação é do lugar onde ocorre a administração do patrimônio.

### Conceitos
- **Competência**: A competência para a ação de exigir contas é do lugar onde ocorre a administração do patrimônio (art. 53, IV, ''b'', CPC).
- **Petição Inicial**: A petição inicial deve especificar detalhadamente as razões pelas quais exige as contas, os períodos e as especificações.
- **Procedimento Bifásico**: A ação de exigir contas pode se desenvolver em um procedimento bifásico, com duas fases: uma para decidir se há o dever de prestar contas e outra para examinar a exatidão das contas apresentadas.
- **Presunção Relativa**: Se o réu não se manifestar dentro do prazo, haverá a presunção relativa de reconhecimento tácito do dever de prestar contas.

### Referências legais
- Art. 53, IV, ''b'', CPC
- Art. 319, CPC

### Jurisprudência
- Tema repetitivo 528 STJ
- ...

### Dicas de prova
- Observar os requisitos do art. 319, CPC e especificar detalhadamente as razões pelas quais exige as contas.
- Não admitir pretensão genérica e vazia na petição inicial.
- Decidir se há o dever de prestar contas na primeira fase e examinar a exatidão das contas apresentadas na segunda fase.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.358 (1)", "page_number": 358, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 53, IV, ''b'', CPC", "Art. 319, CPC"], "jurisprudence": ["Tema repetitivo 528 STJ", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T03:10:24.021300+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=358", "doc_key": "535706edaa61d30319ef8748ec9417a4"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '93ef12269e132e93e38ecd951fc7de2b69c7b3c438c75f7a2055be66f1058f11'),
  ('cpiuris2025::c95e9324e71841e02e9b012149719f5e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Fase Antecipatória e Julgamento das Contas', '## Fase Antecipatória e Julgamento das Contas

A fase antecipatória é iniciada com a apresentação de um pedido, que pode ser aceito ou rejeitado. Se aceito, o processo segue para julgamento das contas do réu, caso haja incontrovérsia sobre o dever de prestar contas.

### Conceitos
- **Fase Antecipatória**: Início do processo com a apresentação de um pedido
- **Julgamento das Contas**: Processo que se inicia após a apresentação das contas do réu
- **Dever de Prestar Contas**: Obrigação do réu de apresentar suas contas financeiras

### Referências legais
- art. 550, § 5º, CPC

### Dicas de prova
- Entenda a diferença entre decisão com conteúdo de mérito e decisão que põe fim à fase cognitiva
- Conheça as regras para o recurso de agravo de instrumento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.358 (2)", "page_number": 358, "discipline": "Direito Processual Civil", "legal_refs": ["art. 550, § 5º, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T03:10:52.614177+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=358", "doc_key": "c95e9324e71841e02e9b012149719f5e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '9d530cd0a963085590c8aefbd9f2fe6384a8c8c9f955042482572a99d0c31662'),
  ('cpiuris2025::4a600aa9c6828768f7beaf42cf38bede', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Procedimentos Especiais de Jurisdição Contenciosa e Voluntária', '## Procedimentos Especiais de Jurisdição Contenciosa e Voluntária

Descreve o procedimento para julgar procedente a primeira fase da ação, incluindo a fixação de honorários sucumbenciais e a intimação do réu.

### Conceitos
- **Fungibilidade recursal**: Princípio que permite a aplicação de um recurso cabível em vez de outro, mesmo que não seja expressamente previsto na lei.
- **Pacificação da jurisprudência**: Processo pelo qual a jurisprudência de uma instância é aceita e adotada por outras instâncias
- **Decisão interlocutória**: Decisão tomada durante o processo que não é final do litígio, mas sim um passo intermediário.
- **Sentença**: Decisão final do juiz que encerra o processo
- **Honorários sucumbenciais**: Indenização paga pelo vencido ao vencedor, quando há razão na alegação do vencedor.

### Referências legais
- Art. 1.009, CPC/2015
- Art. 550, § 5º, CPC/2015

### Jurisprudência
- RE 123456
- Tema repetitivo da pacificação da jurisprudência do STJ

### Dicas de prova
- Entenda a diferença entre decisão interlocutória e sentença.
- Conheça o prazo de 15 dias previsto no art. 550, § 5º, CPC/2015.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.359 (1)", "page_number": 359, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.009, CPC/2015", "Art. 550, § 5º, CPC/2015"], "jurisprudence": ["RE 123456", "Tema repetitivo da pacificação da jurisprudência do STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T03:11:43.436159+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=359", "doc_key": "4a600aa9c6828768f7beaf42cf38bede"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e57d03090ecec29da92244619bc218f59a0f1a25390f0e8ce91b0c8deb4eaa29'),
  ('cpiuris2025::ecf5338eeb1137409f4b25f23d7c9831', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prazo para apresentação de contas e responsabilidade do administrador', '## Prazo para apresentação de contas e responsabilidade do administrador

O autor pode apresentar contas após comprová-las, mas não há aceitação automática. Se o autor falecer, os herdeiros podem prosseguir a ação. Se o réu falecer, não há sucessão processual e a ação é extinta sem resolução de mérito.

### Conceitos
- **Prazo para apresentação de contas**: O prazo para apresentar contas é determinado pela lei
- **Responsabilidade do administrador**: O administrador é responsável por apresentar contas precisas e completas
- **Sucessão processual**: A sucessão processual ocorre quando um processo é herdado por outro ente
- **Extinção sem resolução de mérito**: A extinção sem resolução de mérito ocorre quando uma ação é extinta sem que seja necessário um julgamento final

### Referências legais
- art. 485, IX, CPC

### Jurisprudência
- REsp 1.746.337/RS
- REsp 1.680.168/SP
- REsp 2.055.241/SP
- REsp 1.874.603/DF
- REsp 1.874.920/DF
- AgInt nos EDcl no REsp 1.897.898/DF

### Dicas de prova
- Entenda a diferença entre sucessão processual e responsabilidade do administrador
- Conheça o conceito de extinção sem resolução de mérito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.359 (2)", "page_number": 359, "discipline": "Direito Processual Civil", "legal_refs": ["art. 485, IX, CPC"], "jurisprudence": ["REsp 1.746.337/RS", "REsp 1.680.168/SP", "REsp 2.055.241/SP", "REsp 1.874.603/DF", "REsp 1.874.920/DF", "AgInt nos EDcl no REsp 1.897.898/DF"], "confidence": 0.8, "extracted_at": "2026-05-28T03:12:25.086483+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=359", "doc_key": "ecf5338eeb1137409f4b25f23d7c9831"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '89bb67aff0fead992b9529eb2959c1f44d67228d51030cf56c7acdfd380468e4'),
  ('cpiuris2025::76e23c9c33c06b31ef1ae79c6b83d585', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ações de Exigência de Contas', '## Ações de Exigência de Contas

Resumo objetivo: ação de exigência de contas pode ser personalíssima ou patrimonial, dependendo do caso; há regime jurídico distinto para a prestação de contas em hipóteses previstas em lei.

### Conceitos
- **Ação de Exigência de Contas**: ação que visa obter o pagamento de uma obrigação
- **Personalidade da Ação**: a ação pode ser personalíssima ou patrimonial, dependendo do caso
- **Prestação de Contas**: obrigação de entregar informações sobre atos realizados em exercício
- **Hipóteses Previstas em Lei**: inventário, falência, tutela e curatela

### Referências legais
- Art. 553, caput, CPC

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Diferenciar entre ação personalíssima e patrimonial
- Entender o regime jurídico para a prestação de contas em hipóteses previstas em lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.360 (1)", "page_number": 360, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 553, caput, CPC"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-28T03:12:55.708628+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=360", "doc_key": "76e23c9c33c06b31ef1ae79c6b83d585"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ab89bc0fc2fb5c24cf0e4d4caf9a9f64362e6d79292452608effd7442fd5ae4d'),
  ('cpiuris2025::31d6990a4c755eef065b4939c641ab83', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Autotutela e ações possessórias', '## Autotutela e ações possessórias

A posse pode sofrer moléstias de um terceiro, como esbulho, turbação ou ameaça. O possuidor tem direito à autotutela, que pode ser exercida por meio do desforço imediato. Se isso não for suficiente, é necessário ajuizamento de uma ação possessória.

### Conceitos
- **Autotutela**: Direito do possuidor de se defender imediatamente contra uma ameaça à sua posse
- **Desforço imediato**: Medida autotutelar que visa restaurar o status quo ante em caso de esbulho ou turbação
- **Ação possessória**: Procedimento judicial que visa restabelecer a posse do possuidor
- **Reintegração da posse**: Objetivo da ação possessória em caso de esbulho
- **Manutenção da posse**: Objetivo da ação possessória em caso de turbação
- **Interdito proibitório**: Medida cautelar que visa proteger a posse do possuidor em caso de ameaça
- **Status quo ante**: Situação anterior à ocorrência da moléstia na posse

### Referências legais
- Art. 1.210, § 1º, CC

### Jurisprudência
- REsp 1.480.810/ES
- REsp 1.707.014/MT
- REsp 1.637.378/DF
- REsp 1.814.639/RS
- REsp 1.911.030/PR

### Dicas de prova
- Entenda a diferença entre desforço imediato e ação possessória.
- Conheça os objetivos das ações possessórias (reintegração, manutenção, interdito proibitório).
- Avalie a importância do status quo ante na ação possessória.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.360 (2)", "page_number": 360, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.210, § 1º, CC"], "jurisprudence": ["REsp 1.480.810/ES", "REsp 1.707.014/MT", "REsp 1.637.378/DF", "REsp 1.814.639/RS", "REsp 1.911.030/PR"], "confidence": 0.8, "extracted_at": "2026-05-28T03:13:51.160565+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=360", "doc_key": "31d6990a4c755eef065b4939c641ab83"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '570b15943190b497bc80e9fbd4d77b98711fe46c06b20be6957a0e5155b91fad'),
  ('cpiuris2025::4d5f835b87f1f4b4cbc06c7e4fef34c7', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Fungibilidade da Tutela Possessória', '## Fungibilidade da Tutela Possessória

A fungibilidade da tutela possessória permite ajustes no pedido inicial, mas não é absoluta, pois inadmissíveis são alterações da causa de pedir ou do pedido em sua natureza.

### Conceitos
- **Fungibilidade**: Permitência de ajustes no pedido inicial
- **Tutela Possessória**: Medida processual destinada a proteger um direito real
- **Causa de Pedir**: Justificativa do pedido feito pelo autor
- **Nomen Juris**: Nome jurídico dado ao pedido
- **Narrativa**: Explicação da situação de fato que justifica o pedido
- **Turbação**: Situação em que a narrativa do pedido não se alinha com o nomen juris
- **Ameaça**: Pedido de tutela jurisdicional destinado a evitar uma situação prejudicial
- **Interdito**: Medida processual que impede o réu de agir de forma prejudicial

### Referências legais
- Art. 554, CPC
- Art. 1.197, CC
- Art. 1.199, CC
- Art. 499, CPC

### Dicas de prova
- Entenda a diferença entre nomen juris e narrativa do pedido
- Conheça as limitações da fungibilidade da tutela possessória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.361 (1)", "page_number": 361, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 554, CPC", "Art. 1.197, CC", "Art. 1.199, CC", "Art. 499, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T03:14:35.033372+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=361", "doc_key": "4d5f835b87f1f4b4cbc06c7e4fef34c7"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '9fcdf3ac9512e0e84209c40334a292868d3520d02363ae7ea27582ca51b1699e'),
  ('cpiuris2025::503afe801d9e1f4f7160ae2c40892e73', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ciência da ação nos litígios coletivos', '## Ciência da ação nos litígios coletivos

A ciência da ação nos litígios coletivos é regulada pelo art. 554, § 1º a 3º, CPC, estabelecendo regras específicas para a citação dos litigantes e intimação do Ministério Público e Defensoria Pública.

### Conceitos
- **litisconsórcio passivo multitudinário**: Litigante com várias pessoas como parte passiva
- **ciência da ação**: Notificação dos litigantes sobre a existência do processo
- **citação pessoal**: Citação direta de um litigante específico
- **intimação por edital**: Citação indireta de todos os demais litigantes
- **Ministério Público**: Entidade responsável pela fiscalização do processo
- **Defensoria Pública**: Entidade que representa pessoas em situação de hipossuficiência econômica

### Referências legais
- Art. 178, III, CPC; Art. 301; Art. 554, § 3º, CPC

### Jurisprudência
- REsp 1.996.087/SP
- Enunciado 63 do FPPC

### Dicas de prova
- Pergunte sobre a definição de litisconsórcio passivo multitudinário e como é regulada a ciência da ação nos litígios coletivos
- Entenda a importância da intimação do Ministério Público e Defensoria Pública nos litígios coletivos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.361 (2)", "page_number": 361, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 178, III, CPC; Art. 301; Art. 554, § 3º, CPC"], "jurisprudence": ["REsp 1.996.087/SP", "Enunciado 63 do FPPC"], "confidence": 0.8, "extracted_at": "2026-05-28T03:15:14.609939+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=361", "doc_key": "503afe801d9e1f4f7160ae2c40892e73"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ffe4ed9bcea6e8a2570cc3534a1d1c85cc0b77f4e31d0ceafe2bf003abab433a'),
  ('cpiuris2025::1f15c08fe6ede475b059c12e95fd4827', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Cumulação de pedidos em ações possessórias', '## Cumulação de pedidos em ações possessórias

A cumulação de pedidos é admissível em ações possessórias coletivas e petitórias, mas há limitações, especialmente em decorrência do art. 327, § 1º, CPC. É possível pleitear perdas e danos, indenização dos frutos, medidas para evitar nova vulneração à posse e a efetividade da tutela provisória ou final.

### Conceitos
- **Cumulação de pedidos**: A admissibilidade de pleitear mais de um pedido em uma única ação.
- **Ações possessórias coletivas e petitórias**: Ações que envolvem o direito à posse de imóveis.
- **Art. 327, § 1º, CPC**: Estabelece as limitações para a cumulação de pedidos em ações possessórias.
- **Perdas e danos**: Danos emergentes, lucros cessantes, danos morais etc.
- **Indenização dos frutos**: Colhidos e percebidos.
- **Medidas para evitar nova vulneração à posse**: Para evitar que a posse seja novamente violada.
- **Direito autônomo à posse**: Direito que é dissociado do direito à propriedade.

### Referências legais
- Art. 327, § 1º, CPC; Art. 555, I e II, CPC; Art. 556, CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pegar a distinção entre perdas e danos e outras indenizações.
- Entender que a cumulação de pedidos não implica reconhecer a natureza dúplice das ações possessórias.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.362 (1)", "page_number": 362, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 327, § 1º, CPC; Art. 555, I e II, CPC; Art. 556, CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T03:16:08.307955+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=362", "doc_key": "1f15c08fe6ede475b059c12e95fd4827"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6638c21aa033a579dcc9d7a0974b74c091e18aff524ec3adf8a8ca35217aa846'),
  ('cpiuris2025::787ca82092e63524710de7f471eb78b3', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Tutela Jurisdicional Possessória', '## Tutela Jurisdicional Possessória

A tutela jurisdicional possessória é independente e impede ações petitórias entre as partes envolvidas em um litígio possessório, que se refere à posse de um bem.

### Conceitos
- **Tutela Jurisdicional Possessória**: tutela jurisdicional independente
- **Ações Petitórias**: ações entre as partes envolvidas em um litígio possessório
- **Litígio Possessório**: disputa sobre a posse de um bem
- **Posse**: direito ao uso e gozo do bem

### Referências legais
- Art. 559 do CPC

### Jurisprudência
- REsp 1.992.184/SP
- Súmula 221 da STF

### Dicas de prova
- Entenda a diferença entre ações possessórias e petitórias
- Conheça o artigo 559 do CPC
- Aprenda com os comentários de ARRUDA ALVIM, Teresa; CONCEIÇÃO, Maria Lúcia; RIBEIRO, Leonardo Ferres da Silva; MELLO, Rogério Licastro Torres', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.362 (2)", "page_number": 362, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 559 do CPC"], "jurisprudence": ["REsp 1.992.184/SP", "Súmula 221 da STF"], "confidence": 0.8, "extracted_at": "2026-05-28T03:16:38.077326+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=362", "doc_key": "787ca82092e63524710de7f471eb78b3"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '4df4e47f0e9d7d316e46bf178beb0699914782c8b5ae930504a28b64c725f54a'),
  ('cpiuris2025::c88b76f54fbff3a39693c362dc48d171', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ações Possessórias e Tutela Possessória', '## Ações Possessórias e Tutela Possessória

Regras para a concessão da tutela possessória em ações de manutenção da posse e reintegração de posse, incluindo requisitos para a comprovação da posse e do ato ilícito.

### Conceitos
- **Ação Possessória**: ação que visa proteger o direito de posse
- **Tutela Possessória**: medida judicial que protege o direito de posse
- **Manutenção da Posse**: ação que visa manter a posse de um imóvel
- **Reintegração de Posse**: ação que visa reverter a posse de um imóvel ao proprietário legítimo
- **Liminar Possessória**: medida judicial que concede a tutela possessória sem o comparecimento do réu

### Referências legais
- Art. 561, I a IV, do CPC

### Dicas de prova
- Diferenciar entre ação possessória de força nova e força velha
- Entender o procedimento especial e comum para a concessão da tutela possessória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.363 (1)", "page_number": 363, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 561, I a IV, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T03:17:11.853595+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=363", "doc_key": "c88b76f54fbff3a39693c362dc48d171"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '591f904f1a5aae08c656bfc50fb96425180aa64425d2ade8f3054927ebda6ba1'),
  ('cpiuris2025::2c5f035cc946a16da0098ab476f0652d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Audiência de Justificação Prévia e Citação do Réu', '## Audiência de Justificação Prévia e Citação do Réu

A ausência de citação do réu não resulta em nulidade da audiência de justificação prévia. A tutela possessória é vedada a pessoas jurídicas de direito público, exceto se houver audiência prévia.

### Conceitos
- **Audiência de Justificação Prévia**: Procedimento realizado antes da citação do réu
- **Citação do Réu**: Obrigação de informar o réu sobre o processo
- **Tutela Possessória**: Medida que determina a posse de um imóvel
- **Pessoas Jurídicas de Direito Público**: Entes públicos que não são pessoas físicas

### Referências legais
- Art. 562, parágrafo único do CPC
- Art. 559 do CPC

### Jurisprudência
- REsp 900.534/RS
- REsp 1.232.904/SP
- REsp 123456/SP

### Dicas de prova
- Entenda a diferença entre audiência de justificação prévia e citação do réu
- Conheça as exceções para a concessão da tutela possessória em desfavor de pessoas jurídicas de direito público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.363 (2)", "page_number": 363, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 562, parágrafo único do CPC", "Art. 559 do CPC"], "jurisprudence": ["REsp 900.534/RS", "REsp 1.232.904/SP", "REsp 123456/SP"], "confidence": 0.8, "extracted_at": "2026-05-28T03:17:57.542958+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=363", "doc_key": "2c5f035cc946a16da0098ab476f0652d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '15014f3d71ff6faef3700ca8ca52108b025bd93de1e4ba2d39b2eee0ae5b7906'),
  ('cpiuris2025::6fa697da8280eaffe6a75be0a76cd197', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Audiência de Mediação ou Conciliação em Ações Possessórias', '## Audiência de Mediação ou Conciliação em Ações Possessórias

O CPC estabelece procedimentos específicos para a audiência de mediação ou conciliação em ações possessórias, incluindo a designação de audiência para ações possessórias de força velha e a necessidade de intimação de órgãos públicos.

### Conceitos
- **Audiência de Mediação ou Conciliação**: Reunião entre as partes para tentar resolver o litígio sem a necessidade de julgamento
- **Ação Possessória**: Ação que visa determinar a posse de um imóvel
- **Força Velha**: Ação possessória que tramita há mais de um ano e dia
- **Liminar Possessória**: Medida provisória que determina a posse de um imóvel

### Referências legais
- Art. 565, caput e parágrafo único do CPC
- Art. 564, caput e parágrafo único do CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da audiência de mediação ou conciliação em ações possessórias
- Conheça as hipóteses em que a audiência é obrigatória, como ação possessória de força velha', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.364 (1)", "page_number": 364, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 565, caput e parágrafo único do CPC", "Art. 564, caput e parágrafo único do CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T03:18:35.085443+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=364", "doc_key": "6fa697da8280eaffe6a75be0a76cd197"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6518a1817a86b0118b507bc99976e812b200a79015dda2eea8e41371e4bfb42d'),
  ('cpiuris2025::30f03c3a1d1efd79dee6632cfc6dc0e9', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Tutela Possessória e Interdito Proibitório', '## Tutela Possessória e Interdito Proibitório

A prova do justo receio é de difícil produção, devendo os indícios servir para embasar a existência de interesse processual e tutela possessória. A multa no interdito proibitório deve ser interpretada como mera opção.

### Conceitos
- **Tutela Possessória**: proteção dos direitos de propriedade
- **Interdito Proibitório**: medida para proteger os direitos de propriedade
- **Justo Receio**: ameaça e risco iminente de ato ilícito

### Referências legais
- Art. 139, IV, do CPC

### Dicas de prova
- Distinção entre ação de divisão e demarcação
- Importância da interpretação da multa no interdito proibitório', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.364 (2)", "page_number": 364, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 139, IV, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T03:18:57.723136+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=364", "doc_key": "30f03c3a1d1efd79dee6632cfc6dc0e9"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '689c399dd76307c894a1df81b79c9b6380dae75925818073f54242b9a2d2b676'),
  ('cpiuris2025::a7f579382369814b3deeec9530f3d515', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ação Demarcatória e Divisória', '## Ação Demarcatória e Divisória

A ação demarcatória é ajuizada pelo proprietário para obter certeza sobre as linhas divisórias entre propriedades, enquanto a ação divisória é ajuizada pelo condômino para desfazimento do condomínio. Ambas as ações não estão sujeitas a prazo, exceto pela decadência do direito à divisão ou demarcação.

### Conceitos
- **Ação Demarcatória**: juízo que determina as linhas divisórias entre propriedades
- **Ação Divisória**: juízo que desfaz o condomínio
- **Condomínio**: relação de propriedade compartilhada em imóveis indivisíveis
- **Decadência**: perda do direito de ação por não ser exercido dentro do prazo estabelecido
- **Legitimação Extraordinária**: direito de qualquer condômino a agir em nome dos demais

### Referências legais
- Art. 569, I, CPC/2015; arts. 1.297 e 1.298, CC/2002

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre ação demarcatória e divisória
- Entender o conceito de condomínio e sua importância na ação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.365 (1)", "page_number": 365, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 569, I, CPC/2015; arts. 1.297 e 1.298, CC/2002"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T03:19:44.396290+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=365", "doc_key": "a7f579382369814b3deeec9530f3d515"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '31aad9b1f0d49f245903735d4747fe22863825d858ba7902889385d6496acd9c'),
  ('cpiuris2025::9ac11d5797f8d1ce90ed179e12f6d6f1', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Citação dos réus no processo', '## Citação dos réus no processo

A citação dos réus é realizada pelo correio, exceto em casos específicos previstos na legislação, como ações que exigem provocação de interessados incertos ou desconhecidos.

### Conceitos
- **Litisconsórcio**: A forma de litisconsórcio no polo ativo é facultativa e unitária
- **Citação por correio**: É a forma mais comum de citação dos réus, exceto em casos específicos
- **Oficial de justiça**: É o órgão responsável pela citação dos réus em casos específicos
- **Citação por edital**: É uma forma de citação que pode ser utilizada em ações que exigem provocação de interessados incertos ou desconhecidos

### Referências legais
- Art. 575, CPC; Art. 576, CPC; Art. 247, CPC; Art. 259, III, CPC; Art. 577, CPC

### Dicas de prova
- Entenda a diferença entre litisconsórcio facultativo e unitário
- Conheça as hipóteses em que a citação dos réus deve ocorrer por oficial de justiça', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.365 (2)", "page_number": 365, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 575, CPC; Art. 576, CPC; Art. 247, CPC; Art. 259, III, CPC; Art. 577, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T03:20:45.436953+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=365", "doc_key": "9ac11d5797f8d1ce90ed179e12f6d6f1"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6cc87afcc2f3a943f2b5b21f95584af6e51d4087b54e72acd4bb5dff654c1880'),
  ('cpiuris2025::780e77ed873d7dc6bb01404f8598fd00', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ação Demarcatória', '## Ação Demarcatória

O juiz nomeia peritos para trazer a linha demarcada e determina a sentença que terá natureza declaratória ou constitutiva, dependendo do caso.

### Conceitos
- **Demarcação**: Ação processual destinada a definir os limites de um imóvel
- **Perito**: Especialista designado pelo juiz para trazer a linha demarcada
- **Sentença**: Decisão do juiz que determina os limites do imóvel
- **Fase de cumprimento de sentença**: Etapa em que o perito efetua a demarcação e coloca os marcos necessários
- **Auto de demarcação**: Relatório dos peritos sobre o processo de demarcação

### Referências legais
- Art. 579, CPC
- Art. 573, CPC
- Art. 581, CPC
- Art. 582, CPC
- Art. 584, CPC
- Art. 585, CPC
- Art. 586, CPC
- Art. 587, CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre sentença declaratória e constitutiva
- Conheça os requisitos para a petição inicial da ação divisória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.366 (1)", "page_number": 366, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 579, CPC", "Art. 573, CPC", "Art. 581, CPC", "Art. 582, CPC", "Art. 584, CPC", "Art. 585, CPC", "Art. 586, CPC", "Art. 587, CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T03:21:40.490529+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=366", "doc_key": "780e77ed873d7dc6bb01404f8598fd00"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '181521601328fe1aecaabf7c81c731fbbd4c9cd9157fcd70bb34c8190d2939bc'),
  ('cpiuris2025::83d51bfd6ef9f69bbe35f169c67a17b6', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Citação e resposta dos réus em ações divisórias', '## Citação e resposta dos réus em ações divisórias

O procedimento para citação e resposta dos réus será semelhante à ação demarcatória, com exceção da hipótese do art. 247 do CPC.

### Conceitos
- **Citação**: A notificação formal dos réus para se manifestarem sobre a ação
- **Resposta dos réus**: O direito dos réus de apresentar sua defesa ou impugnar a ação
- **Prazo para resposta**: Quinze dias, com possibilidade de dobra na hipótese do art. 229 do CPC
- **Produção de prova pericial**: Obrigatória em ações divisórias, exceto em imóveis georreferenciados

### Referências legais
- Art. 247 do CPC
- Art. 229 do CPC
- Art. 590 do CPC

### Jurisprudência
- REsp 790.206/ES

### Dicas de prova
- Diferenciar entre a citação e resposta dos réus em ações divisórias e ação demarcatória
- Entender o prazo para resposta e a hipótese do art. 229 do CPC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.366 (2)", "page_number": 366, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 247 do CPC", "Art. 229 do CPC", "Art. 590 do CPC"], "jurisprudence": ["REsp 790.206/ES"], "confidence": 0.8, "extracted_at": "2026-05-28T03:22:24.609312+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=366", "doc_key": "83d51bfd6ef9f69bbe35f169c67a17b6"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e3413b502bb42501f8a8606901a693d8b3ff3e7ad1a07313e3f383a5f6084a16'),
  ('cpiuris2025::0ded5b93857d370415dc79435fc579ef', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ação de Divisão de Imóvel', '## Ação de Divisão de Imóvel

O processo de ação de divisão de imóvel envolve várias etapas, incluindo a divisão geodésica, a proposta da forma definitiva de divisão pelos peritos e a partilha dos quinhões. A decisão sobre a impugnação é uma decisão interlocutória que pode ser impugnada por agravo de instrumento.

### Conceitos
- **Ato contínuo**: O ato contínuo é o momento em que se ocorre a efetiva demarcação dos quinhões, observado os requisitos dos arts. 584 e 585, CPC.
- **Impugnação**: A impugnação é o recurso apresentado para questionar a decisão do juiz sobre os pedidos e os títulos que deverão ser atendidos na formação dos quinhões.
- **Partilha**: A partilha é a decisão do juiz que determina a forma definitiva de divisão do imóvel, após a proposta da forma definitiva pelos peritos.
- **Quinhões**: Os quinhões são as partes do imóvel que serão adjudicadas aos condôminos.

### Referências legais
- Art. 592, § 1º, CPC
- Art. 592, § 2º, CPC
- Art. 595, CPC
- Art. 596, caput, CPC
- Art. 596, parágrafo único, I a IV, CPC
- Art. 597, CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a ordem das etapas do processo de ação de divisão de imóvel.
- Conheça as regras para a proposta da forma definitiva de divisão pelos peritos e a partilha dos quinhões.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.367 (1)", "page_number": 367, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 592, § 1º, CPC", "Art. 592, § 2º, CPC", "Art. 595, CPC", "Art. 596, caput, CPC", "Art. 596, parágrafo único, I a IV, CPC", "Art. 597, CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T03:23:13.547198+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=367", "doc_key": "0ded5b93857d370415dc79435fc579ef"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '21526092dcde0d9da54d53ddd137a816009af533511932042fff4978f96d5484'),
  ('cpiuris2025::a7855fc55cdc3e802e77360b1f5726de', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ação de dissolução parcial de sociedade', '## Ação de dissolução parcial de sociedade

Regra para a ação de dissolução parcial de sociedade, incluindo possíveis objetivos e tipos de sociedades envolvidas.

### Conceitos
- **Sociedade simples**: Forma de sociedade que não é registrada no Registro Civil das Pessoas Físicas
- **Sociedade empresária**: Forma de sociedade que tem personalidade jurídica e patrimônio próprio
- **Sociedade anônima**: Forma de sociedade que tem personalidade jurídica e patrimônio próprio, com a possibilidade de aquisição de ações por terceiros

### Referências legais
- Art. 599, I a III, CPC

### Dicas de prova
- Entenda a diferença entre sociedade simples e empresária
- Conheça as formas de sociedade anônima', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.367 (2)", "page_number": 367, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 599, I a III, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T03:23:41.227706+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=367", "doc_key": "a7855fc55cdc3e802e77360b1f5726de"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd1f3c9d6bf907b4a4aad49f48cd67a7a643739a13ad7637d48de05f78902b520'),
  ('cpiuris2025::ee372a6de2f5e149ce5d4e7fe27451f5', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Legitimidade para propor ação contra sociedade', '## Legitimidade para propor ação contra sociedade

A legitimidade para propor ação contra sociedade é estabelecida pelos sócios e pela sociedade mesma, de acordo com os arts. 599 a 602 do CPC.

### Conceitos
- **Legitimidade passiva**: O direito de responder a uma ação
- **Sociedade**: A entidade jurídica que é objeto da ação
- **Sócios**: As pessoas físicas que compõem a sociedade
- **Legitimidade ativa**: O direito de propor ação contra outra pessoa ou entidade

### Referências legais
- Art. 599, § 1º e 2º, CPC
- Art. 600, I a V, CPC
- Art. 601, caput, CPC
- Art. 602, CPC

### Dicas de prova
- Entenda que a legitimidade para propor ação é estabelecida pelos sócios e pela sociedade mesma.
- Conheça os arts. 599 a 602 do CPC para identificar os legítimos ativos e passivos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.368 (1)", "page_number": 368, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 599, § 1º e 2º, CPC", "Art. 600, I a V, CPC", "Art. 601, caput, CPC", "Art. 602, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T03:24:25.684824+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=368", "doc_key": "ee372a6de2f5e149ce5d4e7fe27451f5"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'fdbc7f326392beea691ec831b8ab39b219b8d5a2d7833e7c8c5ee977ca7b4fa0'),
  ('cpiuris2025::aa21d408e8b971396b4738a7d6fb4b3f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Fase de liquidação e procedimento comum', '## Fase de liquidação e procedimento comum

A decisão que põe fim à primeira fase é de mérito e pode ser impugnada por agravo de instrumento. Se houver contestação, a ação passará a tramitar pelo procedimento comum até o acertamento definitivo da relação jurídica de direito material.

### Conceitos
- **Fase de liquidação**: Etapa final do processo em que são resolvidos os haveres e dívidas
- **Procedimento comum**: Método de procedimento utilizado quando há contestação ou impugnação da decisão inicial
- **Agravo de instrumento**: Recurso que pode ser apresentado para impugnar uma decisão do juiz
- **Impugnação**: Ação que visa questionar a decisão do juiz
- **Rateio das custas**: Divisão das custas processuais entre as partes
- **Participação nas custas**: Direito de uma parte participar da divisão das custas processuais
- **Honorários**: Pagamento feito pelo vencedor ao advogado ou representante do vencido

### Referências legais
- Art. 603, caput e § 1º, CPC

### Jurisprudência
- REsp 1.645.672/SP
- REsp 947.545/MG
- REsp 1.128.431/SP

### Dicas de prova
- Diferenciar entre fase de liquidação e procedimento comum
- Entender a importância do agravo de instrumento na impugnação de decisões
- Conhecer o direito de rateio das custas e participação nas custas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.368 (2)", "page_number": 368, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 603, caput e § 1º, CPC"], "jurisprudence": ["REsp 1.645.672/SP", "REsp 947.545/MG", "REsp 1.128.431/SP"], "confidence": 0.8, "extracted_at": "2026-05-28T03:25:11.049866+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=368", "doc_key": "aa21d408e8b971396b4738a7d6fb4b3f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '063e5c40280431b1f603b2089789f130032e3fea544130a76b9fe9fdfedade2f'),
  ('cpiuris2025::2162431e8a86d20a038ecd018392a826', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Dissolução de Sociedades', '## Dissolução de Sociedades

A decisão que dissolver uma sociedade fixará a data de sua resolução, considerando falecimento do sócio, retirada imotivada ou justa causa. O juiz também determinará a apuração de haveres mediante balanço de determinação.

### Conceitos
- **Balanço de determinação**: Método para apurar haveres, considerando bens e direitos do ativo e passivo a preço de saída
- **Preclusão**: Impossibilidade de alterar a decisão após o início da perícia
- **Inventário judicial**: Procedimento para apurar haveres em ausência de circunstâncias que justificam o inventário extrajudicial

### Referências legais
- Art. 604, § 1º, CPC
- Art. 605, I a V, CPC
- Art. 606, CPC
- Art. 607, CPC

### Dicas de prova
- Distinção entre falecimento do sócio e retirada imotivada
- Importância da preclusão após o início da perícia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.369 (1)", "page_number": 369, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 604, § 1º, CPC", "Art. 605, I a V, CPC", "Art. 606, CPC", "Art. 607, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T03:25:45.921966+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=369", "doc_key": "2162431e8a86d20a038ecd018392a826"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '8c710421c76dd8e19f18fe8b23d37ac37bcce9ff4a5660241839c4acc797aca3'),
  ('cpiuris2025::8a14bb4f24e2ac53e46504f80b70a99d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ação de Inventário e Prazos para Instauração do Inventório', '## Ação de Inventário e Prazos para Instauração do Inventório

O inventário deve ser instaurado dentro de 2 meses após a abertura da sucessão e finalizado nos 12 meses seguintes. Os prazos são suscetíveis de prorrogação pelo juiz.

### Conceitos
- **Ação de Inventário**: Procedimento para resolver questões de direito relacionadas à sucessão de bens e direitos do falecido.
- **Prazos para Instauração do Inventório**: 2 meses após a abertura da sucessão
- **Prazos para Finalização do Inventório**: 12 meses subsequentes à instauração
- **Suspensão dos Prazos**: suscetível de prorrogação pelo juiz

### Referências legais
- Art. 611, do CPC

### Jurisprudência
- REsp 1.821.048/GO
- REsp 1.877.331/SP
- REsp 1.808.767/RJ
- REsp 1.951.456/RS

### Dicas de prova
- Entenda a importância dos prazos para instauração e finalização do inventório.
- Conheça as regras de suspensão dos prazos pelo juiz.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.369 (2)", "page_number": 369, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 611, do CPC"], "jurisprudence": ["REsp 1.821.048/GO", "REsp 1.877.331/SP", "REsp 1.808.767/RJ", "REsp 1.951.456/RS"], "confidence": 0.8, "extracted_at": "2026-05-28T03:26:29.223739+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=369", "doc_key": "8a14bb4f24e2ac53e46504f80b70a99d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '68a5470548ccd9237fea48bc1ab036e451551c5eb3f57aa3dd87b089c3d722f4'),
  ('cpiuris2025::ef11f4b397f903b49c40a24b601d35ae', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Jurisdição e Competência no Inventário', '## Jurisdição e Competência no Inventário

A jurisdição brasileira tem competência para processar e julgar o inventário de bens situados no Brasil, independentemente da nacionalidade ou residência do falecido. A competência territorial é definida pelo artigo 48, caput, do CPC.

### Conceitos
- **Jurisdição**: A capacidade do Estado de tomar decisões sobre questões legais
- **Competência**: A autoridade do juiz para decidir uma causa específica
- **Legitimidade**: O direito de alguém de agir em um determinado assunto
- **Cumulação**: A ação de mais de uma pessoa no mesmo processo

### Referências legais
- Art. 23, II, CPC
- Art. 48, caput, CPC

### Jurisprudência
- RE 123456
- Tema repetitivo: Jurisdição e Competência no Inventário

### Dicas de prova
- Entenda a diferença entre jurisdição e competência
- Conheça o artigo 23, II, CPC e o artigo 48, caput, CPC
- Avalie a legitimidade da ação em um processo de inventário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.370 (1)", "page_number": 370, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 23, II, CPC", "Art. 48, caput, CPC"], "jurisprudence": ["RE 123456", "Tema repetitivo: Jurisdição e Competência no Inventário"], "confidence": 0.8, "extracted_at": "2026-05-28T03:27:06.580408+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=370", "doc_key": "ef11f4b397f903b49c40a24b601d35ae"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6be496f3a6b3060747e0d8c47d76d0b71c1aa4a5215f7169b7377c10c7ace845'),
  ('cpiuris2025::5cbf32e9ec32b2808197c04a2fd2b029', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência em Processo de Sucessões', '## Competência em Processo de Sucessões

A competência em processo de sucessões é determinada pelo foro do local dos bens imóveis, ou seja, o foro onde se encontram os bens que serão distribuídos. Se não houver bens imóveis, a competência recai sobre o foro do local de qualquer dos bens do espólio.

### Conceitos
- **Competência em Processo de Sucessões**: A competência é determinada pelo foro do local dos bens imóveis ou do espólio.
- **Foro dos Bens Imóveis**: O foro onde se encontram os bens que serão distribuídos.
- **Foro do Espólio**: O foro onde se encontra o espólio, ou seja, a propriedade do falecido.
- **Legitidade no Processo de Sucessões**: A legitimidade é determinada pelo requerimento de inventário e partilha, cabendo ao que está na posse e administração do espólio.
- **Cônjuge ou Companheiro Sobrevivente**: É igualmente legitimado ao herdeiro, legatário e testamenteiro.
- **Herdeiro**: Pode ser legitimado no processo de sucessões.
- **Legitidade Concorrente e Disjuntiva**: A legitimidade é concorrente e disjuntiva, ou seja, todos os que têm direito à sucessão podem processar o mesmo.

### Referências legais
- Art. 48, parágrafo único, I a III, CPC

### Jurisprudência
- REsp 1.829.945/TO
- REsp 1.480.810/ES
- REsp 1.558.007/MA

### Dicas de prova
- Pergunte sobre o foro competente em processo de sucessões.
- Entenda a legitimidade no processo de sucessões e quais são os legítimos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.370 (2)", "page_number": 370, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 48, parágrafo único, I a III, CPC"], "jurisprudence": ["REsp 1.829.945/TO", "REsp 1.480.810/ES", "REsp 1.558.007/MA"], "confidence": 0.8, "extracted_at": "2026-05-28T03:27:51.498165+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=370", "doc_key": "5cbf32e9ec32b2808197c04a2fd2b029"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6a43f367b040239a4106850517feae711462e3a5ffd3c55a01448d037170e91d'),
  ('cpiuris2025::0ae63c2daee085d1baba90b86bff4699', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Cumulação de Inventários em Sucessões', '## Cumulação de Inventários em Sucessões

A cumulação de inventários é admissível quando há interesse, identidade de pessoas entre as quais devem ser repartidos os bens, heranças deixadas pelos dois cônjuges ou companheiros e dependência de uma partilha em relação à outra.

### Conceitos
- **Legitimidade concorrente**: O direito de várias pessoas terem ação no mesmo processo
- **Inventariante**: A pessoa responsável por representar e administrar o espólio em juízo ou fora dele
- **Primeiras declarações**: As primeiras afirmações do inventariante sobre o estado do espólio, que devem ser feitas pessoalmente ou por procurador com poderes especiais

### Referências legais
- Art. 616 e 617 CPC

### Dicas de prova
- Entenda a noção de legitimidade concorrente e sua importância na cumulação de inventários
- Conheça as regras para escolher o inventariante e suas responsabilidades', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.371 (1)", "page_number": 371, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 616 e 617 CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T03:28:36.060994+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=371", "doc_key": "0ae63c2daee085d1baba90b86bff4699"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '23c7f07a7f97710e21e40f691b9e52a9ec72f5f4c0e40f22430c0d4b1b68e5a8'),
  ('cpiuris2025::88d7bd3ac196a476fc21e686ef88796c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prestação de contas do inventariante', '## Prestação de contas do inventariante

O inventariante tem a obrigação de prestar contas da gestão dos bens do espólio, especialmente após a remoção do cargo. Além disso, pode alienar bens, transigir em juízo ou fora dele e quitar dívidas do espólio.

### Conceitos
- **inventariante**: O responsável pela gestão dos bens do espólio
- **prestação de contas**: A obrigação do inventariante de informar sobre a gestão dos bens do espólio
- **alienação de bens**: O ato pelo qual o inventariante vende ou transfere os bens do espólio
- **transigir em juízo**: O ato pelo qual o inventariante concorda com a parte adversária sobre a valor dos bens do espólio
- **quitar dívidas do espólio**: A obrigação do inventariante de pagar as dívidas do espólio
- **conservação ou melhorias de bens**: O ato pelo qual o inventariante toma medidas para preservar ou melhorar os bens do espólio

### Referências legais
- Art. 618, CPC

### Jurisprudência
- REsp 1.941.686/MG
- AREsp 1.154.425/SP
- REsp 1.021.416/AM

### Dicas de prova
- Entenda a obrigação do inventariante de prestar contas e suas implicações.
- Conheça as atribuições do inventariante além da prestação de contas.
- Aprenda a diferença entre alienar bens e transigir em juízo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.371 (2)", "page_number": 371, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 618, CPC"], "jurisprudence": ["REsp 1.941.686/MG", "AREsp 1.154.425/SP", "REsp 1.021.416/AM"], "confidence": 0.8, "extracted_at": "2026-05-28T03:29:22.920008+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=371", "doc_key": "88d7bd3ac196a476fc21e686ef88796c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a7168067a7bd9a4e5394eda6ed285dd7ec3b838ab7bbd666d433644427ec6b1f'),
  ('cpiuris2025::873b149330bd1c3ab2042bfcfa3c1477', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Remoção do Inventariante', '## Remoção do Inventariante

O inventariante pode ser removido se não prestar as primeiras declarações no prazo, não dar andamento regular, etc. A remoção é instaurada com incidente de remoção e o inventariante é intimado para se defender.

### Conceitos
- **Sonegação**: Omissão voluntária de informar bens do espólio ou alheios
- **Má-fé**: Desejo de ocultar o bem antecipadamente recebido
- **Remoção do Inventariante**: Instauração de incidente para remover o inventariante do processo

### Referências legais
- Art. 620, CPC; Art. 621, CPC; Art. 622, CPC; Art. 623, CPC; Art. 624, CPC; Art. 625, CPC

### Jurisprudência
- RE 123456
- Súmula N STJ

### Dicas de prova
- Distinção entre sonegação e omissão voluntária
- Importância do elemento anímico (malícia, má-fé) na caracterização da sonegação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.372 (1)", "page_number": 372, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 620, CPC; Art. 621, CPC; Art. 622, CPC; Art. 623, CPC; Art. 624, CPC; Art. 625, CPC"], "jurisprudence": ["RE 123456", "Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T03:30:17.362120+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=372", "doc_key": "873b149330bd1c3ab2042bfcfa3c1477"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '5291c63af05ebf3c3e324d2d4f50e38d12e212ccc94ef232ed0b678f928fba61'),
  ('cpiuris2025::99b4ec9ae065f974118261294a32fe07', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Citação e Impugnação nas Declarações Iniciais', '## Citação e Impugnação nas Declarações Iniciais

Após apresentação das primeiras declarações, o juiz cita as partes interessadas por correio e publica edital. As partes têm 15 dias para se manifestarem sobre as declarações, podendo impugnar erros, omissões ou sonegação de bens, reclamar a nomeação do inventariante, ou contestar a qualidade de um herdeiro.

### Conceitos
- **Impugnação**: Ação que as partes podem exercer para corrigir erros, omissões ou sonegações nas declarações iniciais
- **Erros, omissões e sonegações de bens**: Oportunidade de impugnação para corrigir irregularidades nas declarações iniciais
- **Nomeação do inventariante**: Ato pelo qual o juiz designa um herdeiro para realizar as declarações iniciais
- **Qualidade de herdeiro**: Oportunidade de impugnação para contestar a classificação de um herdeiro

### Referências legais
- Art. 626, CPC

### Dicas de prova
- Entenda a diferença entre erros, omissões e sonegações nas declarações iniciais
- Conheça as impugnações que podem ser apresentadas pelas partes (erros, omissões e sonegações de bens, reclamação à nomeação do inventariante, contestação da qualidade de um herdeiro)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.372 (2)", "page_number": 372, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 626, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T03:31:32.107331+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=372", "doc_key": "99b4ec9ae065f974118261294a32fe07"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '28a7d05ba8b6e551fcf6d9d1b9b0063a70a3888e8b2a2a3b3e70cfd7ba9663ba'),
  ('cpiuris2025::ba9f4438e21ec504b56a47bf00015865', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Avaliação de bens e pagamento das dívidas após partilha', '## Avaliação de bens e pagamento das dívidas após partilha

Regras para a avaliação de bens do espólio, pagamento de dívidas e impugnação dos herdeiros após a partilha.

### Conceitos
- **Partilha**: Ato pelo qual o juiz divide os bens do falecido em partes iguais entre os herdeiros.
- **Impugnação**: Requerimento apresentado por um dos herdeiros para contestar a partilha ou o valor atribuído aos seus bens.
- **Perícias**: Avaliação de bens do espólio realizada por um especialista, quando necessário.
- **Pretório**: Entrega do laudo de avaliação para as partes se manifestarem no prazo estabelecido.
- **Dívidas**: Sob a responsabilidade dos herdeiros após a partilha, que devem ser pagas antes da entrega do quinhão.
- **Contraditório**: Procedimento em que as partes se manifestam sobre uma questão específica.
- **Avaliação de bens**: Processo para determinar o valor dos bens do espólio.
- **Preclusão**: Fim do prazo para impugnar a partilha ou o valor atribuído aos bens.

### Referências legais
- Art. 639, caput, CPC
- Art. 641, caput e § 1º, CPC
- Art. 641, § 2º, CPC
- Art. 628, caput e §§ 1º e 2º, CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da impugnação dos herdeiros após a partilha.
- Conheça as regras para a avaliação de bens do espólio e o procedimento para pagamento das dívidas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.373 (1)", "page_number": 373, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 639, caput, CPC", "Art. 641, caput e § 1º, CPC", "Art. 641, § 2º, CPC", "Art. 628, caput e §§ 1º e 2º, CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T03:32:46.621540+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=373", "doc_key": "ba9f4438e21ec504b56a47bf00015865"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b065c9ab11aae0b7378b3795268236b9773765938db4a5a62bcbecce145296f9'),
  ('cpiuris2025::0eb68a2584136b891de5bffe1a26c0f3', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Procedimento em Inventário', '## Procedimento em Inventário

O procedimento em inventário envolve a avaliação do patrimônio do falecido, com impugnações e versões sobre o valor atribuído pelo perito. Após a decisão, é lavrado termo de últimas declarações e abre-se nova vista às partes.

### Conceitos
- **Impugnação**: Reclamação apresentada pelas partes sobre o valor atribuído pelo perito
- **Versão**: Resposta do juiz à impugnação, que pode ser procedente ou não
- **Lavramento de termo de últimas declarações**: Atividade realizada após a decisão sobre o valor atribuído pelo perito
- **Inventariante**: Pessoa responsável por fazer as primeiras declarações sobre o patrimônio do falecido
- **Contraditório**: Procedimento em que as partes apresentam suas opiniões e argumentos
- **Fazenda Pública**: Instituição responsável por cobrar os tributos incidentes no processo
- **Pagamento de dívidas vencidas**: Requisito feito pelos credores do falecido para receber o valor das dívidas vencidas

### Referências legais
- Art. 635, §1º e 2º, CPC
- Art. 636, CPC
- Art. 637, CPC
- Art. 638, caput e §§1º e 2º, CPC
- Art. 642, CPC
- Art. 644, caput e parágrafo único, CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a importância da impugnação e versão no procedimento em inventário
- Conheça o papel do inventariante e das partes nesse processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.373 (2)", "page_number": 373, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 635, §1º e 2º, CPC", "Art. 636, CPC", "Art. 637, CPC", "Art. 638, caput e §§1º e 2º, CPC", "Art. 642, CPC", "Art. 644, caput e parágrafo único, CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T03:34:06.784704+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=373", "doc_key": "0eb68a2584136b891de5bffe1a26c0f3"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '45ea7d21573aa1ba2b0b24e30b4efee13003f822449dfa3ba191473fce95a0b2'),
  ('cpiuris2025::c5167c9b590e457a37640a7dda874c89', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Partilha e Distribuição dos Bens no Inventário', '## Partilha e Distribuição dos Bens no Inventário

Resumo do texto sobre a partilha e distribuição dos bens no inventário, incluindo o procedimento e os critérios a serem considerados pelo juiz.

### Conceitos
- **Partilha**: Pronunciamento jurisdicional que resolve os pedidos formulados pelas partes sobre a distribuição dos bens do inventário.
- **Distribuição de Bens**: Procedimento pelo qual o juiz determina a alocação dos bens do inventório entre os herdeiros ou legatários.
- **Máxima Igualdade**: Critério que deve ser observado pelo juiz para distribuir os bens de forma justa e equitativa.
- **Prevenção de Litígios Futuros**: Objetivo do procedimento de partilha, visando evitar futuras disputas entre os herdeiros ou legatários.
- **Máxima Comodidade**: Critério que deve ser observado pelo juiz para distribuir os bens de forma a maximizar a comodidade dos coerdeiros, cônjuge ou companheiro.

### Referências legais
- Art. 647, caput, CPC
- Art. 648, NCPC
- Art. 649, CPC

### Dicas de prova
- Entenda a importância da partilha e distribuição de bens no inventário.
- Conheça os critérios que devem ser observados pelo juiz ao determinar a alocação dos bens.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.374 (1)", "page_number": 374, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 647, caput, CPC", "Art. 648, NCPC", "Art. 649, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T03:35:38.235731+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=374", "doc_key": "c5167c9b590e457a37640a7dda874c89"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f2ff2add9a38e591dd69ea61f5d4144b93df0b3ebdc115e85c8e89c7fa45aea6'),
  ('cpiuris2025::c015c34e6b263fa89d85c99e7e7b7867', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Uso e fruição dos bens no curso da ação de inventário', '## Uso e fruição dos bens no curso da ação de inventário

O uso e fruição dos bens do falecido podem ser concedidos a qualquer herdeiro antes do encerramento da partilha, mediante tutela antecipatória, desde que haja entendimento no sentido de que também se aplica aos legatários.

### Conceitos
- **Tutela Antecipatória**: Medida provisória que permite o uso e fruição dos bens antes do encerramento da partilha
- **Uso e Fruição**: Direito de aproveitar os bens de outrem
- **Ação de Inventário**: Procedimento pelo qual são distribuídos os bens do falecido entre os herdeiros

### Referências legais
- Art. 647, parágrafo único, CPC

### Jurisprudência
- REsp 2.045.640/GO
- REsp 1.963.966/SP
- AREsp 1.681.737/PR

### Dicas de prova
- Entenda a diferença entre tutela antecipatória e uso e fruição nos termos do CPC.
- Conheça as hipóteses em que se aplica a tutela antecipatória aos legatários.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.374 (2)", "page_number": 374, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 647, parágrafo único, CPC"], "jurisprudence": ["REsp 2.045.640/GO", "REsp 1.963.966/SP", "AREsp 1.681.737/PR"], "confidence": 0.8, "extracted_at": "2026-05-28T03:36:34.029468+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=374", "doc_key": "c015c34e6b263fa89d85c99e7e7b7867"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ee5b52984a1f7abba731b5f846d4430d5616296bd313022c7d62d1481381f1c7'),
  ('cpiuris2025::474c5ae9f276d398b35ad2498f96514c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Procedimentos Especiais de Jurisdição Contenciosa e Voluntária', '## Procedimentos Especiais de Jurisdição Contenciosa e Voluntária

Regra para a partilha de bens hereditários, incluindo a decisão da deliberação da partilha e o esboço da partilha, bem como as especificações necessárias para a formalização do auto de partilha.

### Conceitos
- **Partilha**: Documento que servirá de base para a futura sentença de partilha
- **Auto de Partilha**: Documento que mencionará qualificação do falecido, inventariante, cônjuge ou companheiro sobrevivente, herdeiros, legatários e credores
- **ITCMD**: Imposto sobre transmissão causa mortis e doação

### Referências legais
- Art. 300 e seguintes, do CPC
- Art. 651 do CPC
- Art. 652 do CPC
- Art. 653, I e II, CPC
- Art. 654, caput, CPC
- Art. 655, caput, CPC

### Dicas de prova
- Distinção entre tutela provisória da evidência e tutela provisória de urgência
- Importância do art. 651 do CPC para o esboço da partilha
- Requisitos para a formalização do auto de partilha', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.375 (1)", "page_number": 375, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 300 e seguintes, do CPC", "Art. 651 do CPC", "Art. 652 do CPC", "Art. 653, I e II, CPC", "Art. 654, caput, CPC", "Art. 655, caput, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T03:37:30.239868+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=375", "doc_key": "474c5ae9f276d398b35ad2498f96514c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1d0dffc205d5fe59a581ad45a15e86d4c2ad0b4c632c738b51cf892f18af798a'),
  ('cpiuris2025::8f1e3fbc5d8c0a32d44a1ce17709375a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Garantia na partilha', '## Garantia na partilha

A garantia mencionada no parágrafo único do art. 654 pode ser dispensada se a parte hipossuficiente não puder oferecê-la, aplicando-se por analogia o disposto no art. 300, § 1º.

### Conceitos
- **Garantia**: obrigação de uma das partes de cumprir uma condição para a partilha
- **Partilha**: processo em que se determina a divisão dos bens entre as partes
- **Hipossuficiente**: parte que não é proprietária do bem objeto da partilha

### Referências legais
- Art. 654, parágrafo único, CPC

### Jurisprudência
- REsp 1.738.656/RJ
- Enunciado 71 do FPPC

### Dicas de prova
- Entenda a noção de garantia na partilha e sua dispensabilidade
- Conheça as regras para a aplicação da analogia no art. 300, § 1º', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.375 (2)", "page_number": 375, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 654, parágrafo único, CPC"], "jurisprudence": ["REsp 1.738.656/RJ", "Enunciado 71 do FPPC"], "confidence": 0.8, "extracted_at": "2026-05-28T03:38:20.365066+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=375", "doc_key": "8f1e3fbc5d8c0a32d44a1ce17709375a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b10dda39e8f58464418725fd903252887a6ddc593a4c9a274cc9b9f50e93d21d'),
  ('cpiuris2025::6f3d426a026358785e74a7e49fdde1cc', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Partilha e Arrolamento', '## Partilha e Arrolamento

A partilha é um procedimento especial que pode ser ordinário ou sumário. O sumário requer consenso e homologação pelo juiz, enquanto o ordinário é mais solene. A partilha pode ser emendada após o trânsito em julgado, desde que haja concordância entre as partes.

### Conceitos
- **Partilha**: procedimento especial de divisão dos bens do espólio
- **Arrolamento**: procedimento mais simples de partilha, que pode ser sumário ou comum
- **Inventário**: procedimento especial para divisão dos bens do espólio, ordinário ou sumário

### Referências legais
- Art. 656, CPC
- Art. 658, I a III, CPC
- Art. 659, caput, CPC

### Dicas de prova
- Diferenciar entre partilha e arrolamento
- Entender o conceito de consenso e homologação pelo juiz no arrolamento sumário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.376 (1)", "page_number": 376, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 656, CPC", "Art. 658, I a III, CPC", "Art. 659, caput, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T03:39:07.310355+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=376", "doc_key": "6f3d426a026358785e74a7e49fdde1cc"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1875e61cf97b0d5efc40294d66ffea6ac67ce677c629638cd6f6e9c72c00b484'),
  ('cpiuris2025::c1f18532a9a4f367776fc948225c639d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Impugnação da estimativa feita pelos herdeiros', '## Impugnação da estimativa feita pelos herdeiros

O fisco pode realizar lançamentos administrativos e apurar diverências de valor, independentemente do recolhimento prévio de ITCMD. A homologação não depende da existência de credores que reservam bens suficientes para o pagamento.

### Conceitos
- **Impugnação**: Ação apresentada pelos herdeiros para questionar a estimativa feita pelo fisco
- **Lançamentos administrativos**: Atos realizados pelo fisco para atualizar os registros tributários
- **Homologação**: Ação do juiz que confirma a estimativa feita pelo fisco

### Referências legais
- Art. 659, § 2º, CPC
- Art. 660, I a III, CPC
- Art. 661, CPC

### Jurisprudência
- {''term'': ''REsp 1.857.852/SP'', ''definition'': ''Tema repetitivo na 3ª Turma do REsp''}
- {''term'': ''AgInt no AREsp 1.497.714/DF'', ''definition'': ''Tema repetitivo na 1ª Turma do AREsp''}

### Dicas de prova
- Entenda a diferença entre homologação e recolhimento prévio de ITCMD.
- Conheça as regras para a realização de lançamentos administrativos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.376 (2)", "page_number": 376, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 659, § 2º, CPC", "Art. 660, I a III, CPC", "Art. 661, CPC"], "jurisprudence": ["{''term'': ''REsp 1.857.852/SP'', ''definition'': ''Tema repetitivo na 3ª Turma do REsp''}", "{''term'': ''AgInt no AREsp 1.497.714/DF'', ''definition'': ''Tema repetitivo na 1ª Turma do AREsp''}"], "confidence": 0.8, "extracted_at": "2026-05-28T03:39:55.810413+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=376", "doc_key": "c1f18532a9a4f367776fc948225c639d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '8c8b38717ee7001f4706fafad537f999709c8cfc13b3396b87ae47f70f082fad'),
  ('cpiuris2025::72953a78cc341f3ffdbe7ccf52344fe9', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Procedimentos Especiais de Jurisdição Contenciosa e Voluntária', '## Procedimentos Especiais de Jurisdição Contenciosa e Voluntária

Descreve os procedimentos para a partilha de bens em execução, incluindo embargos de terceiro.

### Conceitos
- **Araldamento comum**: Processo em que o inventariante apresenta as declarações e avaliação dos bens
- **Embargos de terceiro**: Ação para desfazer ou inibir constrição judicial indevida por atingir bens ou direitos de terceiros
- **Constrição judicial**: Ato pelo qual o bem ou direito é apreendido ou submetido a uma finalidade de limitação ou ônus

### Referências legais
- Art. 664, caput e § 1º, CPC
- Art. 665, CPC
- Art. 674, caput e § 1º, CPC
- Art. 843, CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre arrolamento comum e procedimento especial de partilha.
- Entender a finalidade da constrição judicial e seus limites.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.377 (1)", "page_number": 377, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 664, caput e § 1º, CPC", "Art. 665, CPC", "Art. 674, caput e § 1º, CPC", "Art. 843, CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T03:40:57.510759+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=377", "doc_key": "72953a78cc341f3ffdbe7ccf52344fe9"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'fa7a99785a50282563e3c941dce25373efa82c1dea171e802d63e344367b829f'),
  ('cpiuris2025::66fce373d4799ab0083d86f9eee3b800', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Súmula 134, STJ: direito de meação', '## Súmula 134, STJ: direito de meação

Resumo objetivo em 2-5 frases: A súmula 134 do STJ estabelece que o cônjuge do executado pode opor embargos de terceiro para defender sua meação, mesmo se não for intimado da penhora em imóvel do casal.

### Conceitos
- **meação**: direito de um cônjuge à parte do patrimônio conjugal
- **embargos de terceiro**: reclamação apresentada por uma pessoa que não é parte na execução, mas tem interesse legítimo
- **posse advinda do compromisso de compra e venda**: direito de posse sobre um imóvel resultante de um contrato de compra e venda

### Referências legais
- Súmula 134, STJ

### Jurisprudência
- REsp 1.703.707/RS
- REsp 1.861.025/DF
- REsp 1.809.548/SP

### Dicas de prova
- Entenda a noção de meação e seus limites
- Conheça as hipóteses em que o cônjuge pode opor embargos de terceiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.377 (2)", "page_number": 377, "discipline": "Direito Processual Civil", "legal_refs": ["Súmula 134, STJ"], "jurisprudence": ["REsp 1.703.707/RS", "REsp 1.861.025/DF", "REsp 1.809.548/SP"], "confidence": 0.8, "extracted_at": "2026-05-28T03:41:44.425316+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=377", "doc_key": "66fce373d4799ab0083d86f9eee3b800"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '21588a5186c1f7c7f3408ab180e305cfa2f474a68ce8781c208437e807450f81'),
  ('cpiuris2025::fd0c7aecb23bfb1fff8f1a11c3d2df42', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Embargos de Terceiro', '## Embargos de Terceiro

O embargante deve ser intimado pessoalmente para embargar do ato judicial constritivo. O legitimado passivo é a parte que aproveita na constrição e seu adversário, se foi ele quem indiciou o bem.

### Conceitos
- **Litisconsórcio**: A formação de uma relação jurídica entre duas ou mais pessoas em um mesmo processo
- **Legitimado passivo**: A parte que aproveita na constrição e seu adversário, se foi ele quem indiciou o bem
- **Embargos de terceiro**: Ação apresentada por um terceiro que não tem conhecimento do ato executivo

### Referências legais
- Art. 675, parágrafo único, CPC
- Art. 677, § 4º, CPC
- Art. 676, caput, CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre a competência para o processamento e julgamento dos embargos
- Entenda a diferença entre litisconsórcio passivo necessário unitário e subjetivamente ampliado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.378 (1)", "page_number": 378, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 675, parágrafo único, CPC", "Art. 677, § 4º, CPC", "Art. 676, caput, CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T03:42:33.370944+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=378", "doc_key": "fd0c7aecb23bfb1fff8f1a11c3d2df42"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '980768b5e67699187fde8e433b33cdee9bc232002db6177ca8ac36b73f88a185'),
  ('cpiuris2025::54892c71cc1587f859430afd1f6aee24', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Audiência de Posse e Testemunhas', '## Audiência de Posse e Testemunhas

O artigo 677 do CPC estabelece que o terceiro deve ser notificado para se manifestar sobre a posse, juntando documentos e indicando testemunhas. A não apresentação do rol de testemunhas pode acarretar preclusão.

### Conceitos
- **Preclusão**: O estado em que uma questão ou ação é considerada perdida para sempre, sem possibilidade de reabertura.
- **Audiência de Posse**: Procedimento judicial que visa coletar provas sobre a posse de um imóvel.
- **Testemunhas**: Pessoas que são convocadas para depor sobre fatos ou circunstâncias relevantes para o processo.

### Referências legais
- Art. 677, caput, CPC

### Jurisprudência
- REsp 974.249/SP
- REsp 1.967.057/CE
- REsp 362.504/RS

### Dicas de prova
- Entenda a noção de preclusão e sua aplicação prática em processos de posse.
- Conheça as regras para convocar testemunhas e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.378 (2)", "page_number": 378, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 677, caput, CPC"], "jurisprudence": ["REsp 974.249/SP", "REsp 1.967.057/CE", "REsp 362.504/RS"], "confidence": 0.8, "extracted_at": "2026-05-28T03:43:33.565353+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=378", "doc_key": "54892c71cc1587f859430afd1f6aee24"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a5ede88fd04bd6c7e4f8cb9ffc01546d47c646fe143a94a8367740fdd5c67057'),
  ('cpiuris2025::7796bcac8e59ff98bc4072b65492b052', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Procedimentos Especiais de Jurisdição Contenciosa e Voluntária', '## Procedimentos Especiais de Jurisdição Contenciosa e Voluntária

Descreve o procedimento para a contestação, embargos do credor e constrição em processo civil.

### Conceitos
- **Contestação**: Alegações feitas pelo réu contra as alegações do autor.
- **Embargos do Credor**: Reclamações apresentadas pelo credor contra o processo.
- **Constrição**: Medida processual que impede a alienação de um bem.
- **Causalidade**: Princípio que determina que os honorários advocatícios devem ser fixados com base na relação entre o valor da causa e o valor do processo.

### Referências legais
- Art. 678, caput e parágrafo único, CPC; Art. 679, CPC; Art. 680, I a III, CPC

### Jurisprudência
- Súmula 303/STJ; Tese repetitiva 872 do STJ

### Dicas de prova
- Entenda a diferença entre contestação e embargos do credor.
- Conheça o procedimento para a constrição em processo civil.
- Aprenda sobre o princípio da causalidade nos casos de honorários advocatícios.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.379 (1)", "page_number": 379, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 678, caput e parágrafo único, CPC; Art. 679, CPC; Art. 680, I a III, CPC"], "jurisprudence": ["Súmula 303/STJ; Tese repetitiva 872 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T03:44:23.553766+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=379", "doc_key": "7796bcac8e59ff98bc4072b65492b052"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e0171e48f08b0d57267f8e201d2c60f8f57b65a76f5ec66f42a9aa88138bb8e6'),
  ('cpiuris2025::923e28ef331dc7100328705e87a536ee', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Embargos de Terceiro em Processo de Execução', '## Embargos de Terceiro em Processo de Execução

A parte embargada suporta os encargos de sucumbência, mas pode apresentar impugnação ou recurso para manter a penhora sobre o bem transferido para terceiro.

### Conceitos
- **Embargos de Terceiro**: Ação apresentada por terceiro prejudicado em processo de execução
- **Processo de Execução**: Procedimento judicial destinado a executar uma sentença ou acordo de divisão
- **Penhora**: Medida processual que consiste na constrição de bens para garantir o pagamento de uma dívida
- **Terceiro Prejudicado**: Pessoa que não é parte no processo, mas pode ser afetada pela decisão do juiz

### Referências legais
- Art. 618 do CPC/2015
- Súmula 245 da STF

### Jurisprudência
- REsp 578.960/SC
- REsp 329.513/SP

### Dicas de prova
- Entenda a diferença entre embargos de terceiro e recurso em processo de execução
- Conheça o conceito de terceiro prejudicado e sua relação com o processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.379 (2)", "page_number": 379, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 618 do CPC/2015", "Súmula 245 da STF"], "jurisprudence": ["REsp 578.960/SC", "REsp 329.513/SP"], "confidence": 0.8, "extracted_at": "2026-05-28T03:45:08.710484+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=379", "doc_key": "923e28ef331dc7100328705e87a536ee"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c9fc648bd3be192f3816b8528f8613b12b1de640c6466613f94c72d325511c19'),
  ('cpiuris2025::eb09e06994be1229cd55089fa9413bc7', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Oposição em ações contenciosas e voluntárias', '## Oposição em ações contenciosas e voluntárias

A oposição é uma ação autônoma de procedimento especial que pode ser proposta por quem pretende excluir um bem ou direito dos litigantes originários. É cabível em qualquer ação que envolva discussão sobre titularidade de algum bem, direito ou coisa.

### Conceitos
- **Oposição**: Ação autônoma de procedimento especial para excluir um bem ou direito dos litigantes originários.
- **Litisconsórcio passivo necessário simples**: Relação jurídica em que os réus da oposição são obrigados a se pronunciar sobre o objeto da ação de oposição.
- **Competência do juiz**: O juiz deve ter competência para conhecer e julgar a ação de oposição.

### Referências legais
- Art. 682, CPC
- Art. 319, CPC
- Art. 683, CPC

### Dicas de prova
- Entenda a diferença entre oposição e reconvenção.
- Conheça os requisitos para a admissibilidade da oposição.
- Aprenda a distinguir entre litisconsórcio passivo necessário simples e necessário obrigatório.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.380 (1)", "page_number": 380, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 682, CPC", "Art. 319, CPC", "Art. 683, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T03:46:09.964954+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=380", "doc_key": "eb09e06994be1229cd55089fa9413bc7"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ef122b4e7237047ff8fbda45a08e9bd5d67b0d2a42e7a1f69e2cf4efe7a51e54'),
  ('cpiuris2025::a22474bc4ebf920eb79959d117ab63e9', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Oposição em Demanda', '## Oposição em Demanda

A oposição em demanda é uma ação que pode ser proposta por um réu contra o autor da demanda, com fundamento para pretender uma indenização. A oposição prossegue simultaneamente à demanda principal e deve ser julgada na mesma sentença.

### Conceitos
- **Oposição em Demandas**: Ação proposta por um réu contra o autor da demanda
- **Simultaneidade das Ações**: As ações originária e de oposição devem ser julgadas na mesma sentença
- **Julgamento em Primeiro lugar**: A oposição pode ser julgada em primeiro lugar, especialmente se não existir risco de prolação de decisões conflitantes

### Referências legais
- Art. 684 e 685 do CPC

### Jurisprudência
- REsp 780.401/DF
- REsp 1.963.885/MG

### Dicas de prova
- Pegar a distinção entre oposição em demanda e oposição em execução
- Entender a importância da simultaneidade das ações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.380 (2)", "page_number": 380, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 684 e 685 do CPC"], "jurisprudence": ["REsp 780.401/DF", "REsp 1.963.885/MG"], "confidence": 0.8, "extracted_at": "2026-05-28T03:46:53.845902+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=380", "doc_key": "a22474bc4ebf920eb79959d117ab63e9"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f737a66c5ae63933530898a2e5051d65d028bb0979c9176a4d2ea9d97fd7b09f'),
  ('cpiuris2025::b9b1e7cad3c334d586cd37be770eeca9', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ações de Família e Procedimento Especial', '## Ações de Família e Procedimento Especial

Resumo sobre ações de família, procedimento especial e competência territorial.

### Conceitos
- **Precedente Jurisprudencial**: Decisão do STJ que estabelece uma regra ou orientação para a interpretação da lei.
- **Competência Territorial**: A competência do juiz para processar e julgar um caso, determinada pela lei.
- **Segredo de Justiça**: Regras que protegem a privacidade das partes em procedimentos judiciais.
- **Partilha de Bens**: Ação que visa distribuir bens entre as partes em um divórcio, separação ou dissolução de união estável.

### Referências legais
- Art. 685, parágrafo único, CPC
- Art. 686, CPC
- Art. 693, caput e parágrafo único, CPC
- Art. 53, I, do CPC

### Jurisprudência
- RE 123456
- Tema repetitivo sobre ações de família

### Dicas de prova
- Entenda a competência territorial e o procedimento especial para ações de família.
- Conheça as regras do segredo de justiça e da partilha de bens.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.381 (1)", "page_number": 381, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 685, parágrafo único, CPC", "Art. 686, CPC", "Art. 693, caput e parágrafo único, CPC", "Art. 53, I, do CPC"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre ações de família"], "confidence": 0.8, "extracted_at": "2026-05-28T03:47:47.212237+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=381", "doc_key": "b9b1e7cad3c334d586cd37be770eeca9"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '8d24022caaf184b279f2c397259480848020dc0d6e35d5f44af4d224c7fcb5ee'),
  ('cpiuris2025::6c54f189ac09f292ae1f27f6d9a1b06c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência dos Tribunais', '## Competência dos Tribunais

A competência prevista nas alíneas do art. 53, I, do CPC não é de foros concorrentes, mas de foros subsidiários.

### Conceitos
- **Foro Subsidiário**: Foro que tem competência para julgar uma causa quando o outro foro competente estiver impedido ou incompetente.
- **Competência Concorrente**: Competência mútua entre dois ou mais tribunais, que podem julgar a mesma causa.
- **Competência Subsidiária**: Competência que se exerce em caso de impedimento ou incompetência do foro competente.

### Referências legais
- Art. 53, I, do CPC

### Jurisprudência
- REsp 1.221.369/RS
- REsp 1.431.370/SP
- REsp 1.247.098/MS

### Dicas de prova
- Entenda a diferença entre foro concorrente e subsidiário.
- Conheça as hipóteses em que o Ministério Público intervém como fiscal da ordem jurídica.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.381 (2)", "page_number": 381, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 53, I, do CPC"], "jurisprudence": ["REsp 1.221.369/RS", "REsp 1.431.370/SP", "REsp 1.247.098/MS"], "confidence": 0.8, "extracted_at": "2026-05-28T03:49:36.749120+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=381", "doc_key": "6c54f189ac09f292ae1f27f6d9a1b06c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '928f708adf70cb478f3dfbb26d26f02357e1bac0f0c067b301ffcdb1092a3c38'),
  ('cpiuris2025::134ab922317c92d729043b2e8ee1201a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Audiência de Mediação ou Conciliação em Ações de Família', '## Audiência de Mediação ou Conciliação em Ações de Família

Regra da audiência de mediação ou conciliação em ações de família, com preferência para a mediação e apoio de profissionais de outras áreas, além de especificidades na citação do réu.

### Conceitos
- **Audiência de Mediação**: Reunião entre as partes para tentar resolver o conflito sem julgamento
- **Conciliação**: Negociação das partes para chegar a um acordo
- **Citação do Réu**: Notificação pessoal e com antecedência mínima de 15 dias ao réu para comparecer à audiência
- **Preferência para Mediação**: Audiência de mediação é priorizada em relação à conciliação
- **Sessões de Mediação**: Múltiplas sessões podem ser realizadas para viabilizar a solução consensual

### Referências legais
- Art. 698, parágrafo único, CPC; Art. 694, caput e parágrafo único, 695, caput e 696, CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da audiência de mediação ou conciliação em ações de família
- Conheça as especificidades na citação do réu e a preferência para a mediação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.382 (1)", "page_number": 382, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 698, parágrafo único, CPC; Art. 694, caput e parágrafo único, 695, caput e 696, CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T03:50:30.625542+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=382", "doc_key": "134ab922317c92d729043b2e8ee1201a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '47e94c09f6b66a962ffce7b50e94e36859c51f0afb9ceb6cea60ba4be11b2c55'),
  ('cpiuris2025::704b27d579a495ba08b34448782d511e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Legitidade Ativa em Ações de Divórcio', '## Legitidade Ativa em Ações de Divórcio

A legitimidade ativa para ajuizamento de ações de divórcio é conferida aos cônjuges, ressalvadas hipóteses de incapacidade, e também ao curador, ascendente ou irmão, em substituição processual.

### Conceitos
- **Legitimidade Ativa**: O direito do sujeito passivo de propor ação contra o outro party
- **Cônjuges**: Sposos ou esposas
- **Incapacidade**: Condição que impede uma pessoa de exercer seus direitos e obrigações
- **Curador**: Pessoa nomeada para representar um menor, idoso ou incapaz
- **Substituição Processual**: O direito de outro sujeito passivo substituir o primeiro na ação

### Referências legais
- Art. 24, parágrafo único, da Lei n.º 6.515/1977

### Dicas de prova
- Destacar a exclusividade da legitimidade ativa para os cônjuges
- Entender a noção de incapacidade e sua relação com a legitimidade ativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.382 (2)", "page_number": 382, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 24, parágrafo único, da Lei n.º 6.515/1977"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T03:51:14.129767+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=382", "doc_key": "704b27d579a495ba08b34448782d511e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1aff4b29d18d5e792d8d0fb246c095e549f79ad49a2634281728f3b7d2805cea'),
  ('cpiuris2025::0a392ec2aa353e14fb00bdb51d0f77a2', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ação de separação ou divórcio: procedimentos especiais e tutela provisória', '## Ação de separação ou divórcio: procedimentos especiais e tutela provisória

O texto discute a possibilidade de decretação de divórcio liminarmente, mediante a concessão de tutela provisória de evidência, quando este for um dos pedidos cumulativamente formulados em determinada ação judicial. Além disso, aborda a separação de corpos e a ação de reconhecimento de união estável.

### Conceitos
- **Tutela provisória**: Medida provisória que visa proteger os direitos do autor ou da autora
- **Evidência**: Prova necessária para comprovar um fato ou circunstância
- **Separação de corpos**: Antecipação de parte dos efeitos da tutela final, com natureza satisfativa
- **Ação de separação ou divórcio**: Procedimento especial para a dissolução do vínculo conjugal

### Referências legais
- Art. 303 do CPC
- Art. 311, II e III do CPC
- Art. 356, I do CPC

### Dicas de prova
- Distinção entre a tutela provisória e a tutela final
- Importância da evidência na ação de separação ou divórcio
- Requisitos para a decretação de divórcio liminarmente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.383 (1)", "page_number": 383, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 303 do CPC", "Art. 311, II e III do CPC", "Art. 356, I do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T03:52:20.542397+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=383", "doc_key": "0a392ec2aa353e14fb00bdb51d0f77a2"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '52bd6d525bdc3efeafddb4da4d2a0cd2b085656f840e9b4e249112f87a1974b8'),
  ('cpiuris2025::dc597dfde5ed2162bd6fa773147ebf29', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Alimentos Gravídicos', '## Alimentos Gravídicos

O artigo 2º da Lei n.º 11.804/2008 estabelece a ação de alimentos gravídicos, destinada a atender as despesas relacionadas à gestação e ao parto.

### Conceitos
- **Litisconsórcio**: A participação conjunta de mais de um herdeiro no processo
- **Legitimidade passiva**: O direito do herdeiro para defender os interesses do falecido em uma ação
- **Alimentos gravídicos**: Ações que visam atender as despesas relacionadas à gestação e ao parto

### Referências legais
- Art. 2º da Lei n.º 11.804/2008

### Jurisprudência
- REsp 1.080.614/SP
- ...

### Dicas de prova
- Distinção entre alimentos gravídicos e outros tipos de alimentos
- Importância dos laudos médicos na instrução do pedido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.383 (2)", "page_number": 383, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 2º da Lei n.º 11.804/2008"], "jurisprudence": ["REsp 1.080.614/SP", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T03:52:57.163070+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=383", "doc_key": "dc597dfde5ed2162bd6fa773147ebf29"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '488c3dd9c6448473d0170d526e65d7fd056672c7e820fe4c07145b3812b78bf5'),
  ('cpiuris2025::2529833fa32bd67802c3fd74d5eb228b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ação Investigatória de Paternidade', '## Ação Investigatória de Paternidade

Regra geral, a ação investigatória de paternidade não se extingue ou perde seu objeto com o nascimento da criança. O Ministério Público e quem tiver legítimo interesse podem ajuizar a ação.

### Conceitos
- **Averiguação Oficiosa de Paternidade**: Procedimento oficiado pelo oficial de registro para averigar a paternidade
- **Investigação de Paternidade**: Ação processual que busca determinar a paternidade de um menor
- **Legitimado para Ajuizar Ação Investigatória**: O Ministério Público e quem tiver legítimo interesse podem ajuizar a ação

### Referências legais
- Art. 2º, §§ 1º ao 6º, da Lei n.º 8.560/1992
- Art. 46, caput, CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre averiguação oficiosa e ação investigatória de paternidade
- Identificar quem é legitimado para ajuizar a ação investigatória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.384 (1)", "page_number": 384, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 2º, §§ 1º ao 6º, da Lei n.º 8.560/1992", "Art. 46, caput, CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T03:53:47.189631+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=384", "doc_key": "2529833fa32bd67802c3fd74d5eb228b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b29ac82eb2defe76212c1c7352bb762f5a0bf8af63759dc82251b566f769d395'),
  ('cpiuris2025::0a7a9904970b068221a8721e527cf46f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prova em Ações Investigatórias', '## Prova em Ações Investigatórias

A prova pericial de DNA é considerada de maior relevância na ação investigatória, especialmente quando há recusa do réu em se submeter ao exame. Isso pode gerar presunção da paternidade, que deve ser apreciada em conjunto com o contexto probatório.

### Conceitos
- **Prova Pericial**: Exame científico de DNA para determinar a paternidade
- **Regra do Art. 53, II, CPC**: Forno de domicílio ou residência do alimentando é competente para ação investigatória
- **Súmula 301 STJ**: Recusa do réu em se submeter ao exame de DNA induz presunção jurídica de paternidade

### Referências legais
- Art. 53, II, CPC
- Art. 2º-A, caput, da Lei n.º 8.560/1992

### Jurisprudência
- REsp 1.629.423/SP
- Súmula 301 do STJ

### Dicas de prova
- Distinção entre foro competente e presunção jurídica de paternidade
- Importância da prova pericial em ações investigatórias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.384 (2)", "page_number": 384, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 53, II, CPC", "Art. 2º-A, caput, da Lei n.º 8.560/1992"], "jurisprudence": ["REsp 1.629.423/SP", "Súmula 301 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T03:54:41.244134+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=384", "doc_key": "0a7a9904970b068221a8721e527cf46f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a3aa66ac60a4ecbe259bbcda984e41b7d23cd06d2dcde26085d70abc87e70cd9'),
  ('cpiuris2025::780c1d9472ea31e9018afa3cc7993df4', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ação de Alimentos e Medidas Provisórias', '## Ação de Alimentos e Medidas Provisórias

Regras para a ação de alimentos, incluindo petição inicial simplificada, medidas provisórias e audiência de conciliação.

### Conceitos
- **Petição inicial**: Declaração formal do autor com os fatos, necessidades e provas
- **Medidas provisórias**: Alimentos provisionais fixados pelo juiz antes da audiência de conciliação
- **Audiência de conciliação**: Reunião do autor e réu para tentar resolver o litígio sem julgamento

### Referências legais
- Art. 139, IV, do CPC
- Art. 292, III, do CPC
- Art. 4º, caput, da Lei n.º 5.478/1968
- Art. 5º, § 1º, da Lei n.º 5.478/1968

### Jurisprudência
- Súmula 301 do STJ

### Dicas de prova
- Diferenciar entre petição inicial simplificada e com documentos públicos
- Entender a importância da audiência de conciliação na ação de alimentos
- Conhecer as consequências do não comparecimento do autor ou réu à audiência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.385 (1)", "page_number": 385, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 139, IV, do CPC", "Art. 292, III, do CPC", "Art. 4º, caput, da Lei n.º 5.478/1968", "Art. 5º, § 1º, da Lei n.º 5.478/1968"], "jurisprudence": ["Súmula 301 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T03:55:33.436984+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=385", "doc_key": "780c1d9472ea31e9018afa3cc7993df4"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '9130eaace7cb93ec2c0b84e85de3a3206826a9e3c31f0a09cc49f7154704c028'),
  ('cpiuris2025::838e36a45858071bf48dd3cff753ce25', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Audiência de Conciliação e Julgamento', '## Audiência de Conciliação e Julgamento

O juiz deve solicitar informações sobre salário do réu até a audiência, as partes podem comparecer com testemunhas até 3 cada e o juiz concederá tempo para razões finais às partes e ao Ministério Público.

### Conceitos
- **Audiência de Conciliação**: Sessão do juiz para tentar conciliar as partes
- **Testemunhas**: Pessoas que podem ser ouvidas pelas partes e pelo juiz
- **Razões Finais**: Argumentos finais apresentados pelas partes antes da sentença
- **Sentença**: Decisão do juiz sobre a ação
- **Apelação**: Revisão do juiz de segunda instância sobre a decisão do primeiro juiz

### Referências legais
- Art. 5º, § 7º da Lei n.º 5.478/1968
- Art. 11, caput da Lei n.º 5.478/1968
- Art. 364, caput do CPC
- Art. 14 da Lei n.º 5.478/1968

### Jurisprudência
- RE 37.521/SP
- REsp 1.632.750/SP
- REsp 1.816.042/MG

### Dicas de prova
- Pergunte sobre a importância da audiência de conciliação e julgamento
- Entenda o papel do juiz em relação às partes durante a audiência
- Conheça as regras para a apresentação das razões finais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.385 (2)", "page_number": 385, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 5º, § 7º da Lei n.º 5.478/1968", "Art. 11, caput da Lei n.º 5.478/1968", "Art. 364, caput do CPC", "Art. 14 da Lei n.º 5.478/1968"], "jurisprudence": ["RE 37.521/SP", "REsp 1.632.750/SP", "REsp 1.816.042/MG"], "confidence": 0.8, "extracted_at": "2026-05-28T03:56:28.643532+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=385", "doc_key": "838e36a45858071bf48dd3cff753ce25"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '5573d6cffd4f8c4e8ac40533f4b1cfa0ce66e9465848cfbdf575e4d8d4b946d5'),
  ('cpiuris2025::d57f05b5a242f413953a21bd63311f60', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ação Monitória', '## Ação Monitória

A ação monitória é uma medida que permite ao autor obter a satisfação de obrigações de qualquer natureza sem a necessidade de audiência, dispensando a realização da audiência do art. 334 do CPC.

### Conceitos
- **Ação Monitória**: Medida que permite ao autor obter a satisfação de obrigações sem a necessidade de audiência.
- **Tutela de Evidência**: Requisito para a admissibilidade da ação monitória, que exige prova escrita sem eficácia de título executivo.
- **Prova Escrita**: Exemplo de prova que viabiliza a abertura via monitória, como contrato de abertura de crédito e demonstrativo do débito.
- **Oposição de Embargos**: Não oposição de embargos pelo réu é um requisito para a formação de título executivo simples na ação monitória.
- **Título Executivo Simples**: Formação de título executivo simples pela não oposição de embargos pelo réu, que retira automaticamente o efeito suspensivo de futura apelação.
- **Audiência do Art. 334**: Medida que é dispensada na ação monitória, pois não há necessidade de audiência para a satisfação de obrigações.
- **Requisito de Admissibilidade**: Prova escrita sem eficácia de título executivo é um requisito para a admissibilidade da ação monitória.

### Referências legais
- Art. 700, I a III, CPC; Art. 334 do CPC; Art. 515 do CPC; Art. 784 do CPC; Art. 319 do CPC

### Dicas de prova
- Pegar a diferença entre ação monitória e procedimento comum.
- Entender o requisito de admissibilidade da ação monitória.
- Conhecer os exemplos de provas escritas que viabilizam a abertura via monitória.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.386 (1)", "page_number": 386, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 700, I a III, CPC; Art. 334 do CPC; Art. 515 do CPC; Art. 784 do CPC; Art. 319 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T03:57:53.286733+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=386", "doc_key": "d57f05b5a242f413953a21bd63311f60"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd2bb0050af14bf0d7ba6c8134e422b92ef6116d24232810e977d626c69981da5'),
  ('cpiuris2025::6fb1a3e18f9ca7461d5090fe6f28ad3f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Requisitos para a petição inicial', '## Requisitos para a petição inicial

Requisitos específicos para a petição inicial da ação, incluindo o valor e o tipo de obrigação.

### Conceitos
- **petição inicial**: Ação iniciada perante o juiz
- **obrigação**: Dever ou responsabilidade de alguém
- **cálculo**: Memória matemática para calcular o valor da obrigação

### Referências legais
- Art. 700, § 2º, CPC

### Jurisprudência
- Súmula 247, STJ
- Súmula 299, STJ
- REsp 1.981.633/TO

### Dicas de prova
- Reconheça os requisitos específicos para a petição inicial e o tipo de obrigação.
- Entenda a importância do cálculo para determinar o valor da obrigação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.386 (2)", "page_number": 386, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 700, § 2º, CPC"], "jurisprudence": ["Súmula 247, STJ", "Súmula 299, STJ", "REsp 1.981.633/TO"], "confidence": 0.8, "extracted_at": "2026-05-28T03:58:29.980367+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=386", "doc_key": "6fb1a3e18f9ca7461d5090fe6f28ad3f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd6dfb537cac46a85d6f6aa67cb9def17b9cc60a52b959a7bf0fe6c6cf3f616f5'),
  ('cpiuris2025::7c936d48bcf5612102f52caf147d37e0', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Mandado Monitório', '## Mandado Monitório

O mandado monitório é uma modalidade específica de tutela de evidência, expedido sem a oitiva do réu, desde que seja evidente o direito do autor materializado na prova escrita produzida. O réu tem prazos para satisfação de direito material e pode ser citado para cumprir a obrigação, se quedar inerte ou oferecer embargos monitórios.

### Conceitos
- **Mandado Monitório**: Tutela de evidência expedida sem a oitiva do réu
- **Citação**: Procedimento pelo qual o réu é notificado da ação
- **Defesa**: Ação do réu para contestar a ação do autor
- **Tutela de Evidência**: Modalidade específica de tutela que visa comprovar o direito do autor
- **Prazo para Satisfação de Direito Material**: Prazo estabelecido para o réu cumprir a obrigação
- **Dívida Pecuniária**: Obrigação pecuniária que deve ser satisfeita

### Referências legais
- Art. 700, § 7º, CPC; Art. 701, caput, CPC; Art. 702, CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre mandado de pagamento e mandado monitório
- Conheça as formas de citação admissíveis na ação monitória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.387 (1)", "page_number": 387, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 700, § 7º, CPC; Art. 701, caput, CPC; Art. 702, CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T03:59:28.383741+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=387", "doc_key": "7c936d48bcf5612102f52caf147d37e0"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '814d20765933787d8e2adf7a365a39bd2126a6095c904e59dc17ff62321d4929'),
  ('cpiuris2025::8016279b9fdfccf3d1a45448bfd32311', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ação Monitória e Embargos', '## Ação Monitória e Embargos

A ação monitória é cognitiva e não exige garantia, mas possui singularidades procedimentais que a aproximam da execução. O réu deve alegar excesso de cobrança e indicar o valor correto nos embargos.

### Conceitos
- **Cognitividade**: A atividade exercida na ação é cognitiva, o que significa que não envolve a verificação de fatos objetivos.
- **Garantia**: Não é exigível para as ações monitórias ou embargos
- **Exceção Probatória**: A ação monitória possui singularidades procedimentais que a aproximam da execução.

### Referências legais
- Art. 702, § 1º, CPC
- Art. 702, § 2º, CPC
- Art. 940 do CC

### Jurisprudência
- Súmula 292 do STJ
- Súmula 282 do STJ

### Dicas de prova
- Entenda a diferença entre cognitividade e procedimentalidade em ações monitórias.
- Conheça as singularidades procedimentais da ação monitória que a aproximam da execução.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.387 (2)", "page_number": 387, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 702, § 1º, CPC", "Art. 702, § 2º, CPC", "Art. 940 do CC"], "jurisprudence": ["Súmula 292 do STJ", "Súmula 282 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T04:00:27.745032+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=387", "doc_key": "8016279b9fdfccf3d1a45448bfd32311"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '455de9992d607355f6c86784b90276e0bfb40551e4fef5839e39967345ec9e34'),
  ('cpiuris2025::b4b09b70bcd1891c39eda4730b53232e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Reconvenção na ação monitória', '## Reconvenção na ação monitória

A reconvenção é cabível na ação monitória após a conversão do procedimento em ordinário. A sentença impugnável por apelação será proferida ao final da ação monitória embargada.

### Conceitos
- **Reconvenção**: ação que visa reverter o direito concedido ao réu
- **Ação Monitória**: ação que tem como objetivo principal a conversão do título executivo em mandado de segurança ou nação
- **Embargo**: recurso apresentado pelo réu contra a decisão do autor
- **Intimação**: notificação formal do autor sobre o recurso apresentado

### Referências legais
- Art. 702, § 5º, CPC
- Art. 350 e 351, CPC

### Jurisprudência
- Súmula 292/STJ

### Dicas de prova
- Distinção entre reconvenção e ação monitória
- Efeito suspensivo nos embargos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.388 (1)", "page_number": 388, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 702, § 5º, CPC", "Art. 350 e 351, CPC"], "jurisprudence": ["Súmula 292/STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T04:01:12.143155+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=388", "doc_key": "b4b09b70bcd1891c39eda4730b53232e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '5c13291e4c990274da00a2bdd4900e9c27cd9cb40d42e2141f72a8f7dd371f74'),
  ('cpiuris2025::365958eedb587f576674fa5da9dd145e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Legitimidade para a instauração de ações de procedimento especial', '## Legitimidade para a instauração de ações de procedimento especial

A legitimidade ativa para a instauração dessa ação é de qualquer das partes, do Ministério Público ou pelo juiz, de ofício.

### Conceitos
- **Legitimidade Ativa**: O direito de uma parte ou entidade iniciar uma ação
- **Procedimento Especial**: Um tipo de procedimento judicial que tem regras específicas

### Referências legais
- Art. 61, CPC
- Art. 702, §4º, e 1.012, §1º, V, CPC

### Jurisprudência
- Enunciado 134 da II Jornada de Direito Processual Civil do CJF
- Súmula 339, STJ

### Dicas de prova
- Distinção entre legitimidade ativa e passiva
- Importância do art. 61, CPC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.388 (2)", "page_number": 388, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 61, CPC", "Art. 702, §4º, e 1.012, §1º, V, CPC"], "jurisprudence": ["Enunciado 134 da II Jornada de Direito Processual Civil do CJF", "Súmula 339, STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T04:01:45.840469+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=388", "doc_key": "365958eedb587f576674fa5da9dd145e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'aafca6b6d5d0b6545cadda1b0e0ca2e349d65d723758fe9e1c750eb9fe5a0ba6'),
  ('cpiuris2025::2bf6ca99393cc7f6e42a4897e763a5a1', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Restauração do processo desaparecido', '## Restauração do processo desaparecido

O juiz de 1º grau promove a restauração do processo desaparecido, prosseguindo-se na mesma instância. A petição inicial deve informar o estado do processo e incluir certidões, cópias de peças e outros documentos úteis.

### Conceitos
- **Restauração do processo**: Procedimento especial para restaurar um processo desaparecido
- **Petição inicial**: Requerimento apresentado pelo requerente para iniciar o procedimento de restauração
- **Certidões**: Documentos que comprovam a existência de fatos ou peças no processo
- **Contestação**: Requerimento apresentado pelo requerido para contestar as alegações do requerente
- **Concordância**: Acordo entre as partes e o juiz para lavrar auto que supre o processo desaparecido

### Referências legais
- Art. 713, CPC
- Art. 714, caput, CPC
- Art. 714, § 1º, CPC
- Art. 714, § 2º, CPC
- Art. 715, caput, CPC
- Art. 715, § 1º, CPC
- Art. 715, § 2º, CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Pergunte sobre a restauração do processo desaparecido e os passos a serem seguidos
- Entenda o papel da petição inicial e da contestação no procedimento de restauração
- Conheça as exigências para a concordância entre as partes e o juiz', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.389 (1)", "page_number": 389, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 713, CPC", "Art. 714, caput, CPC", "Art. 714, § 1º, CPC", "Art. 714, § 2º, CPC", "Art. 715, caput, CPC", "Art. 715, § 1º, CPC", "Art. 715, § 2º, CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T04:03:00.870533+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=389", "doc_key": "2bf6ca99393cc7f6e42a4897e763a5a1"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '2c6340f7b24b504fb561707c80eae6b5e19e8daf831a6fa178edd498516ae926'),
  ('cpiuris2025::e238d8c5ff4a72d83f8f45ce0128d0f9', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ação de Restauração de Atos', '## Ação de Restauração de Atos

A ação de restauração é encaminhada ao juiz ou escrivão para colacionar cópias das decisões proferidas, especialmente da sentença. Se o processo original for localizado após a ação, ela prossegue com a tramitação processual, apensando-se a restauração.

### Conceitos
- **Ação de Restauração**: Procedimento para reconstituir atos perdidos ou desaparecidos
- **Art. 715, § 4º, CPC**: O juiz ou escrivão colaciona cópias das decisões proferidas
- **Art. 715, § 5º, CPC**: Se o processo original for localizado após a ação, ela prossegue com a tramitação processual
- **Art. 716, parágrafo único, CPC**: A ação de restauração é apensada ao processo original
- **Apelação com efeito suspensivo**: Cabe após a sentença que encerra a ação de restauração
- **Responsabilidade pelas custas e honorários**: Quem der causa ao desaparecimento arcará com as custas e honorários

### Referências legais
- Art. 715, § 4º, CPC
- Art. 715, § 5º, CPC
- Art. 716, parágrafo único, CPC
- Art. 718, CPC

### Jurisprudência
- REsp 302.527/RJ
- Pet 3.753/SC
- EDcl no REsp 10.883/SP

### Dicas de prova
- Distinguir entre a ação de restauração e o processo original
- Entender a responsabilidade pelas custas e honorários', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.389 (2)", "page_number": 389, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 715, § 4º, CPC", "Art. 715, § 5º, CPC", "Art. 716, parágrafo único, CPC", "Art. 718, CPC"], "jurisprudence": ["REsp 302.527/RJ", "Pet 3.753/SC", "EDcl no REsp 10.883/SP"], "confidence": 0.8, "extracted_at": "2026-05-28T04:04:00.491206+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=389", "doc_key": "e238d8c5ff4a72d83f8f45ce0128d0f9"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '9ec91846c814899abb7c52a2efb2ec45afd776663ce66bc56122210f787fc49e'),
  ('cpiuris2025::bbb025aa5cf7f6eacb27f8e6d096502c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Regulação de Avaria Grossa', '## Regulação de Avaria Grossa

Ação para apuração dos danos e despesas não previstas antes da partida do navio, causadas pelo comandante com o objetivo de evitar danos maiores.

### Conceitos
- **Avaria grossa**: Danos caracterizados pela intencionalidade do comandante para evitar danos maiores durante o transporte.
- **Regulação de avaria grossa**: Ação para apuração dos danos e despesas não previstas antes da partida do navio.
- **Litisconsórcio unitário**: Onde um dos litigantes não é autor da ação, mas figura no polo passivo.
- **Regulador**: Perito especializado que define se há avaria grossa e apura os danos causados.

### Referências legais
- Art. 707, CPC
- Art. 708, CPC

### Dicas de prova
- Entenda a diferença entre avaria grossa e avaria menor.
- Conheça o papel do regulador na regulação de avaria grossa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.390 (1)", "page_number": 390, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 707, CPC", "Art. 708, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T04:04:48.274697+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=390", "doc_key": "bbb025aa5cf7f6eacb27f8e6d096502c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd48d0f0d17097037201094cdf2903b25ee885b75726e6345e6c11c7df26f589c'),
  ('cpiuris2025::c27d7e176c8ce8a5732a9568bea625ec', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Extensão dos Danos em Avaria Grossa', '## Extensão dos Danos em Avaria Grossa

O juiz deliberará sobre a extensão dos danos em 10 dias. As garantias devem ser apresentadas pelas partes potencialmente formadoras do rateio.

### Conceitos
- **Avaria Grossa**: Danos causados por uma situação grave e irreversível
- **Rateio**: Divisão das responsabilidades entre as partes potencialmente formadoras do dano
- **Garantias**: Reais, fidejussórias ou outras formas de garantia para a liberação das cargas

### Referências legais
- Art. 708, § 1º, CPC

### Dicas de prova
- Entenda o conceito de Avaria Grossa e como ela afeta as responsabilidades das partes
- Conheça a importância das garantias na liberação das cargas em caso de Avaria Grossa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.390 (2)", "page_number": 390, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 708, § 1º, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T04:05:35.865632+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=390", "doc_key": "c27d7e176c8ce8a5732a9568bea625ec"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd2ce44f258a0ed97150111559a645574e1eefeb3ffa0c67146ed934a2dc0ca8e'),
  ('cpiuris2025::ea85bf3c93dfe70d8c11b8ed777ee416', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Homologação de Decisões Estrangeiras e Regulação de Contratos', '## Homologação de Decisões Estrangeiras e Regulação de Contratos

A ação de homologação de decisão estrangeira tem como finalidade conferir eficácia total ou parcial a uma decisão proferida em outro país, para que possa ser executada no Brasil. O regulamento de um contrato pode ser homologado e ter eficácia jurídica.

### Conceitos
- **Ação de Homologação**: Procedimento utilizado para conferir eficácia total ou parcial a uma decisão proferida em outro país
- **Regulação de Contratos**: O processo de criação e homologação de um regulamento de um contrato, que tem natureza condenatória
- **Homologabilidade de Decisões Estrangeiras**: Classificação das decisões estrangeiras que podem ser homologadas no Brasil, como sentenças, decisões parciais, decisões não judiciais e tutelas de urgência
- **Contraditório**: O direito do adversário de se manifestar e apresentar argumentos em uma causa
- **Prazo para Manifestação**: O período durante o qual as partes têm a oportunidade de se manifestar sobre um regulamento ou decisão estrangeira

### Referências legais
- Art. 961, caput e § 2º, CPC
- Art. 960, § 3º, do CPC
- Art. 962, § 1º, CPC
- Art. 962, § 2º, CPC
- Art. 962, § 3º, CPC

### Jurisprudência
- RE 123456
- Tema repetitivo de homologação de decisões estrangeiras

### Dicas de prova
- Entenda a diferença entre homologação total e parcial de decisões estrangeiras
- Conheça as condições para a homologabilidade de decisões não judiciais
- Aprenda a importância do contraditório na homologação de decisões estrangeiras', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.391 (1)", "page_number": 391, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 961, caput e § 2º, CPC", "Art. 960, § 3º, do CPC", "Art. 962, § 1º, CPC", "Art. 962, § 2º, CPC", "Art. 962, § 3º, CPC"], "jurisprudence": ["RE 123456", "Tema repetitivo de homologação de decisões estrangeiras"], "confidence": 0.8, "extracted_at": "2026-05-28T04:06:51.239156+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=391", "doc_key": "ea85bf3c93dfe70d8c11b8ed777ee416"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f0de607987d05d8e2ea72397ede77ec9d680d9f409137634db88082ec0f3c530'),
  ('cpiuris2025::440c9895f785f7703a41ca410c7e4eea', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Dispensa de Homologação em Decisões Estrangeiras', '## Dispensa de Homologação em Decisões Estrangeiras

A sentença estrangeira de divórcio consensual dispensa a homologação, mas se sujeita ao controle jurisdicional. A cognição do STJ é restrita e apenas verificará se a decisão foi proferida por autoridade competente e houve citação válida na origem.

### Conceitos
- **Dispensa de Homologação**: Exceção à homologação de decisões estrangeiras
- **Decisão Estrangeira**: Sentença emitida por autoridade jurisdicional de outro país
- **Citação Válida**: Obrigação de ser citado na origem para a decisão estrangeira
- **Controle Jurisdicional**: Exercício da competência do juiz para revisar a decisão estrangeira

### Referências legais
- Art. 962, § 4º, CPC
- Art. 961, § 5º, CPC
- Art. 961, § 6º, CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre dispensa de homologação e tratados internacionais
- Entender a limitação do controle jurisdicional sobre decisões estrangeiras', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.391 (2)", "page_number": 391, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 962, § 4º, CPC", "Art. 961, § 5º, CPC", "Art. 961, § 6º, CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T04:07:35.026635+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=391", "doc_key": "440c9895f785f7703a41ca410c7e4eea"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '919ec4dba627b96dd4f172c4520d17c3c3c8ec892b70c9794e2329bc485b3539'),
  ('cpiuris2025::bbc49c228582ffd6c2eb5181795fbffa', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ação de Homologação de Decisão Estrangeira', '## Ação de Homologação de Decisão Estrangeira

Regras e procedimentos para a homologação de decisões estrangeiras no Brasil, incluindo requisitos da petição inicial, instrução do processo e prazos.

### Conceitos
- **Ação de Homologação**: Procedimento para reconhecer a validade de uma decisão estrangeira em um processo brasileiro.
- **Decisão Estrangeira**: Julgamento proferido por uma autoridade jurisdicional estrangeira.
- **Regimento Interno do STJ**: Normas que regem o procedimento da Suprema Corte de Justiça (STJ) no Brasil.
- **Tradução Oficial**: Documentação traduzida por um tradutor juramentado e aprovada pela autoridade consular brasileira.
- **Tutela Provisória**: Medida provisória concedida pelo STJ para proteger os direitos do réu em uma ação de homologação de decisão estrangeira.

### Referências legais
- Art. 216-A RITSTJ
- Art. 216-C RITSTJ
- Art. 216-E RITSTJ
- Art. 216-G RITSTJ
- Art. 216-H RITSTJ
- Art. 216-I RITSTJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da tradução oficial e do Regimento Interno do STJ na ação de homologação de decisão estrangeira.
- Conheça os requisitos da petição inicial e os prazos para réplica e tréplica em uma ação de homologação de decisão estrangeira.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.392 (1)", "page_number": 392, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 216-A RITSTJ", "Art. 216-C RITSTJ", "Art. 216-E RITSTJ", "Art. 216-G RITSTJ", "Art. 216-H RITSTJ", "Art. 216-I RITSTJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T04:08:47.744901+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=392", "doc_key": "bbc49c228582ffd6c2eb5181795fbffa"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ad19abbe2d507db6aab0acd6e376f0c201b0e9360a4174240cd99c75f1aa0f1d'),
  ('cpiuris2025::df5574ecf341b4c953debe2c7491eebf', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Manifestação em 15 dias e impugnação do pedido', '## Manifestação em 15 dias e impugnação do pedido

A manifestação em 15 dias permite ao parquet impugnar o pedido, enquanto decisões unipessoais de homologação de decisão estrangeira podem ser apeladas por agravo interno.

### Conceitos
- **Manifestação em 15 dias**: O prazo para manifestação em 15 dias é estabelecido pelo art. 216-L do RISTJ.
- **Impugnação do pedido**: O parquet pode impugnar o pedido dentro do prazo de 15 dias.
- **Agravo interno**: É cabível agravo interno em decisões unipessoais de homologação de decisão estrangeira, conforme art. 1.021 do CPC e art. 216-M do RISTJ.
- **Recurso extraordinário**: O recurso extraordinário é cabível se presentes os pressupostos estabelecidos no art. 102, III, a, da CF/88.
- **Processo necessário**: Um processo é necessário quando indispensável à execução de uma decisão estrangeira em território nacional.
- **Condenação do réu**: A condenação do réu não é cabível em custas, despesas e honorários se não houver resistência ou se o réu revel for nomeado curador especial.

### Referências legais
- Art. 216-L do RISTJ
- Art. 1.021 do CPC
- Art. 102, III, a da CF/88

### Jurisprudência
- SEC 14.812/EX
- HDE 1.614/EX
- HDE 1.809/EX

### Dicas de prova
- Pegar a distinção entre manifestação em 15 dias e impugnação do pedido.
- Entender o conceito de processo necessário e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.392 (2)", "page_number": 392, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 216-L do RISTJ", "Art. 1.021 do CPC", "Art. 102, III, a da CF/88"], "jurisprudence": ["SEC 14.812/EX", "HDE 1.614/EX", "HDE 1.809/EX"], "confidence": 0.8, "extracted_at": "2026-05-28T04:09:49.692792+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=392", "doc_key": "df5574ecf341b4c953debe2c7491eebf"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd012f9281081f9f66ee879b0fa28fe64f05280f224c5c9643892981fa4cb6775'),
  ('cpiuris2025::0245ff5f9b9dbf167675c5501091083a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Homologação de Penhor Legal e Execução de Decisões Estrangeiras', '## Homologação de Penhor Legal e Execução de Decisões Estrangeiras

O penhor legal é uma modalidade de direito real de garantia que pode ser homologado judicialmente ou extrajudicialmente. A homologação extrajudicial é feita pelo notário, enquanto a homologação judicial é realizada pelo juiz.

### Conceitos
- **Penhor Legal**: Direito real de garantia que recai sobre bens móveis e pode decorrer da lei ou de acordo entre as partes.
- **Homologação Extrajudicial**: Procedimento realizado pelo notário para homologar o penhor legal, sem a necessidade de citação do devedor.
- **Homologação Judicial**: Procedimento realizado pelo juiz para homologar o penhor legal, após a citação do devedor.
- **Citação do Devedor**: Notificação formal do devedor para pagar ou impugnar a dívida.

### Referências legais
- Art. 703, §§ 2º a 4º, CPC
- Art. 301, I, RISTJ
- Art. 965, caput e parágrafo único, CPC
- Art. 1.467, I e II, CC
- Art. 31, Lei n.º 6.533/1978

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre homologação extrajudicial e judicial do penhor legal.
- Conheça os requisitos para a citação do devedor e o procedimento para impugnar a dívida.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.393 (1)", "page_number": 393, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 703, §§ 2º a 4º, CPC", "Art. 301, I, RISTJ", "Art. 965, caput e parágrafo único, CPC", "Art. 1.467, I e II, CC", "Art. 31, Lei n.º 6.533/1978"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T04:10:51.550574+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=393", "doc_key": "0245ff5f9b9dbf167675c5501091083a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '57631151b8bf478ddb63cb39c90f6e3e69a6cc2f013c35fb9dd331e63e86f38c'),
  ('cpiuris2025::c81c2d730b936a80e6067c58b093252e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Audiência Preliminar no Procedimento de Penhor Legal', '## Audiência Preliminar no Procedimento de Penhor Legal

Resumo do conteúdo sobre audiência preliminar no procedimento de penhor legal, limitações da defesa do devedor e conversão para comum procedimento após a audiência.

### Conceitos
- **Audiência Preliminar**: Reunião especial para discutir questões específicas do procedimento de penhor legal
- **Limitações da Defesa do Devedor**: Matérias que podem ser dedutíveis, como nulidade do processo, extinção da obrigação e inexistência da obrigação
- **Conversão para Comum Procedimento**: Mudança do procedimento de penhor legal para comum após a realização da audiência preliminar

### Referências legais
- Art. 334 do CPC
- Art. 704, I a IV, do CPC
- Art. 705 do CPC

### Dicas de prova
- Entenda a diferença entre audiência de mediação e conciliação versus audiência preliminar no procedimento de penhor legal.
- Conheça as limitações da defesa do devedor em relação à homologação extrajudicial ou judicial do penhor legal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.393 (2)", "page_number": 393, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 334 do CPC", "Art. 704, I a IV, do CPC", "Art. 705 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T04:11:47.794149+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=393", "doc_key": "c81c2d730b936a80e6067c58b093252e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f0670bb36fe494ee4c5911e5c9407fb698e176981dd97ac1f33c16276fd00f83'),
  ('cpiuris2025::ca611612a778eb04f60667753d8efab1', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Jurisdição Contenciosa e Voluntária', '## Jurisdição Contenciosa e Voluntária

A jurisdição contenciosa e voluntária é atividade jurisdicional que cria, modifica ou extinge situações e relações jurídicas, pressupondo a inexistência de lide e a existência de interesses convergentes.

### Conceitos
- **Jurisdição Contenciosa**: atividade jurisdicional que cria, modifica ou extinge situações e relações jurídicas
- **Jurisdição Voluntária**: atividade jurisdicional que visa a criação, modificação ou extinção de situações e relações jurídicas, pressupondo a inexistência de lide e a existência de interesses convergentes
- **Princípio Dispositivo**: necessidade de provocação dos interessados para formular o pedido e instruir o requerimento

### Referências legais
- art. 706, caput e §1º, CPC
- art. 720, CPC
- art. 721, CPC
- art. 722, CPC

### Dicas de prova
- Entenda o conceito de jurisdição contenciosa e voluntária e como elas se diferenciam.
- Conheça o princípio dispositivo e a necessidade de provocação dos interessados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.394 (1)", "page_number": 394, "discipline": "Direito Processual Civil", "legal_refs": ["art. 706, caput e §1º, CPC", "art. 720, CPC", "art. 721, CPC", "art. 722, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T04:12:40.345860+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=394", "doc_key": "ca611612a778eb04f60667753d8efab1"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '769e8e86e324331cadbe0544e821ec82565856c769d04267effbcc31d9eb667d'),
  ('cpiuris2025::550924e4088ce1c327e65ad3d57a3c58', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Revelia e Nulidade de Processo', '## Revelia e Nulidade de Processo

A revelia não é aplicável em casos de lide e conflito de interesses, e a sentença deve ser proferida no prazo de 10 dias. O juiz pode adotar solução equitativa com base em conveniência ou oportunidade.

### Conceitos
- **Revelia**: Falta de contestação em procedimento
- **Lide e Conflito de Interesses**: Conflito entre interesses opostos
- **Sentença**: Decisão do juiz
- **Critérios Discricionários**: Solução equitativa com base em conveniência ou oportunidade

### Referências legais
- Art. 723, caput, CPC

### Dicas de prova
- Distinção entre revelia e nulidade de processo
- Importância da sentença no prazo de 10 dias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.394 (2)", "page_number": 394, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 723, caput, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T04:13:16.611357+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=394", "doc_key": "550924e4088ce1c327e65ad3d57a3c58"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '3f3896f8643590c1effc2e40b0601cbe251b8e30bbe98fd7546e7da06e56dcda'),
  ('cpiuris2025::8fc6ab7bcbefab4a009ee3b1a0eabbfe', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Procedimentos Especiais de Jurisdição Contenciosa e Voluntária', '## Procedimentos Especiais de Jurisdição Contenciosa e Voluntária

Art. 725 do CPC lista hipóteses que se processarão sob procedimentos de jurisdição voluntária, incluindo emancipação de menores, sub-rogação, alienação de bens de crianças e administração de coisa comum.

### Conceitos
- **Jurisdição Voluntária**: Procedimento que não exige ordem judicial ou prova
- **Emanipação do Menor**: Necessária quando houver divergência entre os pais
- **Sub-Rogação**: Meio do qual se transfere a cláusula de inalienabilidade ou impenhorabilidade
- **Alienação de Bens de Crianças**: Requer prévia autorização judicial
- **Administração de Coisa Comum**: Requer manifestação do Poder Judiciário

### Referências legais
- Art. 725 do CPC

### Dicas de prova
- Diferenciar entre jurisdição contenciosa e voluntária
- Entender a necessidade de prévia autorização judicial para certos atos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.395 (1)", "page_number": 395, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 725 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T04:14:14.224025+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=395", "doc_key": "8fc6ab7bcbefab4a009ee3b1a0eabbfe"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '368621103ec2b06c16ace4b94841d7cc7cf6c74d5ad7aedf718049d628710296'),
  ('cpiuris2025::a7f302b0b44a514d0fa2116d71eaac0b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Protesto, Notificação e Interpelação em Processo Cível', '## Protesto, Notificação e Interpelação em Processo Cível

Resumo objetivo: A regra geral é que não há sentença, mas existem exceções para protesto, notificação e interpelação. O juiz determina a intimação da pessoa indicada se requerida, salvo hipótese de edital.

### Conceitos
- **Protesto**: Documentação de um fato
- **Notificação**: Documentação de um fato associada a um ato de comunicação
- **Interpelação**: Documentação de um fato com intenção de gerar um ato da outra parte

### Referências legais
- Art. 726, caput, CPC
- Art. 726, § 1º, CPC
- Art. 728, I e II, CPC
- Art. 729, CPC

### Dicas de prova
- Diferenciar entre protesto, notificação e interpelação
- Entender a hipótese de edital e sua exceção
- Conhecer o procedimento para intimação da pessoa indicada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.395 (2)", "page_number": 395, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 726, caput, CPC", "Art. 726, § 1º, CPC", "Art. 728, I e II, CPC", "Art. 729, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T04:14:56.463243+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=395", "doc_key": "a7f302b0b44a514d0fa2116d71eaac0b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '0f34d1441ac0203859400cac957039c5b47464425121a6e8b543c33f822a1c66'),
  ('cpiuris2025::a527e827b105eefe489627147b8092f9', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Procedimentos Especiais de Jurisdição Contenciosa e Voluntária', '## Procedimentos Especiais de Jurisdição Contenciosa e Voluntária

Descreve procedimentos especiais de jurisdição contenciosa e voluntária, incluindo alienação judicial, divórcio, separação consensual, extinção da união estável e alteração do regime de bens do matrimônio.

### Conceitos
- **Alienação Judicial**: Procedimento pelo qual o juiz determina a alienação de um bem sem acordo entre os interessados.
- **Divórcio**: Processo que visa a dissolução da união conjugal e a partilha dos bens comuns.
- **Separação Consensual**: Acordo entre os cônjuges para separar-se sem necessidade de processo judicial.
- **Extinção da União Estável**: Processo que visa a dissolução da união estável sem necessidade de processo judicial.
- **Alteração do Regime de Bens do Matrimônio**: Mudança no regime de partilha dos bens comuns entre os cônjuges.

### Referências legais
- Art. 879 a 903, CPC

### Dicas de prova
- Entenda a diferença entre alienação judicial e leilão judicial.
- Conheça as condições para a homologação judicial de divórcio, separação consensual, extinção da união estável e alteração do regime de bens do matrimônio.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.396 (1)", "page_number": 396, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 879 a 903, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T04:15:54.444822+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=396", "doc_key": "a527e827b105eefe489627147b8092f9"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '482d98a2679d6cdafe7e69bef0ffeeab127426314149c54f37731126700d29b4'),
  ('cpiuris2025::becdf7abfd1bd995b1b0294b13722973', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Homologação Extrajudicial de Separação ou Dissolução', '## Homologação Extrajudicial de Separação ou Dissolução

A homologação extrajudicial de separação ou dissolução é possível mediante escritura pública, desde que as partes estejam representadas por advogados ou defensores e não haja nascituros ou filhos incapazes.

### Conceitos
- **Homologação Extrajudicial**: Ato de reconhecer a validade de um ato processual sem necessidade de julgamento judicial.
- **Separação ou Dissolução**: Fim do casamento, que pode ser homologado extrajudicialmente.
- **Escritura Pública**: Documento público que regista a separação ou dissolução de casal.
- **Advogados ou Defensores**: Representantes legais das partes em procedimentos judiciais.
- **Nascituros ou Filhos Incapazes**: Pessoas que dependem de cuidado e proteção dos pais para sua sobrevivência.
- **Autorização Judicial**: Decisão do juiz que permite proceder com um ato específico.
- **Regime de Bens do Casamento**: Regra que regula a distribuição dos bens entre os cônjuges em caso de separação ou dissolução.
- **Procedimento Motivado**: Ato processual que explica as razões e fundamentos de uma decisão.

### Referências legais
- Art. 731, parágrafo único, CPC; Art. 647 a 658, CPC

### Jurisprudência
- REsp 35.631/CE
- ...

### Dicas de prova
- Diferenciar entre homologação extrajudicial e homologação judicial.
- Entender a importância da representação das partes por advogados ou defensores.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.396 (2)", "page_number": 396, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 731, parágrafo único, CPC; Art. 647 a 658, CPC"], "jurisprudence": ["REsp 35.631/CE", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T04:17:04.160222+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=396", "doc_key": "becdf7abfd1bd995b1b0294b13722973"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '13ae635acce56fef041dea440f276b72857c6ccb2423aa55b72681168437ef79'),
  ('cpiuris2025::d94f3ecda66468cd413e302bf4abe6a9', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Jurisdição Voluntária e Testamentos', '## Jurisdição Voluntária e Testamentos

A jurisdição voluntária é usada para apurar a credibilidade dos motivos apresentados pelas partes, resguardando os direitos de terceiros. No contexto de testamentos, o juiz abre o testamento cerrado se não identificar vício que o torne suspeito de nulidade ou falsidade.

### Conceitos
- **Jurisdição Voluntária**: Uso da jurisdição para apurar a credibilidade dos motivos apresentados pelas partes
- **Testamento Cerrado**: Testamento escrito pelo próprio testador ou por alguém a pedido dele, aprovado por tabelião
- **Testamento Público**: Testamento que segue as regras do testamento cerrado

### Referências legais
- Art. 1.639, § 2º, CC
- Art. 734, caput, CPC
- Art. 735, caput, CPC
- Art. 735, § 1º, CPC
- Art. 735, § 2º, CPC
- Art. 736, CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre testamento cerrado e público
- Conheça as regras para abertura de testamentos
- Identifique os direitos dos terceiros em relação aos testamentos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.397 (1)", "page_number": 397, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.639, § 2º, CC", "Art. 734, caput, CPC", "Art. 735, caput, CPC", "Art. 735, § 1º, CPC", "Art. 735, § 2º, CPC", "Art. 736, CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T04:17:59.527334+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=397", "doc_key": "d94f3ecda66468cd413e302bf4abe6a9"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a2ecbd86b8e46971e69c17237b314d0323ba97b7c55878912f380089486f2ecd'),
  ('cpiuris2025::e54c11466529c1c6553543adfbf8bd08', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Publicação de Testamentos', '## Publicação de Testamentos

O testamento deve ser publicado em determinadas situações, como no marítimo, aeronáutico, militar ou nuncupativo. A publicação pode ser requerida por herdeiro, legatário, testamenteiro ou terceiro detentor do testamento.

### Conceitos
- **Testamento**: Instrumento jurídico que dispõe sobre a distribuição de bens após a morte do autor.
- **Publicação de Testamentos**: Obrigatório em determinadas situações, como no marítimo, aeronáutico, militar ou nuncupativo.
- **Requisitos Legais**: Deverão ser cumpridos para que o testamento seja considerado válido.
- **Intimadação de Herdeiros**: Os herdeiros que não requereram a publicação devem ser intimados e ouvidos.
- **Ministério Público**: Deve ser ouvido após a requisição da publicação.
- **Juiz**: Confirma o testamento após a ouvida do Ministério Público e a intimadação dos herdeiros.
- **Testamento Cerrado**: O que se considera um testamento válido para fins legais.
- **Legitimados**: Os herdeiros, legatários, testamenteiros e terceiros detentores do testamento.

### Referências legais
- Art. 737, caput, CPC

### Jurisprudência
- REsp 1.446.330/SP
- REsp 1.533.179/RS

### Dicas de prova
- Diferenciar entre testamento e publicação.
- Conhecer os requisitos legais para a publicação de testamentos.
- Entender o papel do Ministério Público na publicação de testamentos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.397 (2)", "page_number": 397, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 737, caput, CPC"], "jurisprudence": ["REsp 1.446.330/SP", "REsp 1.533.179/RS"], "confidence": 0.8, "extracted_at": "2026-05-28T04:19:02.276617+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=397", "doc_key": "e54c11466529c1c6553543adfbf8bd08"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f9fa4e6837a04d6ea2d9af6f3db81f15c500e1e2f9df3043a0fe401fabc00430'),
  ('cpiuris2025::6b71f74593c2103daf1386570be24e2c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Herança Jacente', '## Herança Jacente

A herança jacente é um ente despersonalizado administrado por um curador sob fiscalização do juiz, existindo até que se habilitem os herdeiros ou se reconheça a vacância da herança.

### Conceitos
- **Curador**: Administrador de uma herança jacente
- **Arrecadação**: Procedimento para coletar bens e direitos da herença
- **Auto de inquirição e informação**: Documento que contém as informações coletadas durante as diligências de arrecadação
- **Princípio da demanda**: Princípio que obriga o juiz a provar a existência da demanda antes de iniciar o processo

### Referências legais
- Art. 1819, CC
- Art. 739, caput e § 1º, CPC
- Arts. 159 a 161, CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de curador e sua responsabilidade na herança jacente
- Conheça as regras de arrecadação e auto de inquirição e informação
- Aprenda a aplicar o princípio da demanda no procedimento da herança jacente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.398 (1)", "page_number": 398, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1819, CC", "Art. 739, caput e § 1º, CPC", "Arts. 159 a 161, CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T04:20:05.295073+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=398", "doc_key": "6b71f74593c2103daf1386570be24e2c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6d171fe1e7f460cd03db7623c9c7eaaee723d0c909228b843ab01a88587229cf'),
  ('cpiuris2025::7a0287171f1dd7d60cebab664e0c7e14', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Arrecadação de Bens e Priorização do Julgamento de Mérito', '## Arrecadação de Bens e Priorização do Julgamento de Mérito

O juiz deve priorizar o julgamento de mérito, cooperando na arrecadação de bens. Os documentos devem ser examinados e, se não apresentarem informações interessantes, devem ser entregues aos sucessores ou queimados.

### Conceitos
- **Arrecadação**: Procedimento pelo qual os bens do falecido são objeto de aquisição por terceiros.
- **Priorização do Julgamento de Mérito**: A ordem em que os processos devem ser julgados para garantir a eficiência e a justiça no sistema jurídico.
- **Cooperar na Priorização**: Participar ativamente na determinação da ordem de julgamento de mérito para garantir a eficiência e a justiça.
- **Documentos a Examinar**: Os documentos que devem ser analisados pelo juiz para determinar se apresentam informações interessantes ou não.
- **Entrega aos Sucessores**: A entrega dos documentos aos sucessores, que devem utilizá-los para localizar herdeiros e destino de bens.
- **Queimamento de Documentos**: O procedimento pelo qual os documentos são destruídos se não apresentarem informações interessantes.

### Referências legais
- Art. 740, § 4º, CPC

### Jurisprudência
- REsp 1.837.129/ES

### Dicas de prova
- Entenda a importância da priorização do julgamento de mérito e como isso afeta a eficiência do sistema jurídico.
- Conheça o procedimento para arrecadação de bens e como ele se relaciona com a entrega aos sucessores ou queimamento de documentos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.398 (2)", "page_number": 398, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 740, § 4º, CPC"], "jurisprudence": ["REsp 1.837.129/ES"], "confidence": 0.8, "extracted_at": "2026-05-28T04:21:04.906854+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=398", "doc_key": "7a0287171f1dd7d60cebab664e0c7e14"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '2695da423382f1c1368f852b380bd82079455677600ede18e6a94b027762fa24'),
  ('cpiuris2025::e49dfc11a61f445bae7bdb629bd8438a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Alienação de Bens em Sucessões', '## Alienação de Bens em Sucessões

Regra da alienação de bens móveis, semoventes, títulos e créditos, ações e imóveis em sucessões, com restrições para certos tipos de bens.

### Conceitos
- **Alienação**: Venda ou transferência de um bem
- **Succesoção**: Procedimento utilizado para a divisão de bens em caso de morte de um dos cônjuges, companheiro ou herdeiro
- **Vacância**: Fim do processo de sucessão após o prazo de 1 ano sem que haja herdeiro habilitado
- **Curador**: Pessoa nomeada pelo juiz para representar os interesses de um ausente

### Referências legais
- Art. 741, caput, CPC
- Art. 742, I a V, CPC
- Art. 743, caput e § 2º, CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre alienação e sucessão.
- Conheça as restrições para a alienação de certos tipos de bens.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.399 (1)", "page_number": 399, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 741, caput, CPC", "Art. 742, I a V, CPC", "Art. 743, caput e § 2º, CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T04:21:52.224930+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=399", "doc_key": "e49dfc11a61f445bae7bdb629bd8438a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'cc0b566b8efc9d5ade6527e40a74c82defd5e5e4e8b5daf401b5ee61cc132a51'),
  ('cpiuris2025::09d82ecc9555e24d260fce632d78e4de', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Sucessões e Coisas Vagas', '## Sucessões e Coisas Vagas

Regras para a conversão de morte em sucessão definitiva ou abertura diretamente da sucessão, além do procedimento comum para os sucessores provisórios ou definitivos.

### Conceitos
- **Sucessão Definitiva**: Processo que se inicia após a morte de um indivíduo
- **Sucessões Provisórias**: Processos que se iniciam antes da morte do indivíduo, com o objetivo de proteger os direitos dos herdeiros
- **Ministério Público**: Órgão responsável por defender a ordem jurídica e proteger os interesses do Estado
- **Fazenda Pública**: Representante do Estado em procedimentos judiciais

### Referências legais
- Art. 37, CC
- Art. 38, CC
- Art. 745, § 4º, CPC

### Jurisprudência
- REsp 36.873/SP
- REsp 1.924.451/SP

### Dicas de prova
- Entenda a diferença entre sucessões provisórias e definitivas
- Conheça o procedimento comum para os sucessores provisórios ou definitivos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.399 (2)", "page_number": 399, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 37, CC", "Art. 38, CC", "Art. 745, § 4º, CPC"], "jurisprudence": ["REsp 36.873/SP", "REsp 1.924.451/SP"], "confidence": 0.8, "extracted_at": "2026-05-28T04:22:46.049336+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=399", "doc_key": "09d82ecc9555e24d260fce632d78e4de"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '675018b947c7f4d2c6caf0889051341f1b0d1d65330dc767defdcede6abee10e'),
  ('cpiuris2025::16462412ae2b069f57f11762212537b1', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Interdição', '## Interdição

A interdição é um procedimento especial destinado a proteger os indivíduos incapazes de se autogovernar, sendo necessário o envolvimento do Estado. O processo deve ser iniciado por legitimados ativos e especificar os fatos relacionados à incapacidade do interditando.

### Conceitos
- **Interdição**: Procedimento especial para proteger indivíduos incapazes de se autogovernar
- **Legitimidade ativa**: Direito do Ministério Público e outros legitimados para ajuizar ação de interdição
- **Capacidade**: Condição necessária para que alguém possa se autogovernar

### Referências legais
- Art. 747, I a IV, CPC
- Art. 748, I e II, CPC
- Art. 749, caput, CPC
- Art. 750, CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a definição de interdição e seus requisitos legais.
- Conheça os legitimados ativos que podem ajuizar ação de interdição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.400 (1)", "page_number": 400, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 747, I a IV, CPC", "Art. 748, I e II, CPC", "Art. 749, caput, CPC", "Art. 750, CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T04:23:32.549355+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=400", "doc_key": "16462412ae2b069f57f11762212537b1"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '40d77b7c1d343b98931b784e090fd7fe2b5929aeddcb02373a7726d1727b9d4a'),
  ('cpiuris2025::62a6c55c225c224e7cd37c4bb78b0c29', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Impugnação do Interditando e Curatela', '## Impugnação do Interditando e Curatela

Após a entrevista, o interditando tem 15 dias para impugnar sua própria interdição. Se impugnado, será nomeado curador especial e, em caso de ausência, um curador substituto será designado.

### Conceitos
- **Curatela**: Intervenção do juiz na gestão dos bens de uma pessoa incapaz
- **Impugnação do Interditando**: Ação do interditando para contestar sua própria interdição
- **Curador Especial**: Pessoa nomeada para gerir os bens de um interditando incapaz
- **Curador Substituto**: Pessoa designada para gerir os bens de um interditando incapaz em caso de ausência do curador especial

### Referências legais
- Art. 752, caput, CPC

### Dicas de prova
- Entenda a diferença entre curatela e impugnação do interditando.
- Conheça as regras para a nomeação de curador especial e substituto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.400 (2)", "page_number": 400, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 752, caput, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T04:24:15.633975+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=400", "doc_key": "62a6c55c225c224e7cd37c4bb78b0c29"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd56f0a43bb218ccc4a1b2505fc583e2200131fb827e30a39a40e2ad69f8a5fe1'),
  ('cpiuris2025::d8ccc5906d3df45dfe3a41b2912d06cb', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Tutela e curatela', '## Tutela e curatela

Regras para a nomeação do curador e tutela de incapazes, incluindo o prazo para compromisso e renúncia ao encargo.

### Conceitos
- **Curatela**: Administração dos bens de um incapaz
- **Tutela**: Proteção dos direitos de um incapaz
- **Nomeação do curador**: Decisão do juiz que nomeia o responsável pela tutela ou curatela do incapaz
- **Prazo para compromisso**: 5 dias contados da intimação do despacho que mandar cumprir o testamento ou instrumento público
- **Renúncia ao encargo**: Sob pena de renunciar ao direito de escusar-se

### Referências legais
- Art. 754, CPC
- Art. 755, I e II, §§ 1º a 3º, CPC
- Art. 756, caput, §§ 1º a 4º, CPC
- Art. 759, I e II, e § 2º, CPC

### Dicas de prova
- Entenda a diferença entre tutela e curatela.
- Conheça o prazo para compromisso do tutor ou curador.
- Aprenda a rejeitar o encargo de forma correta.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.401 (1)", "page_number": 401, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 754, CPC", "Art. 755, I e II, §§ 1º a 3º, CPC", "Art. 756, caput, §§ 1º a 4º, CPC", "Art. 759, I e II, e § 2º, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T04:25:22.660133+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=401", "doc_key": "d8ccc5906d3df45dfe3a41b2912d06cb"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '21818edb951bcd521656edfac2fb58ace31f6e6e0cd6fff07821cfd850cdd71c'),
  ('cpiuris2025::2afcccf3f3989ed6332d6c4680791b6f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Remoção do Tutor ou Curador', '## Remoção do Tutor ou Curador

O tutor ou curador pode ser removido a pedido do Ministério Público ou de quem tenha legítimo interesse. O processo segue pelo procedimento comum após o prazo de contestação, e o tutor ou curador pode requerer exoneração após 2 anos de nomeação.

### Conceitos
- **Tutoria**: A figura jurídica que autoriza uma pessoa a representar um menor de idade em procedimentos judiciais.
- **Curatela**: A figura jurídica que autoriza uma pessoa a representar um menor de idade em procedimentos judiciais, com maior grau de autoridade do que o tutor.
- **Remoção**: O ato de remover alguém de um cargo ou função.
- **Prazo**: Um período de tempo estabelecido para realizar uma ação ou cumprir uma obrigação.
- **Contestação**: A resposta apresentada por uma parte em um processo judicial para negar a validade de uma ação ou reclamação.
- **Procedimento comum**: O procedimento utilizado em processos civis, que é diferente do procedimento especial.
- **Cautelarmente**: De forma temporária e preventiva, sem necessidade de uma decisão final.
- **Substituto**: Uma pessoa que assume a função de outra em um processo judicial.

### Referências legais
- Art. 761, caput e parágrafo único, CPC
- Art. 762, CPC
- Art. 1765, CC
- Art. 763, caput e § 1º, CPC

### Jurisprudência
- REsp 1.685.826/BA
- REsp 1.735.668/MT

### Dicas de prova
- Pergunte sobre a diferença entre tutoria e curatela.
- Entenda o conceito de prazo para contestação e exoneração.
- Conheça as consequências da remoção do tutor ou curador.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.401 (2)", "page_number": 401, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 761, caput e parágrafo único, CPC", "Art. 762, CPC", "Art. 1765, CC", "Art. 763, caput e § 1º, CPC"], "jurisprudence": ["REsp 1.685.826/BA", "REsp 1.735.668/MT"], "confidence": 0.8, "extracted_at": "2026-05-28T04:26:28.311870+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=401", "doc_key": "2afcccf3f3989ed6332d6c4680791b6f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '52d50cecb3a926c626cfe700a1a6a6875cfa67adff81a25786c4ffbffbe9e464'),
  ('cpiuris2025::90fbc35924cdf18da13621b75eee12d1', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Organização e fiscalização das fundações', '## Organização e fiscalização das fundações

As fundações têm interesse público e, portanto, a prévia deliberação do Ministério Público é necessária. O juiz pode decidir sobre a aprovação ou extinção da fundação.

### Conceitos
- **fundo**: instituição sem fins lucrativos
- **Ministério Público**: órgão responsável pela fiscalização das fundações
- **deliberação**: decisão tomada pelo Ministério Público sobre a aprovação ou extinção da fundação
- **art. 764, I e II, e § 2º, CPC**: disposição do Código de Processo Civil que regula a aprovação das fundações
- **art. 765, I e III, CPC**: disposição do Código de Processo Civil que regula a extinção das fundações

### Referências legais
- Art. 764, I e II, e § 2º, CPC
- Art. 765, I e III, CPC

### Dicas de prova
- Entenda a importância da prévia deliberação do Ministério Público sobre as fundações.
- Conheça as disposições do Código de Processo Civil que regem a aprovação e extinção das fundações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.402 (1)", "page_number": 402, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 764, I e II, e § 2º, CPC", "Art. 765, I e III, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T04:27:23.205276+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=402", "doc_key": "90fbc35924cdf18da13621b75eee12d1"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1576c1b344dc98674c6692f57eff96d4e266678afd49d70d1d7f85055d55b2e2'),
  ('cpiuris2025::f9618e624c5f1693ee9a7e119a0df3cc', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ações Possessórias', '## Ações Possessórias

Resumo objetivo: Ação possessória é distribuída com urgência e deve ser ouvida o comandante e testemunhas. Em ações possessórias coletivas, a citação de todos os ocupantes pode ser pessoal, mas não há necessidade de curador especial.

### Conceitos
- **Ação Possessória**: Processo em que um dos litigantes busca a posse de imóvel
- **Citação Pessoal**: Ocupantes devem ser citados pessoalmente, mas não há necessidade de curador especial
- **Audiência Contínua**: Realizada para ouvir todos os envolvidos e ratificar o protesto ou processo testemunhável

### Referências legais
- Art. 768, caput, §§ 1º e 2º, CPC; Arts. 769 e 770, caput e parágrafo único, CPC

### Dicas de prova
- Entenda a diferença entre ações possessórias coletivas e individuais
- Conheça as regras de audiência contínua e citação pessoal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.402 (2)", "page_number": 402, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 768, caput, §§ 1º e 2º, CPC; Arts. 769 e 770, caput e parágrafo único, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T04:28:15.200682+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=402", "doc_key": "f9618e624c5f1693ee9a7e119a0df3cc"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6eccfffa4dead676150f00c5af2745a4e55287477b71c5f8f7efafc90e159228'),
  ('cpiuris2025::7fb8a6f353f9affa777c45b9f56ee1f5', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Procedimentos Especiais de Jurisdição Contenciosa e Voluntária', '## Procedimentos Especiais de Jurisdição Contenciosa e Voluntária

Discute-se procedimentos especiais de jurisdição contenciosa e voluntária, incluindo a concessão da liminar possessória, ações de divisão e demarcação de terras, inventariamento do espólio e condenação em honorários de sucumbência.

### Conceitos
- **Audiência de justificação**: Reunião do juiz com as partes para esclarecer fatos e fundamentações
- **Prova pericial**: Exame técnico de um objeto ou documento para determinar sua autenticidade ou valor
- **Sentença**: Decisão final do juiz em uma ação
- **Impugnação**: Recurso apresentado por uma das partes contra uma decisão do juiz

### Referências legais
- Art. 522 Código de Processo Civil
- Súmula 656 STF

### Dicas de prova
- Diferenciar entre a audiência de justificação e a prova pericial
- Entender a natureza da sentença em procedimentos especiais
- Conhecer as regras para impugnação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.403 (1)", "page_number": 403, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 522 Código de Processo Civil", "Súmula 656 STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T04:29:05.125794+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=403", "doc_key": "7fb8a6f353f9affa777c45b9f56ee1f5"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '503328b0776959af28f904a6c68ecdeaae28f327d01cca3f9901671021ade35f'),
  ('cpiuris2025::52ca288724138ee45afef7934a68f1a6', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Mandados de Pagamento e Honorários', '## Mandados de Pagamento e Honorários

O texto destaca a importância dos mandados de pagamento e o cálculo dos honorários, destacando-se a faculdade do réu em apresentar contestação ou opor embargos.

### Conceitos
- **Mandado de Pagamento**: Ordem judicial que obriga um indivíduo a pagar uma determinada quantia
- **Tutela Provisória**: Medida provisória tomada pelo juiz para proteger os direitos de alguém, geralmente com natureza urgente
- **Honorários**: Compensação paga ao advogado pelo cliente vencedor em um processo

### Referências legais
- Art. 273 do Código de Processo Civil

### Dicas de prova
- Entenda a diferença entre mandados de pagamento com natureza provisória e urgência
- Conheça as regras para cálculo dos honorários', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.403 (2)", "page_number": 403, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 273 do Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T04:29:41.866066+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=403", "doc_key": "52ca288724138ee45afef7934a68f1a6"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd5c5975a2f7c447004dbb4e3ff2279f63290feb617f698b098f15799d4197ea2'),
  ('cpiuris2025::89fd3ea6014ba66c8fe3e3f05c8aa6b9', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Interdito Proibitório', '## Interdito Proibitório

O interdito proibitório é uma medida cautelar que visa evitar a violência iminente contra um direito. Ele pode ser requerido para qualquer outro tipo de receio, não sendo necessário o justo receio. A tutela deve ser requerida pelo possuidor, desde que indireto, e não apenas pelo detentor do bem.

### Conceitos
- **Interdito Proibitório**: Medida cautelar para evitar violência iminente contra um direito
- **Justo Receio**: Receio legítimo que justifica a medida cautelar
- **Possuidor**: Pessoa que detém o direito de posse sobre um bem
- **Detentor**: Pessoa que detém o bem, mas não necessariamente tem o direito de posse

### Referências legais
- CPC - Art. 821
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferencie entre interdito proibitório e outro tipo de receio
- Entenda a diferença entre possuidor e detentor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.404 (1)", "page_number": 404, "discipline": "Direito Processual Civil", "legal_refs": ["CPC - Art. 821", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T04:30:38.697025+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=404", "doc_key": "89fd3ea6014ba66c8fe3e3f05c8aa6b9"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '25a78f146f40c90f63f8dc3e31805ab9ca7b1843d138f4ca995d58eefaae657b'),
  ('cpiuris2025::6b4c7299fd3098ef7cbb6897b8ffcb95', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Obrigação da Fazenda Pública de Sobrestar a Partilha em Caso de Dívida', '## Obrigação da Fazenda Pública de Sobrestar a Partilha em Caso de Dívida

A fazenda pública deve sobrestar o julgamento da partilha se houver dívida com a fazenda pública não quitada.

### Conceitos
- **Sobrestamento da Partilha**: Obrigação da fazenda pública de sobrestar o julgamento da partilha em caso de dívida não quitada.
- **Ação Monitória**: Procedimento que visa a entrega de bem móvel com fundamento em prova escrita sem eficácia de título executivo
- **Litisconsórcio Passivo e Multitudinário**: Situação em que várias pessoas hipossuficientes são litigantes passivos em uma ação possessória

### Referências legais
- Art. 555, II, CPC
- Art. 554, § 1º, CPC
- Art. 556, CPC

### Dicas de prova
- Entenda a diferença entre ação monitória e ação possessória.
- Conheça as regras de sobrestamento da partilha e litisconsórcio passivo e multitudinário.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.404 (2)", "page_number": 404, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 555, II, CPC", "Art. 554, § 1º, CPC", "Art. 556, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T04:31:22.512412+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=404", "doc_key": "6b4c7299fd3098ef7cbb6897b8ffcb95"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '62e9bb8a3fbc0359ae481c6d9b4301a7e3fdd3e8b88a31aff1581b1da20cc936'),
  ('cpiuris2025::1674e089328f2ffc3cba4a63795b22c1', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Procedimentos Especiais de Jurisdição Contenciosa e Voluntária', '## Procedimentos Especiais de Jurisdição Contenciosa e Voluntária

Questões sobre procedimentos especiais em jurisdição contenciosa e voluntária, incluindo audiência, embargos, honorários e interdito proibitório.

### Conceitos
- **Audiência**: Reunião do juiz com as partes para discutir o caso
- **Embargo de terceiro**: Ação que um dos litigantes apresenta contra outrem, que está envolvido no processo
- **Honorários**: Indemnização paga ao advogado por sua participação no caso
- **Interdito proibitório**: Medida cautelar que impede alguém de realizar uma ação ou ato prejudicial

### Referências legais
- Art. 562, caput, CPC
- Art. 570, CPC
- Art. 573, CPC
- Art. 581, caput, CPC
- Art. 618, I, CPC
- Art. 619, I, CPC
- Art. 619, III, CPC
- Art. 677, caput, CPC
- Súmula 303 do STJ
- Tese Repetitiva 872 do STJ

### Jurisprudência
- REsp 1.746.337/RS
- REsp 1.680.168/SP
- REsp 1.874.603/DF

### Dicas de prova
- Pergunte sobre a natureza jurídica da audiência e do embargos de terceiro
- Entenda o conceito de honorários e interdito proibitório
- Conheça as regras para a concessão da liminar e a oitiva do réu', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.405", "page_number": 405, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 562, caput, CPC", "Art. 570, CPC", "Art. 573, CPC", "Art. 581, caput, CPC", "Art. 618, I, CPC", "Art. 619, I, CPC", "Art. 619, III, CPC", "Art. 677, caput, CPC", "Súmula 303 do STJ", "Tese Repetitiva 872 do STJ"], "jurisprudence": ["REsp 1.746.337/RS", "REsp 1.680.168/SP", "REsp 1.874.603/DF"], "confidence": 0.8, "extracted_at": "2026-05-28T04:32:30.708835+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=405", "doc_key": "1674e089328f2ffc3cba4a63795b22c1"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e13c6e5f8fffff19a835de450eed18f1fd0e5c4ccbb505593a375a5c4391718e'),
  ('cpiuris2025::5609c0e38fa51b5a0a56405648bdf003', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Interdito Proibitório e Possessório', '## Interdito Proibitório e Possessório

O interdito proibitório é uma medida preventiva para evitar a consumação da turbação ou do esbulho, protegendo a posse. Pode ser requerido tanto pelo possuidor direto quanto pelo possuidor indireto, desde que comprovem justo receio de serem molestados em sua posse.

### Conceitos
- **Interdito Proibitório**: Medida preventiva para evitar a consumação da turbação ou do esbulho
- **Possuidor Direto**: Pessoa que detém a posse de um imóvel
- **Possuidor Indireto**: Pessoa que tem direito à posse de um imóvel, mas não o detém
- **Justo Receio**: Ameaça real e iminente à posse

### Referências legais
- CPC, Art. 567
- CPC, Art. 536, § 1º

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre interdito proibitório e ação possessória
- Entender o conceito de justo receio e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.406 (1)", "page_number": 406, "discipline": "Direito Processual Civil", "legal_refs": ["CPC, Art. 567", "CPC, Art. 536, § 1º"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T04:33:31.928331+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=406", "doc_key": "5609c0e38fa51b5a0a56405648bdf003"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '7426263c0977372cc0b866c01ef00f7c8208255c5a8ece3fd36007b646ad0937'),
  ('cpiuris2025::3d7e9061228963be15815ee5a8d7a0c2', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ação Monitória', '## Ação Monitória

A ação monitória pode ser proposta por aquele que afirmar ter direito de exigir do devedor capaz, com base em prova escrita sem eficácia de título executivo.

### Conceitos
- **Ação Monitória**: ação que visa a obtenção de uma obrigação de fazer ou não fazer
- **Prova Escrita Sem Eficácia de Título Executivo**: prova que não é suficiente para executar um título judicial
- **Legitidade para Propor Ação Monitória**: direito de exigir do devedor capaz

### Referências legais
- Art. 700, inciso II, do CPC

### Dicas de prova
- Distinção entre alegação e prova
- Importância da intimação da DP em casos de litisconsórcio passivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.406 (2)", "page_number": 406, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 700, inciso II, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T04:34:04.510791+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=406", "doc_key": "3d7e9061228963be15815ee5a8d7a0c2"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '4b8690e361b1b60b9b1ae54acc4c3528d4ab4cdd66c2d7fadba8c4a873d211c8'),
  ('cpiuris2025::d3cf2b4c390420cabb3da07a138927f7', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Intervenção do Ministério Público como fiscal da ordem jurídica', '## Intervenção do Ministério Público como fiscal da ordem jurídica

O art. 178 do CPC estabelece situações em que o MP é obrigatório, mas não abrange todos os procedimentos especiais de jurisdição voluntária.

### Conceitos
- **Defensoria Pública**: instituição que promove direitos humanos e individuais
- **Ministério Público**: órgão do Estado responsável por fiscalizar a ordem jurídica
- **Intervenção do MP**: ação do MP como fiscal da ordem jurídica em casos específicos

### Referências legais
- Art. 178 da Lei nº 9.394/1996
- Art. 185 da Lei nº 8.837/1993

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre intervenção obrigatória e não obrigatória do MP.
- Conheça as hipóteses previstas na lei ou na Constituição Federal que exigem a participação do MP.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.407", "page_number": 407, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 178 da Lei nº 9.394/1996", "Art. 185 da Lei nº 8.837/1993"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T04:34:43.208472+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=407", "doc_key": "d3cf2b4c390420cabb3da07a138927f7"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '40bbec663e2cab1347eaf13512bb742f5cf1a4b8fcd411c533f943020cb599a7'),
  ('cpiuris2025::18964e7951dd4ac2fac370db486609c5', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Teoria Geral dos Recursos', '## Teoria Geral dos Recursos

O recurso é o remédio voluntário idôneo para reformar, invalidar, esclarecer ou integrar decisões judiciais dentro do mesmo processo.

### Conceitos
- **Voluntariado**: A característica de ser um ato que pode ser feito por quem tem direito e deve fazer.
- **Remessa necessária**: Não é recurso, pois o reexame da questão pelo Tribunal ocorre de modo automático e involuntário.
- **Mandado de segurança**: Não é um recurso, mas uma ação autônoma de impugnação.
- **Taxatividade**: Somente será recurso aquilo que a lei disser textualmente que é.

### Referências legais
- Art. 496, CPC
- Art. 994, CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de voluntariado e remessa necessária.
- Conheça as diferenças entre recursos e ações autônomas de impugnação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.409 (1)", "page_number": 409, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 496, CPC", "Art. 994, CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T04:35:39.907045+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=409", "doc_key": "18964e7951dd4ac2fac370db486609c5"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '8026578db715fb8f213846d01ca40035e66069f15e9da6f920da4dfa21084d4e'),
  ('cpiuris2025::fc4ff299205c1eb8d68e847e9b0ddbc7', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Despacho Irrecorrível', '## Despacho Irrecorrível

Despacho que determina a habilitação de herdeiros em virtude do falecimento da parte, considerado mero ato de impulso oficial.

### Conceitos
- **despacho**: ato do juiz que determina uma medida processual
- **habilitação**: permite ao herdeiro proceder com as ações legais da parte falecida
- **impulso oficial**: ato realizado por funcionário público em exercício de cargo ou função

### Referências legais
- Art. 476 do CPC
- ...

### Jurisprudência
- REsp 1.219.082/GO
- RCD no AgRg no HC 746.844/SP

### Dicas de prova
- Entenda a diferença entre despacho e decisão judicial
- Conheça o conceito de impulso oficial e como se aplica ao despacho', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.409 (2)", "page_number": 409, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 476 do CPC", "..."], "jurisprudence": ["REsp 1.219.082/GO", "RCD no AgRg no HC 746.844/SP"], "confidence": 0.8, "extracted_at": "2026-05-28T04:36:13.795656+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=409", "doc_key": "fc4ff299205c1eb8d68e847e9b0ddbc7"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ceb641fa772e09bd7443f684e7631d86edadb34c90074b3855e9bbd816fe47e3'),
  ('cpiuris2025::9db844c22c1537f87626ea4357655e6f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso e Princípios Recursais', '## Recurso e Princípios Recursais

Descreve o recurso como mecanismo para promover reforma, invalidação, esclarecimento ou integração do pronunciamento jurisdicional, distinguindo entre error in judicando e error in procedendo.

### Conceitos
- **Error in Judicando**: Vício no conteúdo substancial da decisão
- **Error in Procedendo**: Vício relacionado ao desrespeito de normas procedimentais
- **Princípio do Duplo Grau de Jurisdição**: Garantia que permite às partes o reexame da decisão judicial proferida em seu desfavor

### Referências legais
- Art. 138, caput; Art. 950, § 3º; Art. 1.007, § 6º; Art. 1.031, §§ 2º e 3º; Art. 1.035, caput, CPC

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a distinção entre error in judicando e error in procedendo.
- Conheça o princípio do duplo grau de jurisdição e suas limitações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.410 (1)", "page_number": 410, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 138, caput; Art. 950, § 3º; Art. 1.007, § 6º; Art. 1.031, §§ 2º e 3º; Art. 1.035, caput, CPC"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-28T04:37:02.501735+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=410", "doc_key": "9db844c22c1537f87626ea4357655e6f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ecd44c5dd057a3c1f4a00d8e7aa551df38263efa6c3bc0a239df7b3d19ba65cd'),
  ('cpiuris2025::f1f39f378ac1a725b81b424c47b4f2d5', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso e Princípio da Taxatividade', '## Recurso e Princípio da Taxatividade

O princípio da taxatividade determina que apenas recursos expressamente previstos pela lei podem ser considerados válidos, excluindo-se a possibilidade de criação ou modificação de recursos por outras modalidades normativas ou convenções entre as partes.

### Conceitos
- **Princípio da Taxatividade**: Determina que apenas recursos expressamente previstos pela lei são válidos
- **Recurso**: Mêsagem formal apresentada à Justiça para impugnar uma decisão
- **Lei Federal**: Normas legais emitidas pelo Poder Legislativo federal

### Referências legais
- Art. 34 da Lei n.º 6.830/1980

### Jurisprudência
- AgInt no AREsp 411.892/RJ
- RHC 79.785/RJ
- AREsp 1.751.847/SP

### Dicas de prova
- Entenda a importância do princípio da taxatividade e como ele afeta a admissibilidade de recursos.
- Conheça as diferentes modalidades normativas que podem ser utilizadas para criar ou modificar recursos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.410 (2)", "page_number": 410, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 34 da Lei n.º 6.830/1980"], "jurisprudence": ["AgInt no AREsp 411.892/RJ", "RHC 79.785/RJ", "AREsp 1.751.847/SP"], "confidence": 0.8, "extracted_at": "2026-05-28T04:37:54.409901+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=410", "doc_key": "f1f39f378ac1a725b81b424c47b4f2d5"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '3945063cc138644bae77939e62c7b94f98f774b845c901ac90243064fb71db52'),
  ('cpiuris2025::ecfc14a9143df7a1bfce2c00d535b670', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Princípio da Dialeticidade e Princípio da Singularidade', '## Princípio da Dialeticidade e Princípio da Singularidade

O recurso deve estabelecer um diálogo com a decisão judicial recorrida, impugnando concretamente os seus fundamentos. O princípio da singularidade permite apenas um recurso contra uma mesma decisão.

### Conceitos
- **Princípio da Dialeticidade**: O recurso deve estabelecer um diálogo com a decisão judicial recorrida, impugnando concretamente os seus fundamentos.
- **Princípio da Singularidade**: Permite apenas um recurso contra uma mesma decisão

### Referências legais
- Art. 1.022, II, CPC
- Art. 1.013, § 3º, III, CPC
- Art. 1.030, I, a ou b, CPC
- Art. 1.021, § 2º, CPC

### Jurisprudência
- STJ. 4ª Turma. REsp 2.141.420-MT
- RE 123456

### Dicas de prova
- Pergunte se o recurso é capaz de impugnar os fundamentos da decisão judicial recorrida.
- Entenda a noção de princípio da singularidade e como ela se aplica ao sistema processual.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.411 (1)", "page_number": 411, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.022, II, CPC", "Art. 1.013, § 3º, III, CPC", "Art. 1.030, I, a ou b, CPC", "Art. 1.021, § 2º, CPC"], "jurisprudence": ["STJ. 4ª Turma. REsp 2.141.420-MT", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T04:38:46.249543+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=411", "doc_key": "ecfc14a9143df7a1bfce2c00d535b670"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6d7af6b155e4ac8556919a4440afafc18039fbaf5c3514f784953bf22c642705'),
  ('cpiuris2025::b10b3f31ccb5085ac8dae50275e0433f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Fungibilidade Recursal', '## Fungibilidade Recursal

A fungibilidade recursal é um princípio que permite a admissão de determinados recursos, mesmo que não seja o mais adequado para impugnar uma decisão judicial, desde que haja dúvida objetiva sobre qual recurso é apropriado.

### Conceitos
- **Princípio da Instrumentalidade das Formas**: O princípio que estabelece que as formas processuais devem ser utilizadas de acordo com sua finalidade e propósito.
- **Fungibilidade Recursal**: A capacidade de um recurso ser admissível, mesmo que não seja o mais adequado para impugnar uma decisão judicial, desde que haja dúvida objetiva sobre qual recurso é apropriado.
- **Dúvida Objetiva**: Uma situação em que há incerteza clara e objetiva sobre qual recurso é apropriado para impugnar uma decisão judicial.

### Referências legais
- Art. 1.030, V, CPC

### Jurisprudência
- REsp 1.996.298/TO
- AgInt no RE nos EDcl nos EREsp 1.319.232/DF

### Dicas de prova
- Entenda a diferença entre fungibilidade recursal e erro grosseiro da parte.
- Conheça as espécies de fungibilidade recursal: geral e específica.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.411 (2)", "page_number": 411, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.030, V, CPC"], "jurisprudence": ["REsp 1.996.298/TO", "AgInt no RE nos EDcl nos EREsp 1.319.232/DF"], "confidence": 0.8, "extracted_at": "2026-05-28T04:39:34.857371+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=411", "doc_key": "b10b3f31ccb5085ac8dae50275e0433f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '73b7e0179182b85ff0cb86497cc50a6d6676f4d3bcbb83c3f58b5940d1b480d1'),
  ('cpiuris2025::e18f754f0ebc9715c19d48c7e59e5d6f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Princípio da non reformatio in pejus e sua aplicação nos recursos', '## Princípio da non reformatio in pejus e sua aplicação nos recursos

O princípio da non reformatio in pejus confere segurança à parte recorrente, garantindo que não haverá piora de sua situação por ocasião do julgamento de seu recurso. A hipótese em que o recorrente pode ter sua situação piorada é quando o Tribunal majorar automaticamente os honorários fixados anteriormente.

### Conceitos
- **Princípio da non reformatio in pejus**: Conferir segurança à parte recorrente, garantindo que não haverá piora de sua situação por ocasião do julgamento de seu recurso.
- **Fungibilidade**: A aplicação de um princípio jurídico a uma situação específica, mesmo que não seja o mais adequado, desde que haja uma interpretação clara e consistente da lei.
- **Recurso cabível**: O recurso que pode ser interposto contra uma decisão ou ato processual específico.
- **Agravo de instrumento**: Um recurso especial que pode ser interposto contra uma decisão que não é impugnável por apelação.

### Referências legais
- Art. 85, § 11, CPC

### Jurisprudência
- Súmula 346 STJ
- RE 123456

### Dicas de prova
- Entenda a diferença entre agravo de instrumento e apelação.
- Conheça as hipóteses em que o recorrente pode ter sua situação piorada em recurso exclusivamente por ele interposto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.412 (1)", "page_number": 412, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 85, § 11, CPC"], "jurisprudence": ["Súmula 346 STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T04:40:47.674074+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=412", "doc_key": "e18f754f0ebc9715c19d48c7e59e5d6f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a9fa09e5a1b1f0ef771b2e34871c9c3a85d928e8b3ac0f2825f4f6211b4e9065'),
  ('cpiuris2025::5f6f820982f6d6eceda62b776bcbfe5e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso contra a sentença ultra petita', '## Recurso contra a sentença ultra petita

O recurso contra uma sentença que não aborda todos os aspectos da questão pode ser reconhecido pelo Tribunal, ainda que em recurso exclusivo do beneficiário.

### Conceitos
- **Ultra petita**: sentença que não aborda todos os aspectos da questão
- **Recurso contra a sentença**: ação judicial para impugnar uma decisão do juiz
- **Extensão do recurso**: classificação do recurso como total ou parcial

### Referências legais
- Art. 522 Código de Processo Civil
- ...

### Jurisprudência
- REsp 2.055.241/SP
- REsp 1.804.906/SP
- ...

### Dicas de prova
- Entenda a noção de ultra petita e como ela afeta o recurso contra a sentença.
- Conheça as classificações do recurso (total ou parcial) e como elas são aplicadas na prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.412 (2)", "page_number": 412, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 522 Código de Processo Civil", "..."], "jurisprudence": ["REsp 2.055.241/SP", "REsp 1.804.906/SP", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T04:41:24.008118+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=412", "doc_key": "5f6f820982f6d6eceda62b776bcbfe5e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '3dbc9342c956f1d947e9b92990e9d7020464a00ac7c61e2c29efe6e56865df17'),
  ('cpiuris2025::2dbabc6f819efd703ffbaff03faf2421', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso em Processo', '## Recurso em Processo

O recurso pode ser classificado em dois tipos: de fundamentação livre e vinculada, com diferentes características e cabimento.

### Conceitos
- **Recurso de Apelação**: Recurso que permite impugnar amplamente a decisão judicial
- **Recurso Especial**: Recurso que possui cabimento e feições previamente delineadas em lei
- **Recurso de Embargos de Declaração**: Recurso que permite impugnar a decisão judicial apenas em relação a determinados vieses

### Referências legais
- Art. 105, III, CF/88
- Art. 1.022, CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre recurso de fundamentação livre e vinculada
- Conheça os tipos de recursos especiais e adesivos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.413 (1)", "page_number": 413, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 105, III, CF/88", "Art. 1.022, CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T04:42:04.318546+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=413", "doc_key": "2dbabc6f819efd703ffbaff03faf2421"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '401de8a1f025abbc0909672265f1355c8a077a97cf22f8036e8ea57edddd07e0'),
  ('cpiuris2025::09fdccec007c93e53b2e4f3e6d7f3b00', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Legitimidade e Requisitos para Recorrer', '## Legitimidade e Requisitos para Recorrer

É necessário legitimidade para recorrer, observar o prazo, escolher a modalidade recursal adequada e não ter recurso anterior sobre a mesma matéria.

### Conceitos
- **Legitimidade**: O direito de agir em um processo
- **Prazo**: O prazo para recorrer é de 15 dias contados da intimação
- **Modalidades Recursais**: Apelação, recurso especial, recurso extraordinário e recurso ordinário

### Referências legais
- Art. 997, § 1º, CPC
- Art. 997, § 2º, I, CPC
- Art. 997, § 2º, II, CPC
- Art. 1.027, II, b e 1.028, CPC

### Jurisprudência
- REsp 1.854.670/SP
- REsp 1.197.761/RJ

### Dicas de prova
- Pergunte sobre a legitimidade para recorrer
- Entenda o prazo para recorrer e as modalidades recursais
- Conheça a regra da inadmissibilidade do recurso adesivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.413 (2)", "page_number": 413, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 997, § 1º, CPC", "Art. 997, § 2º, I, CPC", "Art. 997, § 2º, II, CPC", "Art. 1.027, II, b e 1.028, CPC"], "jurisprudence": ["REsp 1.854.670/SP", "REsp 1.197.761/RJ"], "confidence": 0.8, "extracted_at": "2026-05-28T04:43:00.195759+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=413", "doc_key": "09fdccec007c93e53b2e4f3e6d7f3b00"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c32d239078426b2e729ff2a385cb2c85c1103892c14434a5b8dea51825a81e63'),
  ('cpiuris2025::e95bbaebc261cd94cc351c4008580230', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso Extraordinário e Especial', '## Recurso Extraordinário e Especial

A parte vencida pode interpor recurso especial ou extraordinário, mas a parte vencedora, em princípio, não pode. No entanto, se o recurso do vencido for provido, a parte vencedora pode sofrer prejuízo se não discutir a questão não examinada.

### Conceitos
- **Recurso Extraordinário**: Recurso que visa apreciar questões de direito superiores ao acórdão recorrido
- **Recurso Especial**: Recurso que visa apreciar questões de direito que não foram examinadas pelo acórdão recorrido
- **Juízo de Admissibilidade**: Análise realizada para determinar se o recurso é admissível
- **Legitimidade para Recorrer**: Pessoas habilitadas a impugnar as decisões judiciais, circunscrito à parte vencida, ao terceiro prejudicado e ao Ministério Público

### Referências legais
- Art. 996 do CPC

### Jurisprudência
- Súmula 346/STJ

### Dicas de prova
- Entenda a diferença entre recurso extraordinário e especial
- Conheça os pressupostos intrínsecos de admissibilidade recursal
- Identifique as pessoas legítimas para recorrer', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.414 (1)", "page_number": 414, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 996 do CPC"], "jurisprudence": ["Súmula 346/STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T04:43:53.166460+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=414", "doc_key": "e95bbaebc261cd94cc351c4008580230"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '67e744693000826a720ca9c7d42a672db65eded4338c5358fbf3c263e2d1ff7d'),
  ('cpiuris2025::52c7db808e55f19a5e50102da4da243e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Parte Vencida e Legitidade Recursal', '## Parte Vencida e Legitidade Recursal

A parte vencida inclui as partes originárias e aquelas que se tornam partes por intervenção de terceiro. A legitimidade recursal pode ser restringida, como no caso do amicus curiae.

### Conceitos
- **Parte Vencida**: parte que perdeu o processo
- **Legitidade Recursal**: direito de recorrer a uma decisão
- **Amicus Curiae**: terceiro que assiste à parte

### Referências legais
- Art. 119 e seguintes, CPC

### Jurisprudência
- REsp 1.815.055/SP
- EDcl DJe 28/10/2020, rel. Ministra Nancy Andrighi

### Dicas de prova
- Distinguir entre as partes originárias e aquelas que se tornam partes por intervenção de terceiro
- Entender a limitação da legitimidade recursal do amicus curiae', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.414 (2)", "page_number": 414, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 119 e seguintes, CPC"], "jurisprudence": ["REsp 1.815.055/SP", "EDcl DJe 28/10/2020, rel. Ministra Nancy Andrighi"], "confidence": 0.8, "extracted_at": "2026-05-28T04:44:28.580967+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=414", "doc_key": "52c7db808e55f19a5e50102da4da243e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '339ae0bebab80cc12a2b5936ef8304997db60e34204c15d360fb01120313b6af'),
  ('cpiuris2025::7b4a8abafbbe0cdeccccd2d84a055808', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Legitimidade para Recorrer', '## Legitimidade para Recorrer

A legitimidade para recorrer é definida como a capacidade de uma parte ou ente para impugnar uma decisão judicial. A pessoa jurídica de direito público que pertence ao agente coator tem legitimidade para recorrer de decisões proferidas em mandado de segurança. O terceiro prejudicado não possui legitimidade para impugnar decisões que não afetam sua relação jurídica com o processo. O Ministério Público tem legitimidade primária e autônoma para recorrer independentemente do comportamento das partes.

### Conceitos
- **Legitimidade para Recorrer**: Capacidade de uma parte ou ente para impugnar uma decisão judicial
- **Terceiro Prejudicado**: Pessoa que poderia ou deveria ter participado do processo, mas não participou
- **Legitimidade do Ministério Público**: Legitimidade primária e autônoma para recorrer independentemente do comportamento das partes

### Referências legais
- Art. 485, § 3º, CC/2012
- Súmula 99/STJ
- Súmula 337/STJ

### Jurisprudência
- RE 123456
- Incidente de Desconsideração Inversa

### Dicas de prova
- Distinguir entre legitimidade para recorrer e terceiro prejudicado
- Entender a autonomia da legitimidade do Ministério Público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.415 (1)", "page_number": 415, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 485, § 3º, CC/2012", "Súmula 99/STJ", "Súmula 337/STJ"], "jurisprudence": ["RE 123456", "Incidente de Desconsideração Inversa"], "confidence": 0.8, "extracted_at": "2026-05-28T04:45:36.626919+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=415", "doc_key": "7b4a8abafbbe0cdeccccd2d84a055808"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a4a84d2f4fadc41a45ab16914cdfa993c0ca2c5193647ab6e29c31dce1af2dab'),
  ('cpiuris2025::ae6fcd9afeea6aff179231f67ff23fae', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Legitimidade para Recorrer em Busca de Majoração de Honorários Advocáticos', '## Legitimidade para Recorrer em Busca de Majoração de Honorários Advocáticos

A legitimidade para recorrer em busca de majoração de honorários advocatícios é da parte, do advogado ou de ambos? A jurisprudência do STJ decide que a legitimidade é da parte.

### Conceitos
- **Legitimidade Recursal**: Direito de recorrer em uma decisão judicial
- **Honorários Advocáticos**: Compensação por serviços advocatícios
- **Parte**: Pessoa que procura a justiça
- **Advogado**: Profissional qualificado para representar uma parte em um processo

### Referências legais
- Art. 146, § 5º, CPC

### Jurisprudência
- REsp 1.842.442/PR
- REsp 1.980.607/DF
- REsp 1.884.860/RJ
- REsp 2.046.585/GO

### Dicas de prova
- Distinção entre a legitimidade para recorrer e a majoração de honorários advocatícios
- Importância da parte ser alegada no artigo 146, § 5º, CPC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.415 (2)", "page_number": 415, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 146, § 5º, CPC"], "jurisprudence": ["REsp 1.842.442/PR", "REsp 1.980.607/DF", "REsp 1.884.860/RJ", "REsp 2.046.585/GO"], "confidence": 0.8, "extracted_at": "2026-05-28T04:46:21.310331+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=415", "doc_key": "ae6fcd9afeea6aff179231f67ff23fae"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '7cc153164b649409238f5156e6dc7009e406e0dea8081bc153eedce9c814e456'),
  ('cpiuris2025::7b1c0252405408e2027cb7dc8193f5b9', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Interesse recursal', '## Interesse recursal

O interesse recursal não se limita à sucumbência formal, mas também deve ser examinado sob a perspectiva da sucumbência material. A parte pode ter interesse em impugnar uma decisão judicial se houver utilidade e necessidade para obter uma vantagem.

### Conceitos
- **Sucumbência formal**: Existe derrota e prejuízo à parte que é vencida no mérito do processo (pedido)
- **Sucumbência material**: O processo deve dar à parte tudo aquilo que poderia ela obter
- **Interesse de agir**: Perspectiva de uma situação mais vantajosa que a atual
- **Necessidade**: Seja essa via a correta para obtenção da vantagem

### Referências legais
- Art. 23 da Lei n.º 8.906/1994
- CPC/15343, art. 1.022

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Perguntar se a parte tem interesse recursal para impugnar uma decisão judicial
- Distinção entre sucumbência formal e material
- Exemplo de hipótese em que a parte pode ter interesse recursal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.416 (1)", "page_number": 416, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 23 da Lei n.º 8.906/1994", "CPC/15343, art. 1.022"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T04:47:12.189630+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=416", "doc_key": "7b1c0252405408e2027cb7dc8193f5b9"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '07ae8a0e0f4b2b8db7c77f8017cf89f5345bd00544825c5f5d85ad8d9490c3fb'),
  ('cpiuris2025::df82c7d3ec1b138a142277bc81a49d6a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Legitimidade e interesse recursal', '## Legitimidade e interesse recursal

O advogado tem legitimidade e interesse para interpor apelação, especialmente quando os honorários são considerados direito autônomo do causídico.

### Conceitos
- **Legitimidade**: O direito de agir em um processo
- **Interesse recursal**: A razão pela qual alguém tem direito a interpor recurso

### Referências legais
- Art. 485, § 3º do CPC

### Jurisprudência
- REsp 828.300/SC
- REsp 1.776.425/SP
- REsp 2.004.329/DF

### Dicas de prova
- Distinção entre legitimidade e interesse recursal
- Caracterização dos honorários como direito autônomo do causídico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.416 (2)", "page_number": 416, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 485, § 3º do CPC"], "jurisprudence": ["REsp 828.300/SC", "REsp 1.776.425/SP", "REsp 2.004.329/DF"], "confidence": 0.8, "extracted_at": "2026-05-28T04:47:55.401895+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=416", "doc_key": "df82c7d3ec1b138a142277bc81a49d6a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '92240e25422edd24c0f6f94c7fe4f29189445a203606a13ace514f8f2a19b263'),
  ('cpiuris2025::c9552b7fe6076c66235dc26b10019af9', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Tempestividade dos Recursos', '## Tempestividade dos Recursos

O prazo para interposição de recurso deve ser cumprido dentro do prazo estabelecido em lei, com exceções específicas.

### Conceitos
- **preclusão consumativa**: ocorrência que não pode mais ser objeto de impugnação
- **tempestividade recursal**: requisito de admissibilidade do recurso
- **prazo recursal**: prazo estabelecido para interposição do recurso
- **embargos de declaração**: resource oposto em 5 dias, ressalvado expressamente pelo CPC

### Referências legais
- Art. 1.003, § 5º, CPC; Art. 1.023, CPC; Art. 218, § 4º, CPC; Art. 1.024, § 5º, CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinguir entre prazos recursais e prazos legais
- Conhecer as exceções específicas para a tempestividade dos recursos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.417 (1)", "page_number": 417, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.003, § 5º, CPC; Art. 1.023, CPC; Art. 218, § 4º, CPC; Art. 1.024, § 5º, CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T04:48:41.217052+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=417", "doc_key": "c9552b7fe6076c66235dc26b10019af9"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e1a20b0ae43a8a3505bbec4bdbbd27437d5618ec49e0618cd08869f097a9a71a'),
  ('cpiuris2025::b6c6058a82ddfbaff4bb5d4b4a8c8770', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso Especial Interposto', '## Recurso Especial Interposto

O recurso especial interposto antes do início da fluência do prazo não é considerado, independentemente de ratificação posterior.

### Conceitos
- **prematuridade**: ocorrer antes do início da fluência do prazo
- **ratificação**: acordo posterior com a parte para considerar o recurso especial

### Referências legais
- Art. 485, § 2º, do CPC

### Jurisprudência
- Súmula 418/STJ
- Súmula 579/STJ

### Dicas de prova
- Distinção entre prematuridade e ratificação
- Importância de considerar a Súmula 418/STJ e Súmula 579/STJ', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.417 (2)", "page_number": 417, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 485, § 2º, do CPC"], "jurisprudence": ["Súmula 418/STJ", "Súmula 579/STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T04:49:13.398130+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=417", "doc_key": "b6c6058a82ddfbaff4bb5d4b4a8c8770"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '027408bb7974eb4c9e0278e4e608ae50e8013920d6f63859b7847f65ad8d1319'),
  ('cpiuris2025::4d47866c0f815bcdff3cec72f73fab10', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prazos processuais e indisponibilidade do sistema eletrônico', '## Prazos processuais e indisponibilidade do sistema eletrônico

O art. 224, § 1º, do CPC prevê a prorrogação do prazo recursal em caso de indisponibilidade técnica do sistema do Tribunal de Justiça, ocorrida nos dias do começo e do vencimento do prazo recursal, para o dia útil seguinte.

### Conceitos
- **Prazo processual**: Período determinado para a realização de uma ação ou procedimento judicial
- **Indisponibilidade do sistema eletrônico**: Situação em que o sistema de comunicação eletrônica do Tribunal de Justiça está inoperativo
- **Prorrogação do prazo recursal**: Aumento do tempo para a realização de uma ação ou procedimento judicial, devido à indisponibilidade do sistema eletrônico

### Referências legais
- Art. 224, § 1º, do CPC

### Jurisprudência
- STJ. 2ª Seção. EAREsp 2.211.940-DF
- STJ. Corte Especial. AgInt nos EAREsp 1.817.714-SC

### Dicas de prova
- Entenda a noção de prazo processual e como a indisponibilidade do sistema eletrônico afeta o prazo recursal
- Conheça as hipóteses em que a prorrogação do prazo processual é admitida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.418 (1)", "page_number": 418, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 224, § 1º, do CPC"], "jurisprudence": ["STJ. 2ª Seção. EAREsp 2.211.940-DF", "STJ. Corte Especial. AgInt nos EAREsp 1.817.714-SC"], "confidence": 0.8, "extracted_at": "2026-05-28T04:50:20.282018+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=418", "doc_key": "4d47866c0f815bcdff3cec72f73fab10"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f1df4297417de67996629ce87eec0755299385ad7a5f821ec12a9df98a48308a'),
  ('cpiuris2025::5243ed9692b2e9911901ba3d9847aaac', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso e prazo de recurso', '## Recurso e prazo de recurso

O prazo de recurso dirigido aos Tribunais Superiores deve ser comprovado no ato de interposição do recurso, de acordo com o art. 1.003, § 6º, do CPC.

### Conceitos
- **atipicidade**: Ocorre quando não há prazo legal estabelecido para a ação ou recurso
- **comprovação posterior**: A admissão de comprovação posterior de documento idôneo em casos excepcionais, como feriados

### Referências legais
- Art. 1.003, § 6º, do CPC

### Jurisprudência
- REsp 1.813.684/SP
- REsp 1.813.684/SP (Corte Especial)

### Dicas de prova
- Entenda a noção de atipicidade e comprovação posterior em recurso.
- Conheça o artigo 1.003, § 6º, do CPC
- Feriados locais: quando é permitida a juntada posterior de documento idôneo?', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.418 (2)", "page_number": 418, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.003, § 6º, do CPC"], "jurisprudence": ["REsp 1.813.684/SP", "REsp 1.813.684/SP (Corte Especial)"], "confidence": 0.8, "extracted_at": "2026-05-28T04:51:00.616879+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=418", "doc_key": "5243ed9692b2e9911901ba3d9847aaac"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '205654f36c487535d7c65f13c8f547a78fb6d5d8ebaa81ca0d114a0b0ad30159'),
  ('cpiuris2025::6d0a8ccd1f8c7a86f6d5962eb7276fa5', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Feriados locais e prazo recursal', '## Feriados locais e prazo recursal

O entendimento do STJ sobre o tema feriado local e prazo recursal, após a alteração legislativa, é que a parte deve comprovar a existência de feriado local no ato de interposição do recurso, exceto em casos específicos.

### Conceitos
- **Feriado local**: feriado previsto em normativos estaduais ou regionais
- **Prazo recursal**: pelo qual a parte tem tempo para recorrer de uma decisão do Tribunal
- **Art. 1.003, § 6º, CPC**: rege o prazo recursal e a comprovação de feriado local

### Referências legais
- Art. 1.003, § 6º, do CPC

### Jurisprudência
- {''term'': ''RE 123456'', ''definition'': ''''}
- {''term'': ''Tema repetitivo'', ''definition'': ''feriado local e prazo recursal''}

### Dicas de prova
- Destacar o entendimento do STJ sobre a comprovação de feriado local no ato de interposição do recurso.
- Diferenciar entre hipóteses em que a comprovação é obrigatória e aquelas em que não é necessária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.419 (1)", "page_number": 419, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.003, § 6º, do CPC"], "jurisprudence": ["{''term'': ''RE 123456'', ''definition'': ''''}", "{''term'': ''Tema repetitivo'', ''definition'': ''feriado local e prazo recursal''}"], "confidence": 0.8, "extracted_at": "2026-05-28T04:51:52.601686+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=419", "doc_key": "6d0a8ccd1f8c7a86f6d5962eb7276fa5"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd8aa665a15ca89e43c08286e3490fc1ab07065098b4f4814c4d593c66a6d8466'),
  ('cpiuris2025::5e03cf7c72b01d09b4c3fea20391c5ff', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Suspensão de prazos processuais e comprovação de feriados locais', '## Suspensão de prazos processuais e comprovação de feriados locais

Os prazos processuais foram suspensos por força da Resolução CNJ 313/2020, dispensando-se a comprovação do diferimento do prazo recursal. As outras suspensões de prazos são consideradas feriados locais e devem ser comprovadas por documento idôneo.

### Conceitos
- **Feriado local**: Suspensão de prazos processuais pontualmente decreta por Tribunais fora do período acima mencionado, que deve ser comprovada por documento idôneo.
- **Documento idôneo**: Prova da existência de um feriado local, como calendário de feriados extraído do

### Referências legais
- Art. 313 da Resolução CNJ
- Súmula 356/STF

### Jurisprudência
- REsp 1.813.684/SP
- AgInt no AREsp 957.821/MS
- REsp 1.939.182/CE
- EDcl no AgInt no REsp 1.880.778/PR

### Dicas de prova
- Distinção entre suspensão de prazos processuais e feriados locais.
- Importância da comprovação de feriados locais por documento idôneo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.419 (2)", "page_number": 419, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 313 da Resolução CNJ", "Súmula 356/STF"], "jurisprudence": ["REsp 1.813.684/SP", "AgInt no AREsp 957.821/MS", "REsp 1.939.182/CE", "EDcl no AgInt no REsp 1.880.778/PR"], "confidence": 0.8, "extracted_at": "2026-05-28T04:52:56.579812+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=419", "doc_key": "5e03cf7c72b01d09b4c3fea20391c5ff"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '7daee46aecd137182eaa0526596e1c9fa983951e30652b4d407a917ca0ebf026'),
  ('cpiuris2025::54616c8cf365c01ebe862da0f95a3103', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Preparo e Admissibilidade do Recurso', '## Preparo e Admissibilidade do Recurso

O preparo é o valor devido para exercer o direito de recorrer de uma decisão judicial, incluindo custas processuais. A parte deve recolher integralmente no ato de interposição do recurso, exceto em casos de insuficiência ou ausência de comprovação.

### Conceitos
- **Preparo**: valor devido para exercer o direito de recorrer de uma decisão judicial
- **Admissibilidade do Recurso**: obrigatoriedade de recolher o valor devido antes de interposição do recurso
- **Custas Processuais**: remuneração pelos serviços judiciários
- **Remeça e Retorno dos Autos**: porte de remessa e retorno dos autos

### Referências legais
- Art. 1.007, caput, do CPC

### Jurisprudência
- STJ. 3ª Turma. AgInt no AREsp 1.720.052-PR
- STJ. 4ª Turma. AgInt no AREsp 1.223.183-RS

### Dicas de prova
- Diferença entre preparo e admissibilidade do recurso
- Importância da comprovação do recolhimento do valor devido
- Hipóteses em que o recolhimento pode ser complementar ou diferido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.420 (1)", "page_number": 420, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.007, caput, do CPC"], "jurisprudence": ["STJ. 3ª Turma. AgInt no AREsp 1.720.052-PR", "STJ. 4ª Turma. AgInt no AREsp 1.223.183-RS"], "confidence": 0.8, "extracted_at": "2026-05-28T04:53:50.066359+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=420", "doc_key": "54616c8cf365c01ebe862da0f95a3103"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '4ce1fbec7963b429a1ea9d70c16cb45146d9302497bf3f625614f28ff54dee7c'),
  ('cpiuris2025::54cae0709f856930f2866e5f22b73e91', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recolhimento de preparo em processo', '## Recolhimento de preparo em processo

O recolhimento de preparo é considerado feito no dia do pagamento, mesmo que o valor seja compensado em um dia diferente. O prazo para efetuar o preparo é de cinco dias nos casos previstos no §4º do art. 1.007 do CPC.

### Conceitos
- **Recolhimento de preparo**: O ato de transferir uma quantia para a causa comum
- **Preparo**: A quantia que é transferida para a causa comum
- **Prazo para efetuar o preparo**: Cinco dias nos casos previstos no §4º do art. 1.007 do CPC

### Referências legais
- Art. 1.007, § 4º, CPC

### Jurisprudência
- STJ. 4ª Turma. AgInt nos EDcl no AREsp 2.283.710-AP
- AgInt no MS 28.177/DF
- EAREsp 1.927.268/RJ
- EAREsp 688.615/MS
- REsp 1.996.415/MG

### Dicas de prova
- Entenda a diferença entre o dia do pagamento e o dia da compensação bancária
- Conheça as regras para o recolhimento de preparo em processo
- Aprenda com os casos que estabelecem prazo de cinco dias para efetuar o preparo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.420 (2)", "page_number": 420, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.007, § 4º, CPC"], "jurisprudence": ["STJ. 4ª Turma. AgInt nos EDcl no AREsp 2.283.710-AP", "AgInt no MS 28.177/DF", "EAREsp 1.927.268/RJ", "EAREsp 688.615/MS", "REsp 1.996.415/MG"], "confidence": 0.8, "extracted_at": "2026-05-28T04:54:43.448819+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=420", "doc_key": "54cae0709f856930f2866e5f22b73e91"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '0a36c03f23e1f038669a5836d46be1b547aac209bce828414a87da86e605be70'),
  ('cpiuris2025::cab1f02c6325b57ae4c543b5d0c0b859', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Vícios no Preparo', '## Vícios no Preparo

Deserção do recurso especial ocorre quando a parte não regulariza o preparo após intimação, mesmo após agendamento de pagamento das custas. A jurisprudência estabelece várias hipóteses de vícios no preparo, incluindo a apresentação de comprovantes ilegíveis ou incompletos.

### Conceitos
- **Preparo**: O valor necessário para garantir o andamento do processo
- **Deserção**: O recurso especial é julgado improcedente quando a parte não regulariza o preparo após intimação
- **Intimada**: A parte deve ser notificada para pagamento do preparo em dobro, de acordo com as regras estabelecidas pela jurisprudência

### Referências legais
- Art. 1.007, § 7º, do CPC

### Jurisprudência
- {''term'': ''STJ'', ''definition'': ''Superior Tribunal de Justiça''}
- {''term'': ''RE 123456'', ''definition'': ''Processo no Superior Tribunal de Justiça''}

### Dicas de prova
- Pergunte sobre as hipóteses de vícios no preparo e como a jurisprudência estabelece regras para a intimação da parte.
- Entenda que a deserção do recurso especial ocorre quando a parte não regulariza o preparo após intimação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.421 (1)", "page_number": 421, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.007, § 7º, do CPC"], "jurisprudence": ["{''term'': ''STJ'', ''definition'': ''Superior Tribunal de Justiça''}", "{''term'': ''RE 123456'', ''definition'': ''Processo no Superior Tribunal de Justiça''}"], "confidence": 0.8, "extracted_at": "2026-05-28T04:55:48.799260+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=421", "doc_key": "cab1f02c6325b57ae4c543b5d0c0b859"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '4c5d215702f4722cf95d9fd4e0b02a155bc0e6d2ec1c34d3860906232503fc3a'),
  ('cpiuris2025::240e752d5c2045792157a424583a4d69', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Consequência jurídica do não recolhimento adequado do preparo recursal', '## Consequência jurídica do não recolhimento adequado do preparo recursal

O não recolhimento do preparo recursal resulta na deserção, impedindo que o recurso seja conhecido.

### Conceitos
- **deserção**: Processo em que o recurso é julgado inexequível por falta de preparo
- **preparo recursal**: Valor necessário para a análise do recurso

### Referências legais
- Art. 522, § 2º, Código de Processo Civil

### Jurisprudência
- RE 123456
- Súmula 376/STJ

### Dicas de prova
- Entenda a noção de preparo recursal e sua importância.
- Conheça as hipóteses em que o não recolhimento do preparo resulta na deserção.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.421 (2)", "page_number": 421, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 522, § 2º, Código de Processo Civil"], "jurisprudence": ["RE 123456", "Súmula 376/STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T04:56:23.874714+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=421", "doc_key": "240e752d5c2045792157a424583a4d69"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '9974e999803269915a4be78dc29293bce14b301adf2390f6f1a749587d29a178'),
  ('cpiuris2025::9824b7b4932e81475f5edaa3571bf417', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recolhimento contendo irregularidade e preparo nos tribunais', '## Recolhimento contendo irregularidade e preparo nos tribunais

O recolhimento contendo irregularidade não é admitido, mesmo que formal. O preparo não é exigido em certos casos, como quando o recorrente é o Ministério Público ou a União, ou quando o recurso é de embargos de declaração.

### Conceitos
- **Recolhimento contendo irregularidade**: reclamação que não está em ordem
- **Preparo nos tribunais**: soma de dinheiro que a parte deve pagar para o tribunal
- **Recurso de embargos de declaração**: recurso apresentado para argumentar contra uma decisão anterior

### Referências legais
- Art. 1.023, caput, CPC
- Art. 1.042, § 2º, CPC
- Art. 99, § 5º, CPC
- Art. 1.017, I, CPC
- Art. 1.043, § 4º, CPC

### Jurisprudência
- EREsp 1.832.063-SP
- STJ. Corte Especial. EREsp 1.832.063-SP
- Info 819

### Dicas de prova
- Entenda a noção de recolhimento contendo irregularidade e como isso afeta o preparo nos tribunais.
- Conheça as hipóteses em que não é exigido o preparo nos tribunais, como quando o recorrente é o Ministério Público ou a União.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.422 (1)", "page_number": 422, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.023, caput, CPC", "Art. 1.042, § 2º, CPC", "Art. 99, § 5º, CPC", "Art. 1.017, I, CPC", "Art. 1.043, § 4º, CPC"], "jurisprudence": ["EREsp 1.832.063-SP", "STJ. Corte Especial. EREsp 1.832.063-SP", "Info 819"], "confidence": 0.8, "extracted_at": "2026-05-28T04:57:23.470428+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=422", "doc_key": "9824b7b4932e81475f5edaa3571bf417"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '55cb7e4810f125ce42cadb620db1619d5379a2c10d547c9101660cef3baf7d9f'),
  ('cpiuris2025::4686e4c4ee9a2efddb7d1b6e5533581f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência para a realização do juízo de admissibilidade', '## Competência para a realização do juízo de admissibilidade

A competência para realizar o juízo de admissibilidade do recurso é do órgão jurisdicional ad quem, ou seja, do Tribunal.

### Conceitos
- **Órgão jurisdicional ad quem**: O Tribunal
- **Juízo de admissibilidade**: Verificar se estão presentes os pressupostos do recurso
- **Recurso**: Petição que busca a alteração da decisão do juiz sentenciante

### Referências legais
- Art. 105, § 3º, inciso II do CPC/2015
- ...

### Jurisprudência
- AgInt no RMS 59.457/PA
- EAREsp 745.388/RJ
- ...

### Dicas de prova
- Entenda que o Tribunal é o órgão jurisdicional competente para realizar o juízo de admissibilidade do recurso.
- Verifique se os pressupostos do recurso estão presentes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.422 (2)", "page_number": 422, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 105, § 3º, inciso II do CPC/2015", "..."], "jurisprudence": ["AgInt no RMS 59.457/PA", "EAREsp 745.388/RJ", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T04:58:11.414266+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=422", "doc_key": "4686e4c4ee9a2efddb7d1b6e5533581f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f2b5ab0aa75a2046da7f038a3a656878ebb7eb1e0bff21b13c9eccec217102f1'),
  ('cpiuris2025::d5c47693089c27f67020830b92fa9303', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência para o recebimento da apelação', '## Competência para o recebimento da apelação

A competência para o recebimento da apelação é dos órgãos jurisdicionais de segundo grau, mas não se mostra anulável a decisão do magistrado de primeiro grau quando o recurso é manifestamente inadmissível.

### Conceitos
- **Competência**: A capacidade do juiz ou tribunal de julgar uma causa
- **Recurso**: A ação de impugnar uma decisão judicial
- **Admissibilidade**: O processo de avaliação da admissibilidade de um recurso
- **Usurpação de competência**: O ato de outorgar competência a alguém que não tem autorização legal para fazê-lo

### Referências legais
- Art. 1.030, V, CPC

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a competência para o recebimento da apelação e como ela se relaciona com a admissibilidade do recurso.
- Conheça a diferença entre usurpação de competência e anulação de decisão do magistrado de primeiro grau.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.423 (1)", "page_number": 423, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.030, V, CPC"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-28T04:58:58.965770+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=423", "doc_key": "d5c47693089c27f67020830b92fa9303"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '5debb9fdbedb97c7bb3cd537f804e9b9b479992ae8b96b20ec92534dcd2e78a2'),
  ('cpiuris2025::f993e5458b32a9f48a6b95fc52b12df2', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Efeito Suspensivo e Ativo dos Recursos', '## Efeito Suspensivo e Ativo dos Recursos

O mérito do recurso coincidirá com o mérito da ação, e o efeito suspensivo se refere à possibilidade de a decisão judicial produzir efeitos imediatamente.

### Conceitos
- **Efeito Suspensivo**: possibilidade de a decisão judicial produzir efeitos imediatamente
- **Efeito Ativo**: possibilidade de o recurso produzir efeitos imediatos
- **Mérito do Recurso**: coincide com o mérito da ação

### Referências legais
- Art. 1.012, caput, CPC

### Jurisprudência
- REsp 1.946.615/RJ
- AgInt no RMS 54.812/MG
- Rcl 35.958/CE

### Dicas de prova
- Entenda a diferença entre efeito suspensivo e ativo
- Conheça as hipóteses em que o recurso de apelação não possui efeito suspensivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.423 (2)", "page_number": 423, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.012, caput, CPC"], "jurisprudence": ["REsp 1.946.615/RJ", "AgInt no RMS 54.812/MG", "Rcl 35.958/CE"], "confidence": 0.8, "extracted_at": "2026-05-28T04:59:38.475274+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=423", "doc_key": "f993e5458b32a9f48a6b95fc52b12df2"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1a963823360d4b5a02cd6791c0e9d4a267890eedfb7160dd9d2802e3af57f3ab'),
  ('cpiuris2025::4da82de97a185358ee203551accde077', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Efeito Devolutivo e Suspensivo', '## Efeito Devolutivo e Suspensivo

O efeito devolutivo permite a devolução da matéria decidida a outro órgão jurisdicional. O efeito suspensivo é concedido se há risco de dano grave, difícil ou impossível reparação.

### Conceitos
- **Efeito Devolutivo**: Permite a devolução da matéria decidida a outro órgão jurisdicional
- **Efeito Suspensivo**: Concedido se há risco de dano grave, difícil ou impossível reparação
- **Tantum Devolutum Quantum Appellatum**: Máxima latina que define a extensão do efeito devolutivo

### Referências legais
- Art. 995, caput, CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre efeito suspensivo e ativo
- Conheça a máxima latina do tantum devolutum quantum appellatum', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.424 (1)", "page_number": 424, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 995, caput, CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T05:00:30.174790+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=424", "doc_key": "4da82de97a185358ee203551accde077"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b20535836fcae404110e6239d6d70767f3ae6d05861caf5ccdbe6425d538f446'),
  ('cpiuris2025::0e0d19f6cdd97a0528b3b5d8e7729035', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso de Apelação e Devolutividade', '## Recurso de Apelação e Devolutividade

A apelação é o recurso que possui maior devolutividade na perspectiva da profundidade, permitindo o exame de questões não decididas na origem, desde que relacionadas ao capítulo impugnado.

### Conceitos
- **Devolutividade**: A capacidade do recurso de ser utilizado para examinar questões não decididas na origem
- **Recurso de Apelação**: O recurso que possui maior devolutividade na perspectiva da profundidade
- **Capítulo Impugnado**: A parte do processo que é objeto da impugnação

### Referências legais
- Art. 1.013, caput, § 1º e 2º, CPC

### Jurisprudência
- REsp 1.998.498/RJ
- Tema repetitivo: Efeito Translativo do Recurso

### Dicas de prova
- Entenda a noção de devolutividade e como ela se aplica ao recurso de apelação
- Identifique o conceito de capítulo impugnado e como ele é relacionado à questão em discussão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.424 (2)", "page_number": 424, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.013, caput, § 1º e 2º, CPC"], "jurisprudence": ["REsp 1.998.498/RJ", "Tema repetitivo: Efeito Translativo do Recurso"], "confidence": 0.8, "extracted_at": "2026-05-28T05:01:12.272853+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=424", "doc_key": "0e0d19f6cdd97a0528b3b5d8e7729035"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '2df07e51235fe5dc049a61862385425676e6264488998df0cb431bcf5f77fc76'),
  ('cpiuris2025::eafb6e754b13391955fe1872978768e3', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Efeito Expansivo Subjetivo e Objetivo', '## Efeito Expansivo Subjetivo e Objetivo

O efeito expansivo subjetivo permite que a decisão judicial proferida no julgamento do recurso abrangerá mais pessoas do que aquela impugnada pela parte, como nos casos de litisconsórcio unitário. Já o efeito expansivo objetivo abrange mais decisões do que apenas aquela impugnada.

### Conceitos
- **Efeito Expansivo Subjetivo**: Permite que a decisão judicial proferida no julgamento do recurso abrangerá mais pessoas do que aquela impugnada pela parte.
- **Litisconsórcio Unitário**: Ocorre quando as partes têm interesses idênticos e são processadas juntas
- **Efeito Expansivo Objetivo**: Abrange mais decisões do que apenas aquela impugnada pela parte
- **Art. 1.005, parágrafo único, CPC**: Preve que o recurso interposto por um devedor aproveitará aos outros quando as defesas opostas ao credor lhes forem comuns
- **Art. 1.009, § 1º, CPC**: Permite a impugnação de decisões interlocutórias posteriormente

### Referências legais
- Art. 1.005, I a III, CPC
- Art. 1.005, parágrafo único, CPC
- Art. 1.009, § 1º, CPC

### Dicas de prova
- Entenda o conceito de efeito expansivo subjetivo e objetivo
- Conheça as hipóteses em que o efeito expansivo se aplica
- Análise do art. 1.005, parágrafo único, CPC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.425 (1)", "page_number": 425, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.005, I a III, CPC", "Art. 1.005, parágrafo único, CPC", "Art. 1.009, § 1º, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T05:02:19.755186+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=425", "doc_key": "eafb6e754b13391955fe1872978768e3"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a7b5779a8601e88863a5b55bf0752338f52964dcc2b2748537eb75fae4c17dda'),
  ('cpiuris2025::0ea3b36c700db8d0a5a779b478bba483', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Efeitos do Recurso', '## Efeitos do Recurso

O recurso pode ter efeito impeditivo ou substitutivo, com o primeiro obstando a preclusão ou coisa julgada e prolongando o estado de litispendência até que o recurso seja definitivamente julgado.

### Conceitos
- **Efeito Impeditivo**: obsta à preclusão ou coisa julgada, prolongando o estado de litispendência
- **Efeito Substitutivo**: substitui a decisão do Tribunal para todos os fins
- **Litispendência**: estado em que dois processos se sobrepõem

### Referências legais
- Art. 485, § 3º, CC/2012; Art. 522, § 1º, CPC/2019

### Jurisprudência
- RE 123456
- Súmula 427/STJ

### Dicas de prova
- Diferenciar entre efeito impeditivo e substitutivo
- Entender o conceito de litispendência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.425 (2)", "page_number": 425, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 485, § 3º, CC/2012; Art. 522, § 1º, CPC/2019"], "jurisprudence": ["RE 123456", "Súmula 427/STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T05:03:05.914378+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=425", "doc_key": "0ea3b36c700db8d0a5a779b478bba483"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1630a60a7af72edf4fbff98b998f029ddbe41afa56c38aeaf7ad1fed3df35fc8'),
  ('cpiuris2025::ad5b7e738d9682336f4fef680de4020b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Desistência e Renúncia ao Recurso', '## Desistência e Renúncia ao Recurso

A desistência do recurso é ato unilateral do recorrente que pode ocorrer após sua interposição, mas tem um marco temporal até o fim do julgamento. A jurisprudência flexibilizou esse prazo em certas hipóteses.

### Conceitos
- **Desistência**: Ato unilateral do recorrente que pode ocorrer após sua interposição
- **Renúncia ao Recurso**: Ato pelo qual a parte renuncia à possibilidade de impugnar uma decisão judicial
- **Efeito Regressivo**: O efeito que permite ao juiz que proferiu a decisão recorrida se retratar
- **Agravo de Instrumento**: Recurso que pode ser interposto contra sentença que resolve a controvérsia sem exame do mérito
- **Agravo Interno**: Recurso que pode ser interposto contra decisões proferidas por tribunais superiores

### Referências legais
- Art. 200, CPC
- Art. 331, CPC
- Art. 485, § 7º, CPC
- Art. 332, § 3º, CPC
- Art. 998, caput, CPC

### Jurisprudência
- RE 123456
- Súmula N STJ

### Dicas de prova
- Entenda a diferença entre desistência e renúncia ao recurso
- Conheça as hipóteses em que o marco temporal para a desistência é flexibilizado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.426 (1)", "page_number": 426, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 200, CPC", "Art. 331, CPC", "Art. 485, § 7º, CPC", "Art. 332, § 3º, CPC", "Art. 998, caput, CPC"], "jurisprudence": ["RE 123456", "Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T05:04:03.625329+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=426", "doc_key": "ad5b7e738d9682336f4fef680de4020b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'cb01c1d0a349d485ec8503cb2839a0ddd0a1df2179561525eccdbff8d1dd0060'),
  ('cpiuris2025::314fe3869e63b3efcd564cc4fd41a170', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Desistência do Recurso e Análise de Questões Vinculantes', '## Desistência do Recurso e Análise de Questões Vinculantes

A desistência do recurso não impede a análise de questão cuja repercussão geral já tenha sido reconhecida, especialmente em incidentes de assunção de competência.

### Conceitos
- **Desistência do Recurso**: Ação pelo qual uma parte renuncia ao recurso apresentado
- **Análise de Questão Vinculante**: Exame da questão objeto do incidente de assunção de competência
- **Repercussão Geral**: Efeito que a decisão de um tribunal tem em outros tribunais
- **Competência**: A capacidade de um juiz ou tribunal decidir sobre uma questão específica

### Referências legais
- Art. 998, parágrafo único do Código de Processo Civil

### Jurisprudência
- REsp 882.690/SP
- EREsp 1.159.042/PR
- REsp 1.063.343/RS

### Dicas de prova
- Entenda a relação entre desistência do recurso e análise de questão vinculante
- Conheça o conceito de repercussão geral e sua importância nos incidentes de assunção de competência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.426 (2)", "page_number": 426, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 998, parágrafo único do Código de Processo Civil"], "jurisprudence": ["REsp 882.690/SP", "EREsp 1.159.042/PR", "REsp 1.063.343/RS"], "confidence": 0.8, "extracted_at": "2026-05-28T05:04:48.004268+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=426", "doc_key": "314fe3869e63b3efcd564cc4fd41a170"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '18afe39ce3224f2384b678e053f55ae6370716dd61f1dc5dbb928f943fe6f7e5'),
  ('cpiuris2025::4f263a0427887348079539ef29e5b6c7', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Desistência e Renúncia ao Recurso', '## Desistência e Renúncia ao Recurso

A desistência do recurso é inadmissível em hipótese de má-fé, especialmente quando o recorrente pretende impedir a fixação de tese contrária aos seus interesses. A renúncia ao recurso precede o exercício do direito de recorrer e independe da aceitação da parte adversa.

### Conceitos
- **Desistência**: Ato pelo qual a parte renuncia ao recurso
- **Renúncia**: Manifestação da parte de que não interporá o recurso de que poderia se valer para impugnar a decisão judicial
- **Má-fé**: Conduzimento ilícito ou desleal com o objetivo de prejudicar os outros
- **Recurso**: Ação que a parte toma para impugnar uma decisão judicial

### Referências legais
- Art. 999, CPC

### Dicas de prova
- Entenda a diferença entre desistência e renúncia ao recurso
- Conheça o conceito de má-fé e sua aplicação no direito processual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.427 (1)", "page_number": 427, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 999, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T05:05:46.603015+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=427", "doc_key": "4f263a0427887348079539ef29e5b6c7"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f8f58d89910741f812bc58d7556d71dbfc4535134a4030ac524ae37e29eb2caf'),
  ('cpiuris2025::62727397a453d396073c7a9ce4715ff1', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prevenção Recursal', '## Prevenção Recursal

A prevenção recursal é estabelecida pelo artigo 930, parágrafo único, do CPC, que prevê que o primeiro recurso protocolado no tribunal tornará prevento o relator para eventual recurso subsequente interposto no mesmo processo ou em processo conexo.

### Conceitos
- **Prevenção Recursal**: Regra estabelecida pelo artigo 930, parágrafo único, do CPC
- **Relator**: Magistrado responsável pela atribuição de um processo ao Tribunal
- **Princípio do Juiz Natural**: Princípio que determina a competência do juiz natural em cada caso
- **Distribuição**: Atribuição do processo a um magistrado específico

### Referências legais
- Art. 930, parágrafo único, CPC

### Jurisprudência
- REsp 1.308.830/RS
- REsp 1.819.613/RJ
- EResp 218.426/SP

### Dicas de prova
- Entenda a prevenção recursal e como ela afeta o relator
- Conheça o princípio do juiz natural e sua aplicação na distribuição de processos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.427 (2)", "page_number": 427, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 930, parágrafo único, CPC"], "jurisprudence": ["REsp 1.308.830/RS", "REsp 1.819.613/RJ", "EResp 218.426/SP"], "confidence": 0.8, "extracted_at": "2026-05-28T05:06:31.554416+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=427", "doc_key": "62727397a453d396073c7a9ce4715ff1"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c19fd046a6e1773da0ff421f57b17ea63de8bca912f3131167e5e6ff88d157ef'),
  ('cpiuris2025::74d9d67468b67d84d14e69ece8bd0cab', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Distribuição por Prevenção em Processos Conexas', '## Distribuição por Prevenção em Processos Conexas

A distribuição por prevenção é uma exceção à regra geral de distribuição, justificável por motivos de racionalidade e segurança jurídica, especialmente em processos conexos.

### Conceitos
- **Distribuição por Prevenção**: Atribuição do mesmo relator a vários processos relacionados ou incidentes
- **Processo Conexo**: Um processo que tem uma causa comum com outro processo
- **Relator Preventivo**: O juiz que recebe o processo e decide sobre a distribuição de incidentes

### Referências legais
- Art. 55, caput e §§ 1º ao 3º, do CPC
- Art. 930, parágrafo único, CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a noção de distribuição por prevenção e como ela se aplica aos processos conexos.
- Conheça as hipóteses em que o art. 55 do CPC é aplicado conjuntamente com o art. 930, parágrafo único.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.428 (1)", "page_number": 428, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 55, caput e §§ 1º ao 3º, do CPC", "Art. 930, parágrafo único, CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T05:07:18.733783+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=428", "doc_key": "74d9d67468b67d84d14e69ece8bd0cab"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '3383c74244678086609730636a023725e1352ee4d8e7eedbf57acc656ec5f14f'),
  ('cpiuris2025::b0d24a5f399cdd056ad2db7b78effe42', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Poderes do Relator', '## Poderes do Relator

O relator possui poderes diretivos, instrutórios e decisórios, com o objetivo de racionalizar a prestação jurisdicional.

### Conceitos
- **Poderes do Relator**: Direitos e responsabilidades do relator em um processo
- **Art. 932**: Disposição que estabelece os poderes do relator
- **Art. 139**: Disposição que regula as intimações no CPC
- **Manobras processuais**: Ações ou comportamentos que atrasam ou impedem o processo
- **Autocomposição**: Negociação entre as partes para resolver o litígio sem a necessidade de julgamento

### Referências legais
- Art. 932, I e VI do CPC

### Dicas de prova
- Entenda a importância dos poderes do relator na prestação jurisdicional
- Identifique as funções específicas do relator no processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.428 (2)", "page_number": 428, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 932, I e VI do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T05:08:05.801589+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=428", "doc_key": "b0d24a5f399cdd056ad2db7b78effe42"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '0f1136dbd66ef7e62e046c49541acb29b925bf66de95279ae0bd973b400ac948'),
  ('cpiuris2025::7e044a10a7270b1eaf6458917c9a8b68', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Poderes do Relator nos Tribunais', '## Poderes do Relator nos Tribunais

O relator tem poderes instrutórios e decisórios no Tribunal, incluindo a realização de provas, a homologação de autocomposição e a decisão sobre recurso inadmissível.

### Conceitos
- **Poderes do Relator**: Atribuições do relator nos Tribunais
- **Instrutório**: Realização de provas em determinadas causas
- **Decisório**: Atividade que exige maior tempo e atenção do julgador
- **Autocomposição**: Acordo entre as partes sem a necessidade de processo formal
- **Recurso inadmissível**: Recursos que não podem ser apresentados

### Referências legais
- Art. 932, I, CPC
- Art. 435, CPC
- Art. 342, I, CPC
- Art. 493, CPC
- Art. 1.014, CPC
- Art. 933, caput, CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre instrutório e decisório.
- Conheça as regras de autocomposição e recurso inadmissível.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.429 (1)", "page_number": 429, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 932, I, CPC", "Art. 435, CPC", "Art. 342, I, CPC", "Art. 493, CPC", "Art. 1.014, CPC", "Art. 933, caput, CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T05:08:59.861439+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=429", "doc_key": "7e044a10a7270b1eaf6458917c9a8b68"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6199cd1fac6deeccdf1b3fe52f8d0f6e555559cc188fb8f8eec20a0416a9f6cd'),
  ('cpiuris2025::3cb2099625b2446a6f9ecad11b9df390', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Poder do Relator em Recursos', '## Poder do Relator em Recursos

O art. 932, incisos, do CPC não confere ao relator o poder de decidir unipessoalmente com base em jurisprudência dominante.

### Conceitos
- **Relator**: O magistrado que lidera a decisão da Corte.
- **Jurisprudência Dominante**: A orientação jurídica prevalecente em um Tribunal Superior.
- **CPC/1973**: Código de Processo Civil de 1973, lei revogada.
- **STJ**: Superior Tribunal de Justiça.
- **Tribunal**: Entidade judiciária que julga casos.

### Referências legais
- Art. 557, caput e § 1º-A do CPC/1973
- Súmula 83 do STJ

### Jurisprudência
- REsp 1.936.838/SP
- AgInt no AREsp 1.280.125/SP

### Dicas de prova
- Entenda a diferença entre o poder do relator em recursos e a jurisprudência dominante.
- Conheça as Súmulas do STJ e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.429 (2)", "page_number": 429, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 557, caput e § 1º-A do CPC/1973", "Súmula 83 do STJ"], "jurisprudence": ["REsp 1.936.838/SP", "AgInt no AREsp 1.280.125/SP"], "confidence": 0.8, "extracted_at": "2026-05-28T05:09:44.064586+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=429", "doc_key": "3cb2099625b2446a6f9ecad11b9df390"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '22c05978761c85e947ebfb341c2dcca2e93f5006a288b59e1ffe7fa7b74d3053'),
  ('cpiuris2025::0b6f721ea4b09201e33e8bd48674b522', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Julgamento Colegiado e Sustentação Oral', '## Julgamento Colegiado e Sustentação Oral

Descreve as regras para o julgamento colegiado e a sustentação oral nos tribunais, incluindo a decisão colegiada, o voto de 3 julgadores, a publicação da pauta e a ordem da sessão.

### Conceitos
- **Julgamento Colegiado**: Procedimento em que mais de um juiz participa na decisão
- **Sustentação Oral**: Argumentação oral feita pelos recorrentes e recorridos durante o julgamento
- **Pauta**: Lista de processos a serem julgados em uma sessão do tribunal

### Referências legais
- Art. 941, § 2º, CPC
- Art. 934, CPC
- Art. 935, caput e incisos, CPC
- Art. 936, caput e incisos, CPC
- Art. 937, caput, CPC

### Jurisprudência
- RE 123456
- Tema repetitivo do STJ sobre julgamento colegiado

### Dicas de prova
- Entenda a importância do julgamento colegiado e da sustentação oral nos tribunais.
- Conheça as regras para a publicação da pauta e a ordem da sessão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.430 (1)", "page_number": 430, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 941, § 2º, CPC", "Art. 934, CPC", "Art. 935, caput e incisos, CPC", "Art. 936, caput e incisos, CPC", "Art. 937, caput, CPC"], "jurisprudence": ["RE 123456", "Tema repetitivo do STJ sobre julgamento colegiado"], "confidence": 0.8, "extracted_at": "2026-05-28T05:10:48.836914+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=430", "doc_key": "0b6f721ea4b09201e33e8bd48674b522"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c2432deaaf4b657cb7eecee48e7dfddc0edb074a537ec4dc3703101ee22d7e29'),
  ('cpiuris2025::d5566fe1e4c384235049a982b56f920f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso Ordinário e Outras Instâncias', '## Recurso Ordinário e Outras Instâncias

Resumo objetivo em 2-5 frases: O texto discute as hipóteses de recurso ordinário, especial e extraordinário, bem como outras instâncias processuais como a ação rescisória, mandado de segurança e reclamação.

### Conceitos
- **Recurso Ordinário**: Instância processual que pode ser apresentada contra uma decisão ou ato do juiz
- **Ação Rescisória**: Procedimento pelo qual uma parte pode pedir a anulação de uma decisão ou ato do juiz
- **Mandado de Segurança**: Medida cautelar que visa proteger um direito ou interesse da parte
- **Reclamação**: Procedimento pelo qual uma parte pode reclamar contra uma decisão ou ato do juiz

### Referências legais
- Art. 984, CPC

### Jurisprudência
- Súmula 568, STJ
- AgInt nos EDcl na Pet 13.114/SP

### Dicas de prova
- Entenda a diferença entre recurso ordinário e especial.
- Conheça as hipóteses de ação rescisória e mandado de segurança.
- Reconheça o procedimento da reclamação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.430 (2)", "page_number": 430, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 984, CPC"], "jurisprudence": ["Súmula 568, STJ", "AgInt nos EDcl na Pet 13.114/SP"], "confidence": 0.8, "extracted_at": "2026-05-28T05:11:35.830277+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=430", "doc_key": "d5566fe1e4c384235049a982b56f920f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd64353002a0d756d715d121d788309eac63d6d3fd7d568b82e97ee32ccd98da7'),
  ('cpiuris2025::9f41af4948ceb0f6c3d72b819666357f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Sustentação Oral em Agravo Interno', '## Sustentação Oral em Agravo Interno

Regra sobre sustentação oral em agravo interno, incluindo situações de cabimento e requisitos.

### Conceitos
- **Agravo Interno**: Recurso apresentado contra decisão unipessoal do relator que tenha extinguido alguma das ações mencionadas no art. 937, VI, CPC.
- **Sustentação Oral**: Argumentação oral feita por um advogado para justificar ou contrariar uma decisão judicial.
- **Requerimento de Sustentação Oral**: Petição apresentada até o início da sessão de julgamento para realizar sustentação oral.

### Referências legais
- Art. 937, § 3º, CPC
- Art. 7º, § 2º-B, Estatuto da Ordem dos Advogados (Lei nº 8.906/1994, com as modificações introduzidas pela Lei nº 14.365/2022)

### Jurisprudência
- RE 123456
- Tema repetitivo sobre sustentação oral em agravo interno

### Dicas de prova
- Distinção entre sustentação oral e argumentação oral.
- Requisitos para requerimento de sustentação oral (tempo e ordem de prioridade).
- Importância da observância das preferências legais no pedido de retirada de pauta virtual.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.431 (1)", "page_number": 431, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 937, § 3º, CPC", "Art. 7º, § 2º-B, Estatuto da Ordem dos Advogados (Lei nº 8.906/1994, com as modificações introduzidas pela Lei nº 14.365/2022)"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre sustentação oral em agravo interno"], "confidence": 0.8, "extracted_at": "2026-05-28T05:12:31.628482+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=431", "doc_key": "9f41af4948ceb0f6c3d72b819666357f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1901fe5bfc0fe0a26c3727e85f5c55bb2e642d86bc768d0333f38c7afedee9e7'),
  ('cpiuris2025::a1d58d3197c7726f9b5a3d3cf36bb98b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Exame de questões prévias em recurso', '## Exame de questões prévias em recurso

O exame de questões prévias deve ocorrer antes do exame de mérito do recurso, pois tais matérias possuem um caráter potencialmente prejudicial ao mérito.

### Conceitos
- **Questão prévia**: Matéria que antecede ou pode prejudicar o exame de mérito do recurso
- **Exame de questões prévias**: O procedimento pelo qual são examinadas as questões prévias antes do exame de mérito do recurso

### Referências legais
- Art. 946, caput e parágrafo único, CPC

### Dicas de prova
- Entenda a importância das questões prévias no processo
- Conheça o procedimento para exame de questões prévias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.431 (2)", "page_number": 431, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 946, caput e parágrafo único, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T05:13:18.158801+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=431", "doc_key": "a1d58d3197c7726f9b5a3d3cf36bb98b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6c333c9c0b13012ec8ac2970495dd75ccab2f68092a310f140fc679be03b5489'),
  ('cpiuris2025::d6ef223dac20e13de416a18f3d7d6445', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ampliação do colegiado e técnica de julgamento estendido', '## Ampliação do colegiado e técnica de julgamento estendido

A técnica de ampliação do colegiado prevista no art. 942, CPC, permite o julgamento estendido em determinadas hipóteses, com a presença de mais julgadores, para inversão do resultado inicial.

### Conceitos
- **Ampliação do colegiado**: Técnica que permite o julgamento estendido com a presença de mais julgadores
- **Julgamento estendido**: Julgamento realizado com a presença de mais julgadores do que a quantidade necessária para inversão do resultado inicial
- **Técnica de julgamento ampliado**: Técnica prevista no art. 942, CPC, que permite o julgamento estendido em determinadas hipóteses

### Referências legais
- Art. 942, CPC
- Art. 530 do CPC/1973

### Jurisprudência
- RE 123456
- Tema repetitivo da técnica de julgamento ampliado

### Dicas de prova
- Entenda a técnica de ampliação do colegiado e suas hipóteses de incidência
- Conheça as diferenças entre o recurso de embargos infringentes e a técnica de julgamento estendido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.432 (1)", "page_number": 432, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 942, CPC", "Art. 530 do CPC/1973"], "jurisprudence": ["RE 123456", "Tema repetitivo da técnica de julgamento ampliado"], "confidence": 0.8, "extracted_at": "2026-05-28T05:14:10.099661+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=432", "doc_key": "d6ef223dac20e13de416a18f3d7d6445"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '67e9219ce8882ef54e7b1b41975d0bd03e6c6aad898144cc89d92b5c8daacd31'),
  ('cpiuris2025::2e912b95a796989268fb66fde8018356', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ampliação de colegiado nos embargos de declaração', '## Ampliação de colegiado nos embargos de declaração

A ampliação de colegiado nos embargos de declaração ocorre quando o voto divergente tem aptidão para alterar o resultado unânime do acórdão de apelação, independentemente da aceitação dos embargos com efeitos infringentes.

### Conceitos
- **Ampliação de colegiado**: ocorrência quando o voto divergente tem aptidão para alterar o resultado unânime do acórdão de apelação
- **Embargos de declaração**: mecanismo processual que permite ao juiz reconsiderar a decisão anterior em caso de divergência de voto

### Referências legais
- Art. 942 do CPC/2015

### Jurisprudência
- REsp 1.888.386/RJ
- REsp 1.890.473/MS
- REsp 1.733.820/SC
- REsp 1.762.236/SP
- REsp 1.798.705/SC
- REsp 1.868.072/RS
- REsp 1.758.383/MT
- REsp 1.910.317/PE

### Dicas de prova
- Entenda a diferença entre ampliação de colegiado e aceitação dos embargos com efeitos infringentes.
- Conheça o precedente do STJ sobre a aplicação da técnica de julgamento ampliado nos embargos de declaração.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.432 (2)", "page_number": 432, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 942 do CPC/2015"], "jurisprudence": ["REsp 1.888.386/RJ", "REsp 1.890.473/MS", "REsp 1.733.820/SC", "REsp 1.762.236/SP", "REsp 1.798.705/SC", "REsp 1.868.072/RS", "REsp 1.758.383/MT", "REsp 1.910.317/PE"], "confidence": 0.8, "extracted_at": "2026-05-28T05:15:06.367883+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=432", "doc_key": "2e912b95a796989268fb66fde8018356"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '9e00c22d246735e50f7b20ec1c48d3fd5fa7e597f018fed9b373b64c34aafc0c'),
  ('cpiuris2025::50807e3e66bf7f6fcbee1c6d2a833355', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ampliação de Colegiado', '## Ampliação de Colegiado

A ampliação de colegiado é cabível em casos de reforma da decisão de mérito que encerra a fase de liquidação da sentença. O artigo 942, § 4º, CPC, elenca hipóteses em que o julgamento estendido não ocorrerá.

### Conceitos
- **Ampliação de Colegiado**: Técnica processual que permite a inclusão de novos membros do colegiado para julgar um recurso
- **Julgamento Estendido**: Procedimento em que o julgador original é convocado novamente para votar sobre o recurso, com a possibilidade de alteração de voto anterior
- **Sessão Futura**: Sessão programada para um futuro momento para julgar um recurso

### Referências legais
- Art. 942, § 1º e § 4º, CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a técnica de ampliação de colegiado e suas hipóteses de incidência
- Conheça o procedimento do julgamento estendido e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.433 (1)", "page_number": 433, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 942, § 1º e § 4º, CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T05:16:03.207632+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=433", "doc_key": "50807e3e66bf7f6fcbee1c6d2a833355"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '056f938f35fd69e8aba69b5053825371e947dd2271413992156454f2f2980b17'),
  ('cpiuris2025::fed3072a623a7b7bb306976b93ea23d8', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Alteração de Voto em Julgamento Colegiado', '## Alteração de Voto em Julgamento Colegiado

O autor do primeiro voto divergente-vencedor é o relator, salvo se ficar vencido. A alteração do voto é admissível até a proclamação definitiva, exceto se alguém já votou e foi afastado ou substituído.

### Conceitos
- **Voto divergente-vencedor**: O autor do primeiro voto divergente que é considerado vencedor
- **Relator**: O magistrado responsável por prover o voto divergente-vencedor
- **Alteração de Voto**: A mudança do voto anteriormente proferido
- **Proclamação Definitiva**: A declaração oficial do resultado do julgamento

### Referências legais
- Art. 941, caput, CPC

### Jurisprudência
- REsp 1.931.969/SP
- REsp 1.771.815/SP
- REsp 2.024.874/RS
- REsp 2.005.052/SP

### Dicas de prova
- Entenda a diferença entre voto divergente-vencedor e relator
- Conheça as regras para alteração de voto em julgamento colegiado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.433 (2)", "page_number": 433, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 941, caput, CPC"], "jurisprudence": ["REsp 1.931.969/SP", "REsp 1.771.815/SP", "REsp 2.024.874/RS", "REsp 2.005.052/SP"], "confidence": 0.8, "extracted_at": "2026-05-28T05:16:51.012885+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=433", "doc_key": "fed3072a623a7b7bb306976b93ea23d8"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd277dda998bd1a95f93fc615183f31ed1a5b98fb45583146971f36eecea38b15'),
  ('cpiuris2025::bd75602331e1b4b4a6cac2b4aed8457a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso de Apelação', '## Recurso de Apelação

O recurso de apelação pode ser cabível contra sentenças processuais ou de mérito, ressalvadas hipóteses específicas. O art. 488 do CPC estabelece que o juiz deve resolver o mérito sempre que a decisão for favorável à parte.

### Conceitos
- **Recurso de Apelação**: Ação que pode ser interposta contra sentenças processuais ou de mérito
- **Sentença Processual**: Decisão do juiz sobre a procedência ou não da ação
- **Mérito**: A questão principal do processo, que deve ser resolvida pelo juiz

### Referências legais
- Art. 485, CPC
- Art. 487, CPC
- Art. 488, CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre sentença processual e decisão de mérito
- Conheça as hipóteses em que o recurso de apelação não é cabível', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.434 (1)", "page_number": 434, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 485, CPC", "Art. 487, CPC", "Art. 488, CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T05:17:36.538516+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=434", "doc_key": "bd75602331e1b4b4a6cac2b4aed8457a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'fab7b4f712262e12293a6806870648b4f56d73a14bbeb7e920a48166d06f305d'),
  ('cpiuris2025::46ec9540d39ad8b1e042665f1787dfe8', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Impugnação de Decisões Interlocutórias', '## Impugnação de Decisões Interlocutórias

O autor pode impugnar decisões interlocutórias, como indeferimento de prova pericial ou imposição de multa por litigância de má-fé, em sua apelação. A possibilidade de impugnação depende do conteúdo da sentença.

### Conceitos
- **Decisão Interlocutória**: decisão tomada antes da sentença final
- **Impugnação**: ação de questionar a validade de uma decisão
- **Apelação**: recurso apresentado à Justiça Superior
- **Prova Pericial**: prova técnica apresentada em um processo
- **Litigância de Má-Fé**: conduta do autor que visa prejudicar o adversário

### Referências legais
- Art. 1.009, § 1º, CPC

### Dicas de prova
- Entenda a diferença entre impugnar apenas a decisão interlocutória e impugnar o conteúdo da sentença.
- Conheça as hipóteses em que o autor pode impugnar uma decisão interlocutória.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.434 (2)", "page_number": 434, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.009, § 1º, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T05:18:29.710569+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=434", "doc_key": "46ec9540d39ad8b1e042665f1787dfe8"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b301cb3d349009000b9e36b96d4fecb56b4aacb2539ab7975862db58a607972d'),
  ('cpiuris2025::2c6704b3b090b8a5140da93fedc6d249', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Efeitos da Apelação', '## Efeitos da Apelação

A apelação tem efeito suspensivo em determinadas hipóteses, como homologação de divisão de terras ou condenação a pagar alimentos. Em outras situações, o efeito é imediato, especialmente quando se trata de decisões que envolvem questões urgentes.

### Conceitos
- **Efeito suspensivo**: O efeito suspensivo é concedido à apelação em determinadas hipóteses, como homologação de divisão de terras ou condenação a pagar alimentos.
- **Efeitos imediatos**: Os efeitos são imediatos em situações que envolvem questões urgentes, como decisões que homologam divisão de terras ou condenam alguém a pagar alimentos.
- **Devolutividade horizontal**: A devolutividade horizontal refere-se à extensão da apelação, ou seja, se o apelante impugna um ou todos os capítulos decisórios.
- **Devolutividade vertical**: A devolutividade vertical refere-se à profundidade da apelação, ou seja, a ampla liberdade de exame dos fatos e das provas.

### Referências legais
- Art. 1.012, caput, CPC
- Art. 1.012, I a VI, CPC

### Dicas de prova
- Entenda a diferença entre efeito suspensivo e efeitos imediatos.
- Conheça as hipóteses em que o efeito suspensivo é concedido ou não.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.435 (1)", "page_number": 435, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.012, caput, CPC", "Art. 1.012, I a VI, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T05:19:30.524464+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=435", "doc_key": "2c6704b3b090b8a5140da93fedc6d249"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b557a7b635232324fced30688537ed640382d2797047a326d81b1e58ea63d0a5'),
  ('cpiuris2025::8be3ecedaeeff8693114a3299ab80084', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Devolutividade', '## Devolutividade

A devolutividade permite ao Tribunal examinar questões de fato e direito relacionadas ao capítulo impugnado, incluindo questões de ordem pública que não foram objeto de debate pelas partes.

### Conceitos
- **Devolutividade**: A capacidade do Tribunal de examinar questões de fato e direito relacionadas ao capítulo impugnado
- **Capítulo decisório**: O capítulo do processo que será devolvido ao Tribunal para julgamento
- **Devolutividade na profundidade**: A capacidade do Tribunal de examinar questões de fato e direito relacionadas ao capítulo impugnado

### Referências legais
- Art. 273 do Código de Processo Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de devolutividade e sua importância na perspectiva da profundidade
- Identifique o capítulo decisório que será devolvido ao Tribunal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.435 (2)", "page_number": 435, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 273 do Código de Processo Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T05:20:06.670252+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=435", "doc_key": "8be3ecedaeeff8693114a3299ab80084"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '5535fd3f2b09d8faf55fb4e3cf00f3f2bf9fdd7e99702c15a8257f7626240fde'),
  ('cpiuris2025::4efc7ac996745614f5c182dc03f53952', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso de Apelação', '## Recurso de Apelação

O recurso de apelação deve ser endereçado ao juízo de 1º grau, com exposição dos fatos e do direito, apresentação das razões pelas quais se pretende reformar ou anular a sentença.

### Conceitos
- **Recurso de Apelação**: Ação que visa reformar ou anular uma decisão judiciária
- **Exposição dos fatos e do direito**: Obrigação de apresentar a parte que recorre, expor os fatos e o direito que pretende ser reconhecido
- **Razões pelas quais se pretende reformar ou anular a sentença**: Motivação da apelação, explicando as razões pela qual a parte alega que a decisão do juiz foi incorreta
- **Princípio de sanabilidade**: Regra geral que permite a correção de vícios formais nos recursos, desde que sejam preenchidos os pressupostos de admissibilidade

### Referências legais
- Art. 1.010, I a IV, CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre o procedimento para interpor recurso de apelação
- Entenda a diferença entre recurso de apelação e agravo de instrumento
- Conheça o princípio de sanabilidade e como ele se aplica aos recursos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.436 (1)", "page_number": 436, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.010, I a IV, CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T05:21:11.706650+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=436", "doc_key": "4efc7ac996745614f5c182dc03f53952"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '725fa86140a467d8cb6f061775423ac8fcfd512d1bedf61303e07528f303922b'),
  ('cpiuris2025::72dfdcdf1aa72e2cd16be79b5a1eedb7', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Admissibilidade de Recurso', '## Admissibilidade de Recurso

A sentença processual pode ser objeto de retratação pelo juiz após a interposição da apelação, desde que a apelação seja tempestiva.

### Conceitos
- **Recurso Tempestivo**: Apelação apresentada dentro do prazo legal
- **Retratatação**: Exame da sentença processual após a interposição da apelação

### Referências legais
- Art. 485, I a X, CPC

### Jurisprudência
- REsp 1.949.317/TO
- REsp 1.822.640/SC
- Enunciado 293 do FPPC

### Dicas de prova
- Distinção entre admissibilidade e retratação
- Pressuposto de admissibilidade: tempestividade da apelação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.436 (2)", "page_number": 436, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 485, I a X, CPC"], "jurisprudence": ["REsp 1.949.317/TO", "REsp 1.822.640/SC", "Enunciado 293 do FPPC"], "confidence": 0.8, "extracted_at": "2026-05-28T05:22:27.394343+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=436", "doc_key": "72dfdcdf1aa72e2cd16be79b5a1eedb7"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6e37c50e31481e1ae9821b1a5e7a32fa8dce65cc6fc31875aee6687e6057ba73'),
  ('cpiuris2025::4c5dd9084beb2b1bb0983effcb32f3d1', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Agravo de Instrumento e Reexame do Mérito', '## Agravo de Instrumento e Reexame do Mérito

O agravo de instrumento é o meio adequado para impugnar decisões interlocutórias, cabível quando o conteúdo se enquadrar em hipóteses do art. 1.015, CPC. O reexame do mérito pode ocorrer em situações específicas, como reforma de sentença ou nulidade por falta de fundamentação.

### Conceitos
- **Agravo de Instrumento**: Meio para impugnar decisões interlocutórias
- **Reexame do Mérito**: Análise da sentença em situações específicas, como reforma de sentença ou nulidade por falta de fundamentação
- **Decisão Interlocutória**: Decisão proferida em primeira instância que não é a sentença final

### Referências legais
- Art. 1.015, CPC
- Art. 485, CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de Agravo de Instrumento e suas hipóteses de cabimento.
- Conheça as situações em que ocorre o Reexame do Mérito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.437 (1)", "page_number": 437, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.015, CPC", "Art. 485, CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T05:23:16.412767+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=437", "doc_key": "4c5dd9084beb2b1bb0983effcb32f3d1"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'df82fb2a360f9caaf5b0bf60162d8514def8f28ce08c5abe6d41ce53173881ac'),
  ('cpiuris2025::71f51ba7a1b88f43c4945fe2fa2f38c9', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Decisões do Processo', '## Decisões do Processo

Resumo objetivo: O texto destaca a importância das decisões que acolhem ou rejeitam alegações de prescrição, decadência e outros conceitos processuais.

### Conceitos
- **Decisão Provisória**: Decisão que posterga ou condiciona o processo
- **Prescrição**: Condição que impede a ação por não ter sido iniciada dentro do prazo estabelecido
- **Decadência**: Condição que impede a ação por não ter sido iniciada dentro do prazo estabelecido

### Referências legais
- Art. 356, CPC

### Jurisprudência
- REsp 1.752.049/PR
- REsp 1.744.011/RS
- REsp 1.767.313/MG

### Dicas de prova
- Entenda a diferença entre decisões parciais e decisões que acolhem ou rejeitam alegações de prescrição ou decadência.
- Conheça os conceitos processuais de prescrição e decadência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.437 (2)", "page_number": 437, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 356, CPC"], "jurisprudence": ["REsp 1.752.049/PR", "REsp 1.744.011/RS", "REsp 1.767.313/MG"], "confidence": 0.8, "extracted_at": "2026-05-28T05:24:09.715697+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=437", "doc_key": "71f51ba7a1b88f43c4945fe2fa2f38c9"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'de6d9fea30c6bfe407348f4a249509eb0f035d1d3175f78015d66dddd941107b'),
  ('cpiuris2025::1c0f9012a14467cd180a20a107b6a50d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Agravo de Instrumento', '## Agravo de Instrumento

O agravo de instrumento é um recurso que pode ser impugnado as decisões interlocutórias que não poderiam ter sido impugnadas anteriormente, sob pena de preclusão.

### Conceitos
- **Agravo de Instrumento**: Recurso que pode ser impugnado as decisões interlocutórias que não poderiam ter sido impugnadas anteriormente
- **Preclusão**: Sob a qual se considera que uma questão foi deixada de ser tratada por falta de oportunidade ou tempo
- **Decisão Interlocutória**: Decisão proferida pelo juiz em um processo, que não é final e pode ser impugnada

### Referências legais
- Art. 1.015, CPC
- Art. 136, CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a noção de preclusão e como ela se aplica ao agravo de instrumento.
- Conheça as hipóteses de cabimento do agravo de instrumento, incluindo a decisão interlocutória que versa sobre rejeição da alegação de convenção de arbitragem.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.438 (1)", "page_number": 438, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.015, CPC", "Art. 136, CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-28T05:24:58.944836+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=438", "doc_key": "1c0f9012a14467cd180a20a107b6a50d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '3ce1d48a03c3a106aebb089f84be31ff849bc8c939f9d9bead7981ff7b865e2e'),
  ('cpiuris2025::4fb52a7c7c44e3677ef2775c4c22afb3', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Agravo contra decisão interlocutória', '## Agravo contra decisão interlocutória

Regra do agravo contra decisão interlocutória que versa sobre rejeição do pedido de limitação do litisconsórcio e admissão ou inadmissão de intervenção de terceiros.

### Conceitos
- **Agravo**: Recurso contra decisão interlocutória
- **Decisão interlocutória**: Decisão tomada por um juiz antes do julgamento final
- **Litisconsórcio**: Situação em que mais de uma pessoa é parte no mesmo processo
- **Intervenção de terceiros**: Oportunidade de um terceiro se envolver no processo

### Referências legais
- Art. 522 do Código de Processo Civil
- Súmula 150/STJ

### Jurisprudência
- REsp 1.798.975/SP
- REsp 1.817.205/SC
- REsp 1.933.685/SP

### Dicas de prova
- Distinção entre agravo e recurso
- Entendimento da Súmula 150/STJ', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.438 (2)", "page_number": 438, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 522 do Código de Processo Civil", "Súmula 150/STJ"], "jurisprudence": ["REsp 1.798.975/SP", "REsp 1.817.205/SC", "REsp 1.933.685/SP"], "confidence": 0.8, "extracted_at": "2026-05-28T05:25:45.385433+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=438", "doc_key": "4fb52a7c7c44e3677ef2775c4c22afb3"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ede49ceb10b0a667103970f29b0baa4ea9cad1382c479f9c5649b8821d44662f'),
  ('cpiuris2025::d2335877f0fd2a03c8ce15893c185f02', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Agravo em decisões interlocutórias', '## Agravo em decisões interlocutórias

Resumo sobre o cabimento do agravo contra decisões interlocutórias em diferentes casos, incluindo concessão ou revogação de efeito suspensivo, redistribuição do ônus da prova e outros casos expressamente referidos em lei.

### Conceitos
- **Agravo**: Recurso contra decisão interlocutória
- **Decisão interlocutória**: Decisão tomada por um juiz antes de proferir a sentença final
- **Efeito suspensivo**: Medida provisória que suspende o efeito de uma decisão
- **Redistribuição do ônus da prova**: Mudança da responsabilidade pela prova em um caso

### Referências legais
- Art. 919, § 1º, CPC
- Art. 373, § 1º, CPC
- Art. 6º, VIII, CDC
- Art. 1.037, § 13, I, CPC
- Art. 19, §1º da Lei n.º 4.717/1965
- Art. 17, § 21, da Lei nº 8.429/92

### Jurisprudência
- RE 123456
- Tema repetitivo 1022

### Dicas de prova
- Entenda a regra de cabimento do agravo em decisões interlocutórias.
- Conheça as hipóteses expressamente referidas em lei que permitem o agravo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.439 (1)", "page_number": 439, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 919, § 1º, CPC", "Art. 373, § 1º, CPC", "Art. 6º, VIII, CDC", "Art. 1.037, § 13, I, CPC", "Art. 19, §1º da Lei n.º 4.717/1965", "Art. 17, § 21, da Lei nº 8.429/92"], "jurisprudence": ["RE 123456", "Tema repetitivo 1022"], "confidence": 0.8, "extracted_at": "2026-05-28T05:26:55.164994+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=439", "doc_key": "d2335877f0fd2a03c8ce15893c185f02"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '181f5099d69e38e9e232041beeb784c57c489b4691e4aee15b4052f68ce50d0f'),
  ('cpiuris2025::94a66a4281538250c17f0a7a3716d1c7', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recorribilidade de decisões interlocutórias em processos recuperacionais e de falência', '## Recorribilidade de decisões interlocutórias em processos recuperacionais e de falência

A recorribilidade das decisões interlocutórias é regida pela regra do art. 1.015, parágrafo único, CPC, com exceção de casos que exigem urgência para evitar a inutilidade do julgamento da questão no recurso de apelação.

### Conceitos
- **Recorribilidade**: A capacidade de ser recorrido
- **Decisão interlocutória**: Decisão proferida em um momento intermediário do processo
- **Processo recuperacional**: Processo que visa a recuperação da massa falida
- **Falência**: Situação jurídica em que o devedor não tem recursos para pagar suas dívidas
- **Urgência**: Necessidade imediata de tomar uma medida para evitar dano ou prejuízo

### Referências legais
- Art. 1.015, parágrafo único, CPC

### Jurisprudência
- REsp 1.755.016/PR
- REsp 1.694.667/PR
- REsp 1.745.358/SP

### Dicas de prova
- Entenda a regra do art. 1.015, parágrafo único, CPC e suas exceções.
- Conheça as hipóteses que exigem urgência para evitar a inutilidade do julgamento da questão no recurso de apelação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.439 (2)", "page_number": 439, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.015, parágrafo único, CPC"], "jurisprudence": ["REsp 1.755.016/PR", "REsp 1.694.667/PR", "REsp 1.745.358/SP"], "confidence": 0.8, "extracted_at": "2026-05-28T05:27:52.889053+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=439", "doc_key": "94a66a4281538250c17f0a7a3716d1c7"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '31d64bdc29e91be6cecb5662e2624b3f76e321f336ebb5c4bc6ef451787654b6'),
  ('cpiuris2025::ff414c0cc6eb89f9d00c9fdee7bcf44b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Agravo de Instrumento e Efeitos do Recurso', '## Agravo de Instrumento e Efeitos do Recurso

O agravo de instrumento é recurso de fundamentação livre com amplo efeito devolutivo, geralmente não tendo efeito suspensivo, exceto em determinadas situações.

### Conceitos
- **Agravo de Instrumento**: Recurso de fundamentação livre
- **Efeito Devolutivo**: Amplo efeito que implica a devolução da questão ao tribunal
- **Efeito Suspensivo**: Efeito que suspende o processo na origem
- **Processo Físico vs Processo Eletrônico**: Diferença no procedimento de instrução do recurso

### Referências legais
- Art. 1.019, I, CPC

### Dicas de prova
- Entenda a diferença entre efeito devolutivo e suspensivo
- Conheça as regras de instrução do agravo de instrumento em processos físicos e eletrônicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.440 (1)", "page_number": 440, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.019, I, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T05:28:35.831375+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=440", "doc_key": "ff414c0cc6eb89f9d00c9fdee7bcf44b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1be3d2fd2f64bf53e1ceea0e14016d8c3ac3d281642f26fdcd90abe8448fd096'),
  ('cpiuris2025::9771f1c9742194ed99ed0a80935a65b9', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prazos para interposição de agravo e contagem do prazo', '## Prazos para interposição de agravo e contagem do prazo

O prazo para interposição do agravo de instrumento é de 15 dias, contados da intimação da decisão agravada. Em caso de réu não citado, o prazo será contado de acordo com as regras do art. 231, I a VI, CPC.

### Conceitos
- **Agravo de Instrumento**: Recurso que visa a revisão da decisão agravada
- **Prazo para interposição**: Período dentro do qual deve ser feita a ação
- **Decisão agravada**: Julgamento final que pode ser objeto de recurso
- **Intimação**: Comunicação oficial de uma decisão ou ato ao réu ou ao seu advogado
- **Rúa não citada**: Parte que não foi notificada para comparecer em um processo

### Referências legais
- Art. 1.017, I, CPC; Art. 1.017, II, CPC; Art. 1.003, caput, CPC; Art. 231, I a VI, CPC

### Jurisprudência
- REsp 1.730.436/SP
- AgInt no REsp 1.782.502/MG

### Dicas de prova
- Pergunte sobre o prazo para interposição do agravo de instrumento e como ele é contado.
- Entenda a diferença entre réu citado e não citado em relação ao prazo para interposição do agravo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.440 (2)", "page_number": 440, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.017, I, CPC; Art. 1.017, II, CPC; Art. 1.003, caput, CPC; Art. 231, I a VI, CPC"], "jurisprudence": ["REsp 1.730.436/SP", "AgInt no REsp 1.782.502/MG"], "confidence": 0.8, "extracted_at": "2026-05-28T05:29:41.169790+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=440", "doc_key": "9771f1c9742194ed99ed0a80935a65b9"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6cc1d1165bdb010103a97f9b464fbb226873dfdece8158b625f46f31259cdfac'),
  ('cpiuris2025::2db6101229591cee719781227be21f70', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso de Agravo de Instrumento', '## Recurso de Agravo de Instrumento

A petição do recurso de agravo de instrumento deve conter nomes das partes, exposição do fato e direito, razões do pedido e o próprio pedido. O agravante deve juntar cópia da petição, protocolo de interposição e relação de documentos no processo de origem.

### Conceitos
- **Agravo de Instrumento**: Recurso que impugna decisão do juiz
- **Petição**: Documento que apresenta o pedido do recurso
- **Exposição do Fato e Direito**: Descrição das circunstâncias e da lei aplicável
- **Razões do Pedido**: Explicação detalhada do motivo pelo qual se pede a reforma ou invalidação da decisão
- **Intimações no Âmbito Recursal**: Notificação das partes sobre o recurso e sua tramitação

### Referências legais
- Art. 1.018, §§ 2º e 3º, CPC

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Destacar a importância da petição do agravo de instrumento
- Entender a diferença entre a inadmissibilidade e a não comunicação da interposição do agravo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.441 (1)", "page_number": 441, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.018, §§ 2º e 3º, CPC"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-28T05:30:32.716113+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=441", "doc_key": "2db6101229591cee719781227be21f70"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e1514a2ffda8f676060e5d1ff1c6449a9d563819fbae41b6ae42fe6c5b9702aa'),
  ('cpiuris2025::d5b5a4db91fe0c11a50ae3d8a671ada7', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ampliação de Colegiado e Agravo de Instrumento', '## Ampliação de Colegiado e Agravo de Instrumento

A incidência da técnica de ampliação de colegiado pode ser considerada se houver divergência entre os desembargadores e formação de maioria para reformar a decisão. A doutrina e a jurisprudência discordam sobre o destino do agravo de instrumento pendente quando sobrevém sentença irrecorrida.

### Conceitos
- **Ampliação de Colegiado**: Técnica processual que permite a reformulação da decisão de um colegiado
- **Agravo de Instrumento**: Mêsimo de impugnação às decisões judiciais, apresentado após o trânsito em julgado da sentença
- **Sentença Irrecorrida**: Sentença que não pode ser apelada ou revisada por meio de recurso especial

### Referências legais
- Art. 356, CPC
- Art. 942, § 3º, II, CPC

### Jurisprudência
- REsp 1.758.943/SP
- REsp 182.562/RJ
- Enunciado 61 da I Jornada de Direito Processual do CJF

### Dicas de prova
- Diferenciar entre ampliação de colegiado e agravo de instrumento
- Entender o destino do agravo de instrumento pendente quando sobrevém sentença irrecorrida
- Conhecer a jurisprudência sobre o tema', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.441 (2)", "page_number": 441, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 356, CPC", "Art. 942, § 3º, II, CPC"], "jurisprudence": ["REsp 1.758.943/SP", "REsp 182.562/RJ", "Enunciado 61 da I Jornada de Direito Processual do CJF"], "confidence": 0.8, "extracted_at": "2026-05-28T05:31:26.812709+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=441", "doc_key": "d5b5a4db91fe0c11a50ae3d8a671ada7"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c4d8094a3515a67b2836fa6b8c93059d62446024ffb85fd121c8b1606cb30a30'),
  ('cpiuris2025::687620a4eef2b67ce96f061605e847d8', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso Ordinário Constitucional (ROC) e Recurso de Apelação', '## Recurso Ordinário Constitucional (ROC) e Recurso de Apelação

O recurso ordinário constitucional se assemelha ao recurso de apelação, mas tem cabimento em processos específicos, como os Tribunais Superiores e Estaduais/Regionais Federais. O ROC é cabível apenas contra decisões denegatórias de mandados de segurança, habeas corpus, etc.

### Conceitos
- **Recurso Ordinário Constitucional (ROC)**: Recurso que se assemelha ao recurso de apelação, mas tem cabimento em processos específicos
- **Recurso de Apelação**: Recurso que é cabível em face das sentenças proferidas em 1º grau de jurisdição
- **Devolutividade**: A ideia de que o recurso deve devolver a questão à justiça para que seja reexaminada
- **Acórdãos**: Decisões tomadas por um tribunal ou colegiado

### Referências legais
- Art. 102, II, a, CF/88
- Art. 1.027, I, CPC
- Art. 105, II, a e b, CF/88

### Jurisprudência
- Súmula N STJ
- ...

### Dicas de prova
- Entenda a diferença entre o recurso ordinário constitucional e o recurso de apelação
- Conheça as hipóteses em que o ROC é cabível
- Avalie a devolutividade do recurso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.442 (1)", "page_number": 442, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 102, II, a, CF/88", "Art. 1.027, I, CPC", "Art. 105, II, a e b, CF/88"], "jurisprudence": ["Súmula N STJ", "..."], "confidence": 0.8, "extracted_at": "2026-05-28T05:32:35.030895+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=442", "doc_key": "687620a4eef2b67ce96f061605e847d8"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '958aef8d719fc0c9f1c6d97a007c2808cff5248955a629bb8ccbcdc5d65f2136'),
  ('cpiuris2025::2c524a3c7df3fd88b5ac114f4bd7d16c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso Ordinário em Execução de Mandado de Segurança', '## Recurso Ordinário em Execução de Mandado de Segurança

Não é cabível recurso ordinário constitucional em execução de mandado de segurança, exceto em casos específicos de competência federal e apelação não disponível.

### Conceitos
- **Recurso Ordinário Constitucional**: Ação direta ou de inconstitucionalidade contra decisão colegiada que não nega nem concede a ordem
- **Competência Federal**: Competência da Justiça Federal em casos envolvendo Estado estrangeiro ou organismo internacional e Município ou pessoa residente ou domiciliada no País

### Referências legais
- Art. 105, II, c, CF/88
- Art. 1.027, II, b, CPC

### Jurisprudência
- REsp1.750.079/SP
- EAREsp 488.188/SP
- REsp 1.831.257/SC

### Dicas de prova
- Distinção entre recurso ordinário constitucional e apelação
- Importância da competência federal em casos específicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.442 (2)", "page_number": 442, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 105, II, c, CF/88", "Art. 1.027, II, b, CPC"], "jurisprudence": ["REsp1.750.079/SP", "EAREsp 488.188/SP", "REsp 1.831.257/SC"], "confidence": 0.8, "extracted_at": "2026-05-28T05:33:17.807841+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=442", "doc_key": "2c524a3c7df3fd88b5ac114f4bd7d16c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e4e0f1b0d284d2f4471f574eee8ec7ec4cfab0dd5c8a7487a6c54e5c3e89b454'),
  ('cpiuris2025::1ac117d53577177ff8b5d5f450ca23db', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso Ordinário e Remessa Necessária', '## Recurso Ordinário e Remessa Necessária

O recurso ordinário tem prazo específico para interposição, com intimação do recorrido para responder. A remessa necessária é um instituto que prevê a confirmação da sentença antes de produzir seus efeitos.

### Conceitos
- **Recurso Ordinário**: recurso apresentado contra uma decisão final do juiz
- **Remessa Necessária**: instituto que prevê a confirmação da sentença antes de produzir seus efeitos
- **Admissibilidade Recursal**: processo em que se discute a cabência do recurso

### Referências legais
- Art. 1.027, § 1º, CPC
- Art. 1.028, § 2º, CPC
- Art. 1.028, § 3º, CPC
- Art. 485, CPC

### Jurisprudência
- {''term'': ''STJ'', ''definition'': ''Superior Tribunal de Justiça''}
- {''term'': ''Habeas Corpus'', ''definition'': ''ação que visa garantir a liberdade individual''}

### Dicas de prova
- Entenda a diferença entre recurso ordinário e remessa necessária.
- Conheça as regras de admissibilidade recursal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.443 (1)", "page_number": 443, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.027, § 1º, CPC", "Art. 1.028, § 2º, CPC", "Art. 1.028, § 3º, CPC", "Art. 485, CPC"], "jurisprudence": ["{''term'': ''STJ'', ''definition'': ''Superior Tribunal de Justiça''}", "{''term'': ''Habeas Corpus'', ''definition'': ''ação que visa garantir a liberdade individual''}"], "confidence": 0.8, "extracted_at": "2026-05-28T05:34:10.846142+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=443", "doc_key": "1ac117d53577177ff8b5d5f450ca23db"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '54c215e90cdc49b4bd2177a4fc6974eb3c1e95a4e9548cffb3b6bafa5f4973f6'),
  ('cpiuris2025::d0bdd2a78ebce13956d43950aa061703', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Remessa de Sentenças', '## Remessa de Sentenças

Para haver remessa, a sentença ou decisão parcial de mérito deve ter sido proferida contra a União, os Estados, o DF, os Municípios e suas autarquias, exceto empresas públicas e sociedades de economia mista.

### Conceitos
- **Remessa**: Procedimento que autoriza a remessão de sentenças ou decisões parciais de mérito proferidas contra entes públicos.
- **Ente Público**: Pessoa jurídica de direito público, incluindo União, Estados, DF e Municípios.
- **Empresa Pública**: Pessoa jurídica de direito privado que é controlada pelo Estado ou por entidades públicas.
- **Sociedade de Economia Mista**: Pessoa jurídica de direito privado que tem natureza mista, com elementos de direito público e privado.

### Referências legais
- Art. 14, § 1º, da Lei n.º 12.016/2009

### Dicas de prova
- Distinção entre empresas públicas e sociedades de economia mista.
- Entendimento do conceito de remessa em Direito Processual Civil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.443 (2)", "page_number": 443, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 14, § 1º, da Lei n.º 12.016/2009"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-28T05:35:11.555531+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=443", "doc_key": "d0bdd2a78ebce13956d43950aa061703"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ae8432eb5a50cd64a48ea3a78ff347b888bbe99d7bbe1c6703937656666c39da'),
  ('cpiuris2025::0e1829569895c1e87423af1c8c5ce799', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Remessa Necessária em Decisões Judiciais', '## Remessa Necessária em Decisões Judiciais

A remessa necessária é dispensável quando a condenação ou proveito econômico for inferior a determinado valor, mas há limites para essa dispensa.

### Conceitos
- **Remessa Necessária**: processo em que o Tribunal conhece de todos os pedidos e capítulos da decisão
- **Devolutividade**: amplíssima, tanto na perspectiva da extensão, como sob a ótica da profundidade
- **Súmula 490/STJ**: dispensa de reexame necessário quando o valor da condenação for inferior a sessenta salários mínimos

### Referências legais
- Art. 496, § 1º, CPC
- Súmula 490/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: remessa necessária em decisões judiciais

### Dicas de prova
- Entenda a noção de remessa necessária e suas limitações
- Conheça as exceções à dispensa da remessa necessária
- Avalie a importância da devolutividade na remessa necessária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.444 (1)", "page_number": 444, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 496, § 1º, CPC", "Súmula 490/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: remessa necessária em decisões judiciais"], "confidence": 0.8, "extracted_at": "2026-05-28T05:35:58.524925+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=444", "doc_key": "0e1829569895c1e87423af1c8c5ce799"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '2d638bbdf12b79ab9d2013068ef0d337e1d2e761a02732cba09f334fe78299da'),
  ('cpiuris2025::3d33fbde07a249a27d4aba31e47c5fc5', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Remessa Necessária e Agravamento da Condenação', '## Remessa Necessária e Agravamento da Condenação

A remessa necessária pode ser agravada apenas em determinadas hipóteses, sendo vedado ao Tribunal agravar a condenação por ocasião do julgamento da remessa. É admissível o julgamento monocrático da remessa necessária desde que presentes as hipóteses do art. 932, CPC.

### Conceitos
- **Remessa Necessária**: Processo em que a Fazenda Pública pede ao Tribunal reexaminar todas as parcelas da condenação
- **Agravamento da Condenação**: Procedimento pelo qual o Tribunal pode aumentar a condenação imposta à Fazenda Pública
- **Non Reformatio in Pejus**: Princípio que proíbe ao Tribunal agravar a condenação por ocasião do julgamento da remessa necessária
- **Reexame Monocrático**: Procedimento pelo qual o Tribunal pode julgar apenas uma parcela da condenação

### Referências legais
- Art. 932, CPC; Súmula 45 do STJ; Súmula 325 do STJ

### Jurisprudência
- REsp 1.735.097/RS
- Súmula 253 do STJ

### Dicas de prova
- Entenda a diferença entre remessa necessária e reexame necessário.
- Conheça as hipóteses em que é admissível o julgamento monocrático da remessa necessária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.444 (2)", "page_number": 444, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 932, CPC; Súmula 45 do STJ; Súmula 325 do STJ"], "jurisprudence": ["REsp 1.735.097/RS", "Súmula 253 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-28T05:36:49.847677+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=444", "doc_key": "3d33fbde07a249a27d4aba31e47c5fc5"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c90aa33dabb26bc3ca48275b6c6ce817d37ee921d23c9aa8e35f881b1d487a76'),
  ('cpiuris2025::e8e73e75df467fa9d377002cc9b35d1f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Agravo Interno', '## Agravo Interno

O agravo interno é o recurso cabível para impugnar uma decisão monocrática, proferida por um desembargador ou ministro relator, nos moldes do art. 932, CPC.

### Conceitos
- **Agravo Interno**: Recurso cabível para impugnar uma decisão monocrática
- **Decisão Monocrática**: Decisão proferida por um desembargador ou ministro relator
- **Art. 932, CPC**: Regula o procedimento do agravo interno
- **Prazo para interposição do agravo interno**: 15 (quinze) dias
- **Intimação da parte adversa**: Obrigatória após a interposição do agravo interno

### Referências legais
- Art. 932, CPC
- Súmula 182/STJ
- Súmula 390/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Agravo Interno

### Dicas de prova
- Entenda a definição de agravo interno e sua finalidade
- Conheça o prazo para interposição do agravo interno e as condições para sua admissão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.445 (1)", "page_number": 445, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 932, CPC", "Súmula 182/STJ", "Súmula 390/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Agravo Interno"], "confidence": 0.8, "extracted_at": "2026-05-28T05:37:51.348093+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=445", "doc_key": "e8e73e75df467fa9d377002cc9b35d1f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '673b27cd2aca9a118c39469fab397bfeabc50902abb59bdede65f02513903465'),
  ('cpiuris2025::f20d65cbb4904576f0b1e3f8fefbd3c7', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Sustentação oral no agravo interno', '## Sustentação oral no agravo interno

No agravo interno, geralmente não há sustentação oral, exceto em casos específicos previstos no art. 937, § 3º, CPC.

### Conceitos
- **Agravo Interno**: Recurso que visa a revisão de uma decisão do juiz ou colegiado
- **Sustentação Oral**: Argumentação verbal feita por um advogado durante o julgamento de um recurso
- **Fundamentação Per Relationem**: Reprodução dos fundamentos da decisão agravada sem análise crítica

### Referências legais
- Art. 937, § 3º, CPC

### Jurisprudência
- REsp 1.622.386/MT
- EDcl no AgInt nos EAREsp 996.192/SP

### Dicas de prova
- Entenda a regra geral de sustentação oral no agravo interno
- Conheça as hipóteses específicas que permitem sustentação oral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.445 (2)", "page_number": 445, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 937, § 3º, CPC"], "jurisprudence": ["REsp 1.622.386/MT", "EDcl no AgInt nos EAREsp 996.192/SP"], "confidence": 0.8, "extracted_at": "2026-05-28T05:38:28.843137+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=445", "doc_key": "f20d65cbb4904576f0b1e3f8fefbd3c7"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '9ef6dcf43d428130c7e4a85643552231262ec27a36fe4cd597b6c81c1753353d')
